/**
 * Desenha as caixas, os besouros e as poças que vivem na simulação.
 * Mantém pools de billboards e as sincroniza com o estado a cada quadro.
 */
import type { Texture } from 'pixi.js';
import { ITEM_ANCHOR, ITEM_ANGLES, ITEM_COLS, ITEM_FRAME, ITEM_PX_PER_METER, MUD_PX_PER_METER } from '@/data/itemSprites';
import type { ItemSystem } from '@/sim/systems/ItemSystem';
import type { Mode7Camera, ProjectedPoint } from '../mode7/Mode7Camera';
import type { BillboardLayer } from './BillboardLayer';
import type { Pose } from './KartView';
import { PropView } from './PropView';

/** Altura em que a caixa de item flutua, em metros. */
const BOX_HEIGHT = 0;

export interface ItemTextures {
  readonly box: Texture;
  readonly beetle: Texture;
  readonly mud: Texture;
}

export class ItemsView {
  private readonly boxes: PropView[] = [];
  private readonly beetles: PropView[] = [];
  private readonly puddles: PropView[] = [];
  private readonly pose: Pose = { x: 0, y: 0, angle: 0, z: 0 };

  constructor(
    private readonly textures: ItemTextures,
    private readonly layer: BillboardLayer,
  ) {}

  update(
    items: ItemSystem,
    camera: Mode7Camera,
    out: ProjectedPoint,
    width: number,
    height: number,
    dt: number,
  ): void {
    this.syncBoxes(items, camera, out, width, height, dt);
    this.syncBeetles(items, camera, out, width, height);
    this.syncPuddles(items, camera, out, width, height);
  }

  private syncBoxes(
    items: ItemSystem, camera: Mode7Camera, out: ProjectedPoint,
    width: number, height: number, dt: number,
  ): void {
    for (let i = 0; i < items.boxes.length; i++) {
      const box = items.boxes[i]!;
      const view = this.ensure(this.boxes, () =>
        new PropView({
          sheet: this.textures.box, angles: ITEM_ANGLES, frameSize: ITEM_FRAME,
          cols: ITEM_COLS, pxPerMeter: ITEM_PX_PER_METER, anchorY: ITEM_ANCHOR, spin: 0.45,
        }),
      i);

      if (box.cooldown > 0) {
        view.hide();
        continue;
      }
      view.advance(dt);
      this.pose.x = box.x;
      this.pose.y = box.y;
      this.pose.angle = 0;
      this.pose.z = BOX_HEIGHT;
      view.update(this.pose, camera, out, width, height);
    }
  }

  private syncBeetles(
    items: ItemSystem, camera: Mode7Camera, out: ProjectedPoint, width: number, height: number,
  ): void {
    for (let i = 0; i < items.projectiles.length; i++) {
      const projectile = items.projectiles[i]!;
      const view = this.ensure(this.beetles, () =>
        new PropView({
          sheet: this.textures.beetle, angles: ITEM_ANGLES, frameSize: ITEM_FRAME,
          cols: ITEM_COLS, pxPerMeter: ITEM_PX_PER_METER, anchorY: ITEM_ANCHOR,
        }),
      i);

      if (!projectile.active) {
        view.hide();
        continue;
      }
      this.pose.x = projectile.x;
      this.pose.y = projectile.y;
      this.pose.angle = projectile.angle;
      this.pose.z = 0;
      view.update(this.pose, camera, out, width, height);
    }
  }

  private syncPuddles(
    items: ItemSystem, camera: Mode7Camera, out: ProjectedPoint, width: number, height: number,
  ): void {
    for (let i = 0; i < items.hazards.length; i++) {
      const hazard = items.hazards[i]!;
      const view = this.ensure(this.puddles, () =>
        new PropView({
          sheet: this.textures.mud, angles: 1, frameSize: 128, cols: 1,
          pxPerMeter: MUD_PX_PER_METER, anchorY: 0.62,
        }),
      i);

      if (!hazard.active) {
        view.hide();
        continue;
      }
      // some aos poucos nos últimos segundos, avisando que vai sumir
      view.setAlpha(Math.min(1, hazard.life / 2.5));
      this.pose.x = hazard.x;
      this.pose.y = hazard.y;
      this.pose.angle = 0;
      this.pose.z = 0;
      view.update(this.pose, camera, out, width, height);
    }
  }

  /** Cria a view sob demanda e a registra na camada, uma única vez. */
  private ensure(pool: PropView[], make: () => PropView, index: number): PropView {
    let view = pool[index];
    if (!view) {
      view = make();
      pool[index] = view;
      this.layer.add(view);
    }
    return view;
  }
}
