/**
 * Lê `track_mask.png` uma única vez e guarda um id de superfície por pixel.
 * A consulta durante a corrida é O(1), sem tocar na GPU. Ver PLAN.md §6.4.
 */
import {
  SURFACES,
  SURFACE_COLORS,
  SURFACE_PROPS,
  type SurfaceName,
  type SurfaceProps,
} from '@/data/TrackData';

const SURFACE_LIST = SURFACES;

export class SurfaceMap {
  private constructor(
    private readonly ids: Uint8Array,
    private readonly size: number,
    private readonly pixelsPerMeter: number,
  ) {}

  /** Mapa de uma superfície só — usado em testes e em pistas de depuração. */
  static uniform(surface: SurfaceName, sizeMeters: number): SurfaceMap {
    const id = SURFACE_LIST.indexOf(surface);
    return new SurfaceMap(new Uint8Array([id < 0 ? 0 : id]), 1, 1 / sizeMeters);
  }

  /** Decodifica a máscara a partir de uma imagem já carregada. */
  static fromImage(image: ImageBitmap | HTMLImageElement, sizeMeters: number): SurfaceMap {
    const size = image.width;
    const canvas = document.createElement('canvas');
    canvas.width = size;
    canvas.height = size;
    const ctx = canvas.getContext('2d', { willReadFrequently: true });
    if (!ctx) throw new Error('SurfaceMap: canvas 2D indisponível');
    ctx.drawImage(image as CanvasImageSource, 0, 0);
    const pixels = ctx.getImageData(0, 0, size, size).data;

    const ids = new Uint8Array(size * size);
    // a máscara é gerada sem antialias, então há pouquíssimas cores distintas;
    // o cache transforma a busca pela cor mais próxima em uma consulta direta
    const cache = new Map<number, number>();

    for (let i = 0, p = 0; i < ids.length; i++, p += 4) {
      const key = (pixels[p]! << 16) | (pixels[p + 1]! << 8) | pixels[p + 2]!;
      let id = cache.get(key);
      if (id === undefined) {
        id = nearestSurface(pixels[p]!, pixels[p + 1]!, pixels[p + 2]!);
        cache.set(key, id);
      }
      ids[i] = id;
    }

    return new SurfaceMap(ids, size, size / sizeMeters);
  }

  /** Superfície sob um ponto do mundo, em metros. Fora do mapa conta como água. */
  at(x: number, y: number): SurfaceName {
    const px = (x * this.pixelsPerMeter) | 0;
    const py = (y * this.pixelsPerMeter) | 0;
    if (px < 0 || py < 0 || px >= this.size || py >= this.size) return 'water';
    return SURFACE_LIST[this.ids[py * this.size + px]!]!;
  }

  propsAt(x: number, y: number): SurfaceProps {
    return SURFACE_PROPS[this.at(x, y)];
  }
}

function nearestSurface(r: number, g: number, b: number): number {
  let best = 0;
  let bestDistance = Infinity;
  for (let i = 0; i < SURFACE_LIST.length; i++) {
    const [cr, cg, cb] = SURFACE_COLORS[SURFACE_LIST[i]!];
    const d = (r - cr) ** 2 + (g - cg) ** 2 + (b - cb) ** 2;
    if (d < bestDistance) {
      bestDistance = d;
      best = i;
    }
  }
  return best;
}
