/** Perfis de IA. Nenhum deles trapaceia na física — só pilotam diferente. */
export interface DifficultyProfile {
  readonly id: string;
  readonly name: string;
  /** Multiplica a velocidade-alvo das curvas: abaixo de 1 o bot é cauteloso. */
  readonly paceFactor: number;
  /** Erro aleatório somado ao esterço, em unidades de -1..1. */
  readonly steerNoise: number;
  /** Ajusta a distância de mira: acima de 1 faz traçados mais abertos e suaves. */
  readonly lookaheadScale: number;
  /** Quantos waypoints à frente ele olha para frear. */
  readonly brakeLookahead: number;
  /** 0 = nunca derrapa, 1 = derrapa sempre que dá. */
  readonly driftSkill: number;
}

export const DIFFICULTIES: readonly DifficultyProfile[] = [
  { id: 'easy', name: 'Fácil', paceFactor: 0.82, steerNoise: 0.1, lookaheadScale: 0.92, brakeLookahead: 7, driftSkill: 0.2 },
  { id: 'normal', name: 'Normal', paceFactor: 0.93, steerNoise: 0.055, lookaheadScale: 1.0, brakeLookahead: 8, driftSkill: 0.55 },
  { id: 'hard', name: 'Difícil', paceFactor: 1.0, steerNoise: 0.025, lookaheadScale: 1.06, brakeLookahead: 9, driftSkill: 0.85 },
];

export function difficultyById(id: string): DifficultyProfile {
  return DIFFICULTIES.find((d) => d.id === id) ?? DIFFICULTIES[1]!;
}
