/**
 * Um kart desenhado como billboard: o sprite certo para o ângulo em que o
 * kart está em relação à câmera, posicionado e escalado pela projeção.
 * Ver PLAN.md §5.3.
 */
import { Container, Graphics, Rectangle, Sprite, Texture } from 'pixi.js';
import { smoothstep, TAU } from '@/core/math';
import { KART_ANGLES, KART_FRAME, KART_SHEET_COLS } from '@/data/characters';
import type { Kart } from '@/sim/entities/Kart';
import type { Mode7Camera, ProjectedPoint } from '../mode7/Mode7Camera';
import type { SpineKartView } from './SpineKartView';

/**
 * Até esta distância o kart é desenhado em Spine; além da outra, vira sprite.
 * A faixa entre as duas é a histerese que evita o pisca-pisca na troca.
 */
const SPINE_LOD_NEAR = 55;
const SPINE_LOD_FAR = 68;

/**
 * Billboard mais perto que isto some. A escala cresce com 1/distância: um kart
 * que passa rente à câmera viraria uma mancha cobrindo meia tela. Vale para
 * quem ultrapassa por dentro — o kart do jogador está sempre à distância do
 * rabicho da câmera e nunca entra nesta faixa.
 */
const FADE_NEAR = 2;
const FADE_FAR = 4.5;

/** Pixels por metro usados ao gerar os sprites (tools/art/karts.ts). */
const SHEET_PX_PER_METER = 42;
/** Onde está o ponto de contato com o chão dentro do quadro, normalizado. */
const GROUND_ANCHOR_Y = 0.64;

export interface Pose {
  x: number;
  y: number;
  angle: number;
  z: number;
}

export class KartView {
  /** O que vai para a camada de billboards: sombra no chão + sprite do kart. */
  readonly display = new Container();
  readonly sprite: Sprite;
  /** Profundidade do último quadro — usada para ordenar quem desenha na frente. */
  depth = 0;

  private readonly shadow = new Graphics();
  private bubble: Sprite | null = null;
  private spineView: SpineKartView | null = null;
  private usingSpine = false;
  private readonly frames: Texture[];
  private readonly groundPoint: ProjectedPoint = { sx: 0, sy: 0, depth: 0, pxPerMeter: 0 };
  private currentFrame = -1;
  private lastWidth = 1;
  private lastHeight = 1;
  /** Opacidade própria da view — o fantasma usa menos que 1. */
  private baseAlpha = 1;

  constructor(sheet: Texture) {
    this.frames = sliceSheet(sheet);
    this.sprite = new Sprite(this.frames[0]);
    this.sprite.anchor.set(0.5, GROUND_ANCHOR_Y);
    // a sombra fica no CHÃO: quando o kart salta, ela continua lá embaixo
    this.shadow.ellipse(0, 0, 1.15, 0.4).fill({ color: 0x000000, alpha: 0.28 });
    this.display.addChild(this.shadow, this.sprite);
    this.display.visible = false;
  }

  /** Liga a versão em Spine deste kart, usada de perto. */
  attachSpine(view: SpineKartView): void {
    this.spineView = view;
    // entra entre a sombra e o sprite, para a bolha continuar por cima
    this.display.addChildAt(view.spine, 1);
    view.setVisible(false);
  }

  /** Bolha de escudo desenhada em volta do kart. */
  attachBubble(texture: Texture): void {
    if (this.bubble) return;
    const bubble = new Sprite(texture);
    bubble.anchor.set(0.5, 0.58);
    bubble.visible = false;
    this.bubble = bubble;
    this.display.addChild(bubble);
  }

  /** Opacidade base, preservada pela atenuação de proximidade. */
  setBaseAlpha(alpha: number): void {
    this.baseAlpha = alpha;
  }

  setShield(active: boolean): void {
    if (this.bubble) this.bubble.visible = active;
  }

  update(
    pose: Pose,
    camera: Mode7Camera,
    out: ProjectedPoint,
    screenWidth: number,
    screenHeight: number,
    kart?: Kart,
    dt = 0,
  ): void {
    if (!camera.project(pose.x, pose.y, pose.z, out)) {
      this.display.visible = false;
      this.depth = Infinity;
      return;
    }

    // fora da tela com folga: nem vale pagar o custo de desenhar
    if (out.sx < -0.35 || out.sx > 1.35) {
      this.display.visible = false;
      this.depth = out.depth;
      return;
    }

    // decide entre Spine (perto) e sprite (longe), com histerese
    if (this.spineView && kart) {
      if (this.usingSpine && out.depth > SPINE_LOD_FAR) this.usingSpine = false;
      else if (!this.usingSpine && out.depth < SPINE_LOD_NEAR) this.usingSpine = true;
    } else {
      this.usingSpine = false;
    }

    const nearness = smoothstep(FADE_NEAR, FADE_FAR, out.depth);
    if (nearness <= 0.01) {
      this.display.visible = false;
      this.depth = out.depth;
      return;
    }

    this.lastWidth = screenWidth;
    this.lastHeight = screenHeight;
    this.display.visible = true;
    this.display.alpha = this.baseAlpha * nearness;
    this.sprite.visible = !this.usingSpine;
    this.spineView?.setVisible(this.usingSpine);

    if (this.usingSpine && this.spineView && kart) {
      this.spineView.update(kart, pose, camera, out, screenWidth, screenHeight, dt);
      this.depth = out.depth;
      this.updateShadow(pose, camera, screenWidth, screenHeight);
      this.updateBubble(out);
      return;
    }

    const relative = normalizeAngle(pose.angle - camera.angle);
    const frame = Math.round((relative / TAU) * KART_ANGLES) % KART_ANGLES;
    if (frame !== this.currentFrame) {
      this.currentFrame = frame;
      this.sprite.texture = this.frames[frame]!;
    }

    this.sprite.x = out.sx * screenWidth;
    this.sprite.y = out.sy * screenHeight;
    const scale = out.pxPerMeter / SHEET_PX_PER_METER;
    this.sprite.scale.set(scale);
    this.depth = out.depth;

    this.updateShadow(pose, camera, screenWidth, screenHeight);
    this.updateBubble(out);
  }

  /** Dispara a animação pontual no Spine, quando ele estiver ativo. */
  fire(name: 'boost' | 'hit'): void {
    this.spineView?.fire(name);
  }

  private updateBubble(out: ProjectedPoint): void {
    if (!this.bubble?.visible) return;
    this.bubble.position.set(out.sx * this.lastWidth, out.sy * this.lastHeight - out.pxPerMeter * 0.55);
    // a bolha envolve um kart de ~2,6 m
    this.bubble.scale.set((out.pxPerMeter * 2.9) / this.bubble.texture.width);
  }

  /** A sombra é projetada no plano, não presa ao sprite. */
  private updateShadow(pose: Pose, camera: Mode7Camera, screenWidth: number, screenHeight: number): void {
    if (!camera.project(pose.x, pose.y, 0, this.groundPoint)) {
      this.shadow.visible = false;
      return;
    }
    // quanto mais alto o kart, menor e mais fraca a sombra
    const height = Math.max(0, pose.z);
    const shrink = 1 / (1 + height * 0.5);
    this.shadow.visible = true;
    this.shadow.x = this.groundPoint.sx * screenWidth;
    this.shadow.y = this.groundPoint.sy * screenHeight;
    this.shadow.scale.set(this.groundPoint.pxPerMeter * shrink);
    this.shadow.alpha = shrink;
  }
}

function normalizeAngle(a: number): number {
  const x = a % TAU;
  return x < 0 ? x + TAU : x;
}

function sliceSheet(sheet: Texture): Texture[] {
  const frames: Texture[] = [];
  for (let i = 0; i < KART_ANGLES; i++) {
    const col = i % KART_SHEET_COLS;
    const row = Math.floor(i / KART_SHEET_COLS);
    frames.push(
      new Texture({
        source: sheet.source,
        frame: new Rectangle(col * KART_FRAME, row * KART_FRAME, KART_FRAME, KART_FRAME),
      }),
    );
  }
  return frames;
}
