/**
 * Áudio do jogo. Todos os sons são sintetizados por código (PLAN.md §2.1) e
 * chegam aqui como um audio sprite mais três loops em arquivos próprios.
 *
 * Os efeitos usam Web Audio (`html5: false`) porque precisamos de `rate()` e
 * de latência baixa; a música usa HTML5 para transmitir sem travar o load.
 */
import gsap from 'gsap';
import { Howl, Howler } from 'howler';
import { clamp } from '@/core/math';
import type { AudioSettings } from '@/data/settings';
import { assetUrl } from '@/app/assets';
import { LOOP_NAMES, type LoopName, type SfxName } from './sfx';

interface SpriteFile {
  sprite: Record<string, [number, number]>;
}

/** Faixa de variação do tom do motor: 1 = parado, este valor = na máxima. */
const ENGINE_MAX_RATE = 2.35;
const ENGINE_MIN_RATE = 0.55;

export class AudioBus {
  private settings: AudioSettings = { master: 0.8, music: 0.6, sfx: 0.9, muteOnBlur: true };

  private sprite: Howl | null = null;
  private readonly loops = new Map<LoopName, Howl>();
  private readonly loopIds = new Map<LoopName, number>();
  private readonly loopLevels = new Map<LoopName, number>();
  private music: Howl | null = null;
  private musicTheme: string | null = null;

  /** Abaixamento temporário da música, 0 a 1. Animado por GSAP. */
  private readonly duckState = { amount: 0 };
  private muted = false;
  private ready = false;

  async load(): Promise<void> {
    const spriteMap = (await fetch(assetUrl('audio/sfx.json')).then((r) => r.json())) as SpriteFile;

    this.sprite = new Howl({
      src: [assetUrl('audio/sfx.webm'), assetUrl('audio/sfx.ogg')],
      sprite: spriteMap.sprite,
      html5: false,
      preload: true,
    });

    for (const name of LOOP_NAMES) {
      this.loops.set(
        name,
        new Howl({
          src: [assetUrl(`audio/${name}.webm`), assetUrl(`audio/${name}.ogg`)],
          loop: true,
          html5: false,
          volume: 0,
          preload: true,
        }),
      );
      this.loopLevels.set(name, 0);
    }

    this.ready = true;
    this.applySettings(this.settings);
  }

  /** Libera o áudio na primeira interação — exigência de autoplay. */
  unlock(): void {
    const context = Howler.ctx as AudioContext | undefined;
    if (context && context.state === 'suspended') void context.resume();
  }

  applySettings(audio: AudioSettings): void {
    this.settings = audio;
    Howler.volume(this.muted ? 0 : clamp(audio.master, 0, 1));
    this.refreshMusicVolume();
    for (const name of LOOP_NAMES) this.applyLoopVolume(name);
  }

  setMuted(muted: boolean): void {
    this.muted = muted;
    Howler.volume(muted ? 0 : clamp(this.settings.master, 0, 1));
  }

  /* ────────────────────────────── disparos ────────────────────────────── */

  play(name: SfxName, volume = 1, rate = 1): void {
    if (!this.ready || !this.sprite) return;
    const id = this.sprite.play(name);
    this.sprite.volume(clamp(volume * this.settings.sfx, 0, 1), id);
    if (rate !== 1) this.sprite.rate(clamp(rate, 0.5, 4), id);
  }

  /* ─────────────────────────────── loops ─────────────────────────────── */

  startLoops(): void {
    if (!this.ready) return;
    for (const name of LOOP_NAMES) {
      if (this.loopIds.has(name)) continue;
      const howl = this.loops.get(name);
      if (!howl) continue;
      const id = howl.play();
      howl.volume(0, id);
      this.loopIds.set(name, id);
    }
  }

  stopLoops(): void {
    for (const [name, id] of this.loopIds) {
      this.loops.get(name)?.stop(id);
    }
    this.loopIds.clear();
  }

  /**
   * Som do motor: o tom acompanha a velocidade. Dois detalhes importam —
   * a curva não é linear (senão soa elétrico) e o turbo sobe o tom além da
   * velocidade máxima normal.
   */
  setEngine(speedFraction: number, boosting: boolean): void {
    const howl = this.loops.get('engine');
    const id = this.loopIds.get('engine');
    if (!howl || id === undefined) return;

    const f = clamp(speedFraction, 0, 1.3);
    const rate = ENGINE_MIN_RATE + Math.pow(f, 0.78) * (ENGINE_MAX_RATE - ENGINE_MIN_RATE);
    howl.rate(clamp(rate * (boosting ? 1.12 : 1), 0.5, 4), id);
    this.setLoopLevel('engine', 0.32 + f * 0.38);
  }

  setLoopLevel(name: LoopName, level: number): void {
    this.loopLevels.set(name, clamp(level, 0, 1));
    this.applyLoopVolume(name);
  }

  private applyLoopVolume(name: LoopName): void {
    const howl = this.loops.get(name);
    const id = this.loopIds.get(name);
    if (!howl || id === undefined) return;
    howl.volume(clamp((this.loopLevels.get(name) ?? 0) * this.settings.sfx, 0, 1), id);
  }

  /* ─────────────────────────────── música ─────────────────────────────── */

  playMusic(theme: string): void {
    if (this.musicTheme === theme && this.music) return;
    this.music?.stop();
    this.musicTheme = theme;
    this.music = new Howl({
      src: [assetUrl(`audio/music-${theme}.webm`), assetUrl(`audio/music-${theme}.ogg`)],
      loop: true,
      html5: true,
      volume: 0,
    });
    this.music.play();
    this.refreshMusicVolume();
  }

  stopMusic(): void {
    this.music?.stop();
    this.music = null;
    this.musicTheme = null;
  }

  /** Abaixa a música por um instante, para um efeito importante aparecer. */
  duck(amount = 0.6, duration = 0.25, hold = 0.35): void {
    gsap.killTweensOf(this.duckState);
    gsap.to(this.duckState, {
      amount: clamp(amount, 0, 1),
      duration,
      onUpdate: () => this.refreshMusicVolume(),
      onComplete: () => {
        gsap.to(this.duckState, {
          amount: 0,
          duration: 0.5,
          delay: hold,
          onUpdate: () => this.refreshMusicVolume(),
        });
      },
    });
  }

  private refreshMusicVolume(): void {
    this.music?.volume(clamp(this.settings.music * (1 - this.duckState.amount), 0, 1));
  }
}
