/**
 * Persistência versionada em localStorage. Toda chave guarda `{ v, data }`;
 * ao ler, migrações levam versões antigas até a atual. Ver PLAN.md §8.3.
 */
export type Migration<T> = (old: unknown, fromVersion: number) => T;

export interface StoreOptions<T> {
  readonly key: string;
  readonly version: number;
  readonly fallback: () => T;
  readonly migrate?: Migration<T>;
}

interface Envelope {
  v: number;
  data: unknown;
}

export class Store<T> {
  private cache: T | null = null;

  constructor(private readonly options: StoreOptions<T>) {}

  get(): T {
    if (this.cache !== null) return this.cache;
    this.cache = this.read();
    return this.cache;
  }

  set(value: T): void {
    this.cache = value;
    try {
      const envelope: Envelope = { v: this.options.version, data: value };
      localStorage.setItem(this.options.key, JSON.stringify(envelope));
    } catch {
      // modo privado, cota cheia: o jogo continua, só não lembra
    }
  }

  /** Atualiza em cima do valor atual e salva. */
  update(fn: (current: T) => T): T {
    const next = fn(this.get());
    this.set(next);
    return next;
  }

  reset(): T {
    const value = this.options.fallback();
    this.set(value);
    return value;
  }

  private read(): T {
    let raw: string | null = null;
    try {
      raw = localStorage.getItem(this.options.key);
    } catch {
      return this.options.fallback();
    }
    if (!raw) return this.options.fallback();

    try {
      const envelope = JSON.parse(raw) as Envelope;
      if (envelope.v === this.options.version) return envelope.data as T;
      if (this.options.migrate) return this.options.migrate(envelope.data, envelope.v);
      return this.options.fallback();
    } catch {
      return this.options.fallback();
    }
  }
}
