/**
 * Mapeamento de teclas. WASD e setas ficam ativos ao MESMO tempo — não é
 * "um ou outro". Tudo remapeável pelo menu de configurações (PLAN.md §8.3).
 */
export interface KeyBindings {
  left: string[];
  right: string[];
  accelerate: string[];
  brake: string[];
  drift: string[];
  item: string[];
  respawn: string[];
  pause: string[];
}

export const DEFAULT_KEY_BINDINGS: KeyBindings = {
  left: ['KeyA', 'ArrowLeft'],
  right: ['KeyD', 'ArrowRight'],
  accelerate: ['KeyW', 'ArrowUp'],
  brake: ['KeyS', 'ArrowDown'],
  drift: ['Space'],
  item: ['ShiftLeft', 'ShiftRight', 'ControlLeft'],
  respawn: ['KeyR'],
  pause: ['Escape'],
};

export function cloneBindings(bindings: KeyBindings): KeyBindings {
  return {
    left: [...bindings.left],
    right: [...bindings.right],
    accelerate: [...bindings.accelerate],
    brake: [...bindings.brake],
    drift: [...bindings.drift],
    item: [...bindings.item],
    respawn: [...bindings.respawn],
    pause: [...bindings.pause],
  };
}

/** Devolve a ação já mapeada para uma tecla, ou null. */
export function actionForKey(bindings: KeyBindings, code: string): keyof KeyBindings | null {
  for (const action of Object.keys(bindings) as (keyof KeyBindings)[]) {
    if (bindings[action].includes(code)) return action;
  }
  return null;
}
