/**
 * Pilotagem arcade por cima do Box2D. O Planck resolve colisão e contato;
 * a "sensação" de kart vem das forças que aplicamos aqui. Ver PLAN.md §6.2.
 *
 * A ordem importa: aderência lateral → motor/freio → arrasto → esterço.
 */
import { Vec2 } from 'planck';
import { clamp, moveToward } from '@/core/math';
import { ITEM_TUNING } from '@/data/items';
import { KART, RAMP } from '@/data/tuning';
import type { SurfaceProps } from '@/data/TrackData';
import type { InputFrame } from '@/input/InputFrame';
import { DriftSide, type Kart } from '../entities/Kart';

const force = new Vec2(0, 0);
const impulse = new Vec2(0, 0);

export function driveKart(kart: Kart, input: InputFrame, surface: SurfaceProps, dt: number): void {
  const body = kart.body;
  const mass = body.getMass();
  const angle = body.getAngle();
  const fx = Math.cos(angle);
  const fy = Math.sin(angle);
  // direita do kart na tela (mundo com Y para baixo)
  const rx = -fy;
  const ry = fx;

  const velocity = body.getLinearVelocity();
  const forwardSpeed = velocity.x * fx + velocity.y * fy;
  const lateralSpeed = velocity.x * rx + velocity.y * ry;
  kart.speed = forwardSpeed;
  kart.lateralSpeed = lateralSpeed;

  // rodando, o jogador não manda em nada: o giro é imposto pelo SpinOutSystem
  if (kart.spinning) {
    kart.steer = 0;
    kart.driftSide = DriftSide.None;
    applyLateralGrip(kart, surface, lateralSpeed, forwardSpeed, rx, ry, mass, dt);
    applyDrag(kart, surface, velocity);
    return;
  }

  updateSteer(kart, input, dt);
  updateDrift(kart, input, forwardSpeed, dt);
  updateBoost(kart, dt);

  applyLateralGrip(kart, surface, lateralSpeed, forwardSpeed, rx, ry, mass, dt);
  applyEngine(kart, input, surface, forwardSpeed, fx, fy);
  applyDrag(kart, surface, velocity);
  applySteering(kart, forwardSpeed, dt);
}

/**
 * Esterço digital (teclado) vira analógico por uma rampa: sem isso o kart
 * pula de 0 a 100% num quadro e fica impossível de controlar fino.
 */
function updateSteer(kart: Kart, input: InputFrame, dt: number): void {
  const target = clamp(input.steer, -1, 1);
  const rate = target === 0 ? KART.steerReturn : KART.steerRamp;
  kart.steer = moveToward(kart.steer, target, rate * dt);
}

function updateDrift(kart: Kart, input: InputFrame, forwardSpeed: number, dt: number): void {
  const fast = forwardSpeed > KART.driftMinSpeed;
  const turning = Math.abs(kart.steer) > 0.25;

  if (kart.driftSide === DriftSide.None) {
    if (input.drift && fast && turning) {
      kart.driftSide = kart.steer > 0 ? DriftSide.Right : DriftSide.Left;
      kart.driftCharge = 0;
      kart.driftStage = -1;
    }
    return;
  }

  const tooSlow = forwardSpeed < KART.driftMinSpeed * 0.6;
  if (!input.drift || tooSlow) {
    // soltar o botão cobra a carga; perder velocidade cancela sem prêmio
    if (!tooSlow) releaseDrift(kart);
    kart.driftSide = DriftSide.None;
    kart.driftCharge = 0;
    kart.driftStage = -1;
    return;
  }

  kart.driftCharge += dt * Math.max(0.35, Math.abs(kart.steer));
  kart.driftStage = stageFor(kart.driftCharge);
}

/** Índice do maior estágio já alcançado por esta carga, ou -1. */
function stageFor(charge: number): number {
  let stage = -1;
  for (let i = 0; i < KART.boostStages.length; i++) {
    if (charge >= KART.boostStages[i]!.charge) stage = i;
  }
  return stage;
}

function releaseDrift(kart: Kart): void {
  const stage = stageFor(kart.driftCharge);
  if (stage < 0) return;
  const { duration, force } = KART.boostStages[stage]!;
  kart.applyBoost(duration, force);
  kart.pendingBoostStage = stage;
}

function updateBoost(kart: Kart, dt: number): void {
  if (kart.boostTime <= 0) return;
  kart.boostTime -= dt;
  if (kart.boostTime <= 0) {
    kart.boostTime = 0;
    kart.boostForce = 0;
  }
}

/**
 * Mata a velocidade lateral. É isso que diferencia um kart de um disco de
 * hóquei: sem aderência lateral ele desliza para sempre.
 */
function applyLateralGrip(
  kart: Kart,
  surface: SurfaceProps,
  lateralSpeed: number,
  forwardSpeed: number,
  rx: number,
  ry: number,
  mass: number,
  dt: number,
): void {
  const base = kart.drifting ? KART.gripRateDrift : KART.gripRate;
  // no ar não há pneu tocando o chão; na lama, quase nenhuma
  const airFactor = kart.z > 0.01 ? 0 : 1;
  const mudFactor = kart.slipTime > 0 ? 0.25 : 1;
  const rate = base * surface.grip * airFactor * mudFactor;
  // taxa por segundo, não por quadro: o resultado não muda com o framerate
  const factor = 1 - Math.exp(-rate * dt);
  let deltaV = -lateralSpeed * factor;

  // teto do ângulo de deriva: o que passar disso é arrancado de uma vez
  if (kart.drifting) {
    const limit = Math.abs(forwardSpeed) * KART.maxDriftSlip;
    const after = lateralSpeed + deltaV;
    if (Math.abs(after) > limit) {
      deltaV -= Math.sign(after) * (Math.abs(after) - limit);
    }
  }
  impulse.set(rx * deltaV * mass, ry * deltaV * mass);
  kart.body.applyLinearImpulse(impulse, kart.body.getWorldCenter(), true);
}

function applyEngine(
  kart: Kart,
  input: InputFrame,
  surface: SurfaceProps,
  forwardSpeed: number,
  fx: number,
  fy: number,
): void {
  let magnitude = 0;
  if (input.throttle > 0) {
    magnitude += KART.engineForce * input.throttle * surface.traction;
  }
  if (kart.boosting) {
    magnitude += kart.boostForce;
  }
  if (kart.slipTime > 0) magnitude *= ITEM_TUNING.mudSpeedKeep;
  if (input.brake > 0 && !kart.boosting) {
    // freia enquanto anda para frente; engata ré quando já está quase parado
    magnitude -= forwardSpeed > 0.5
      ? KART.brakeForce * input.brake
      : KART.reverseForce * input.brake * surface.traction;
  }
  if (magnitude === 0) return;
  force.set(fx * magnitude, fy * magnitude);
  kart.body.applyForceToCenter(force, true);
}

function applyDrag(kart: Kart, surface: SurfaceProps, velocity: { x: number; y: number }): void {
  const speed = Math.hypot(velocity.x, velocity.y);
  if (speed < 0.01) return;
  let quadratic = KART.dragQuadratic;
  if (kart.boosting) quadratic *= KART.boostDragFactor;
  else if (kart.drifting) quadratic *= KART.driftDragFactor;
  const magnitude = (KART.dragLinear * speed + quadratic * speed * speed) * surface.drag;
  force.set((-velocity.x / speed) * magnitude, (-velocity.y / speed) * magnitude);
  kart.body.applyForceToCenter(force, true);
}

/**
 * O esterço define a velocidade angular diretamente, em vez de aplicar torque.
 * É menos "físico" e muito mais controlável — a escolha arcade clássica.
 */
function applySteering(kart: Kart, forwardSpeed: number, dt: number): void {
  const absSpeed = Math.abs(forwardSpeed);
  // parado não se esterça; a direção vai ficando pesada conforme acelera
  const speedFactor = clamp(absSpeed / KART.yawFullSpeed, 0, 1);

  // o raio mínimo vem da aderência disponível: ω = a / v
  const accel = kart.drifting ? KART.cornerAccel * (1 + KART.driftYawBonus) : KART.cornerAccel;
  const fromGrip = absSpeed > 0.5 ? accel / absSpeed : KART.maxYawRate;
  const airFactor = kart.z > 0.01 ? RAMP.airSteer : 1;
  const mudFactor = kart.slipTime > 0 ? 0.45 : 1;
  const maxYaw = Math.min(KART.maxYawRate, fromGrip) * speedFactor * airFactor * mudFactor;

  const direction = forwardSpeed < -0.5 ? -1 : 1;
  const target = kart.steer * maxYaw * direction;
  const current = kart.body.getAngularVelocity();
  kart.body.setAngularVelocity(moveToward(current, target, KART.yawAccel * dt));
}
