/**
 * Os cinco itens. Função de jogo igual à do gênero; aparência e nome nossos —
 * nada de casco, cogumelo ou banana. Ver PLAN.md §2.2 e §2.3.
 */
export const ITEM_KINDS = ['turbo', 'tripleTurbo', 'beetle', 'mud', 'bubble'] as const;
export type ItemKind = (typeof ITEM_KINDS)[number];

export interface ItemDef {
  readonly id: ItemKind;
  readonly name: string;
  /** Quantos usos o item dá ao ser pego. */
  readonly charges: number;
  /**
   * Peso do sorteio por faixa de colocação: o primeiro índice vale para quem
   * lidera e o último para o lanterna. É a "roleta compensatória" do gênero.
   */
  readonly weights: readonly number[];
}

export const ITEMS: Record<ItemKind, ItemDef> = {
  turbo: { id: 'turbo', name: 'Turbina', charges: 1, weights: [40, 32, 24, 16, 10, 6, 4, 2] },
  tripleTurbo: { id: 'tripleTurbo', name: 'Turbina Tripla', charges: 3, weights: [2, 6, 12, 18, 22, 26, 30, 34] },
  beetle: { id: 'beetle', name: 'Besouro-bomba', charges: 1, weights: [8, 16, 24, 30, 32, 32, 30, 26] },
  mud: { id: 'mud', name: 'Poça de Lama', charges: 1, weights: [36, 30, 24, 18, 14, 10, 8, 6] },
  bubble: { id: 'bubble', name: 'Bolha', charges: 1, weights: [14, 16, 16, 18, 22, 26, 28, 32] },
};

/** Pesos de todos os itens para quem está em `position` (1 = líder). */
export function weightsForPosition(position: number, gridSize: number): number[] {
  const slots = 8;
  // mapeia a colocação para um dos oito degraus da tabela de pesos
  const index = gridSize <= 1
    ? 0
    : Math.min(slots - 1, Math.round(((position - 1) / (gridSize - 1)) * (slots - 1)));
  return ITEM_KINDS.map((kind) => ITEMS[kind].weights[index] ?? 1);
}

