/**
 * O elenco. Oito animais brasileiros escolhidos por SILHUETA: a 60 metros de
 * distância o kart tem poucos pixels, e é o contorno que diferencia um do
 * outro. Ver PLAN.md §2.3.
 *
 * Na v1 os atributos são todos 1.0 — a diferença é puramente visual. Mexer
 * nestes números depois diferencia o desempenho sem tocar em código.
 */

export type EarStyle = 'round' | 'tall' | 'crest' | 'beak' | 'none' | 'fin';

export interface CharacterDef {
  readonly id: string;
  readonly name: string;
  /** Cor do chassi e detalhe — o que se lê de longe. */
  readonly kart: string;
  readonly accent: string;
  /** Pelo/pena do piloto. */
  readonly fur: string;
  readonly furAlt: string;
  /** Caixa da cabeça, em metros: largura, altura, profundidade. */
  readonly head: readonly [number, number, number];
  readonly ears: EarStyle;
  /** Focinho/bico: comprimento e altura em metros, ou null. */
  readonly snout: readonly [number, number] | null;
  readonly topSpeed: number;
  readonly acceleration: number;
  readonly grip: number;
}

