/**
 * Dono do canvas: cria a Application do Pixi, mantém o tamanho em dia e
 * decide quando pedir para o jogador girar o celular. Ver PLAN.md §9.
 */
import { Application, Container } from 'pixi.js';
import { Emitter } from '@/core/Emitter';

/** Teto da densidade de pixels — acima disso o ganho visual não paga o custo. */
const MAX_RESOLUTION = 2;
/** Abaixo desta proporção consideramos o aparelho "em pé". */
const PORTRAIT_RATIO = 1;

export type StageEvents = {
  resize: { width: number; height: number };
  orientation: { portrait: boolean };
};

export class Stage {
  readonly events = new Emitter<StageEvents>();
  readonly root = new Container();

  app!: Application;
  width = 0;
  height = 0;
  portrait = false;

  private host!: HTMLElement;
  private rotateEl: HTMLElement | null = null;
  private resizeTimer = 0;

  async init(host: HTMLElement): Promise<void> {
    this.host = host;
    this.rotateEl = document.getElementById('rotate');

    this.app = new Application();
    await this.app.init({
      // WebGL fixo na v1: o shader do Mode 7 existe só em GLSL (PLAN.md §5.4)
      preference: 'webgl',
      antialias: false,
      backgroundColor: 0x0d1b2a,
      resolution: Math.min(window.devicePixelRatio || 1, MAX_RESOLUTION),
      autoDensity: true,
      powerPreference: 'high-performance',
    });

    this.app.stage.addChild(this.root);
    host.appendChild(this.app.canvas);

    const observer = new ResizeObserver(() => this.scheduleResize());
    observer.observe(host);
    window.addEventListener('orientationchange', () => this.scheduleResize());

    this.applyResize();
  }

  /**
   * Pede tela cheia e tenta travar em paisagem. Só funciona dentro de um gesto.
   *
   * O pedido vai no <html>, NÃO no container do canvas: o elemento em tela
   * cheia entra na camada de topo do navegador e passa a cobrir todo o resto
   * do DOM — com o canvas ali, os menus somem atrás dele.
   */
  async requestFullscreen(): Promise<void> {
    try {
      if (!document.fullscreenElement) await document.documentElement.requestFullscreen();
      const orientation = screen.orientation as ScreenOrientation & {
        lock?: (o: string) => Promise<void>;
      };
      await orientation.lock?.('landscape');
    } catch {
      // vários navegadores recusam; não é motivo para quebrar o jogo
    }
  }

  private scheduleResize(): void {
    clearTimeout(this.resizeTimer);
    this.resizeTimer = window.setTimeout(() => this.applyResize(), 100);
  }

  private applyResize(): void {
    const width = this.host.clientWidth || window.innerWidth;
    const height = this.host.clientHeight || window.innerHeight;
    if (width === 0 || height === 0) return;

    this.width = width;
    this.height = height;
    this.app.renderer.resize(width, height);

    const portrait = width / height < PORTRAIT_RATIO;
    if (portrait !== this.portrait) {
      this.portrait = portrait;
      this.rotateEl?.classList.toggle('show', portrait);
      this.events.emit('orientation', { portrait });
    }

    this.events.emit('resize', { width, height });
  }
}
