/**
 * A simulação anda a 60 Hz; a tela pode andar a 144. A pose desenhada é a
 * interpolação entre os dois últimos estados — sem isso o kart treme.
 * Ver PLAN.md §3.
 */
import { lerp, lerpAngle } from '@/core/math';
import type { Kart } from '@/sim/entities/Kart';
import type { Pose } from './billboards/KartView';

export function poseAt(kart: Kart, alpha: number, out: Pose): Pose {
  out.x = lerp(kart.prevX, kart.x, alpha);
  out.y = lerp(kart.prevY, kart.y, alpha);
  out.angle = lerpAngle(kart.prevAngle, kart.angle, alpha);
  out.z = lerp(kart.prevZ, kart.z, alpha);
  return out;
}

export function emptyPose(): Pose {
  return { x: 0, y: 0, angle: 0, z: 0 };
}
