/** Carregamento dos assets gerados por `npm run assets`. */
import { Assets, type Texture } from 'pixi.js';
// o import registra os carregadores de .atlas e de esqueleto no Pixi Assets
import { Spine } from '@esotericsoftware/spine-pixi-v8';
import { CHARACTERS } from '@/data/characters';
import type { TrackData } from '@/data/TrackData';
import { SurfaceMap } from '@/sim/physics/SurfaceMap';

export function assetUrl(path: string): string {
  return `${import.meta.env.BASE_URL}assets/${path}`;
}

export interface TrackBundle {
  readonly data: TrackData;
  readonly texture: Texture;
  readonly sky: Texture;
  readonly surfaces: SurfaceMap;
}

export async function loadTrack(id: string): Promise<TrackBundle> {
  const base = `tracks/${id}`;
  const [data, texture, sky, maskImage] = await Promise.all([
    fetch(assetUrl(`${base}/track.json`)).then((r) => r.json() as Promise<TrackData>),
    Assets.load<Texture>(assetUrl(`${base}/track.png`)),
    Assets.load<Texture>(assetUrl(`${base}/sky.png`)),
    loadImageBitmap(assetUrl(`${base}/track_mask.png`)),
  ]);

  const surfaces = SurfaceMap.fromImage(maskImage, data.sizeMeters);
  maskImage.close();
  return { data, texture, sky, surfaces };
}

export interface ItemAssets {
  readonly box: Texture;
  readonly beetle: Texture;
  readonly mud: Texture;
  readonly bubble: Texture;
  readonly icons: Texture;
}

export async function loadItemAssets(): Promise<ItemAssets> {
  const [box, beetle, mud, bubble, icons] = await Promise.all([
    Assets.load<Texture>(assetUrl('items/itembox.png')),
    Assets.load<Texture>(assetUrl('items/beetle.png')),
    Assets.load<Texture>(assetUrl('items/mud.png')),
    Assets.load<Texture>(assetUrl('items/bubble.png')),
    Assets.load<Texture>(assetUrl('items/icons.png')),
  ]);
  return { box, beetle, mud, bubble, icons };
}

export interface ParticleAssets {
  readonly smoke: Texture;
  readonly spark: Texture;
}

export async function loadParticles(): Promise<ParticleAssets> {
  const [smoke, spark] = await Promise.all([
    Assets.load<Texture>(assetUrl('fx/smoke.png')),
    Assets.load<Texture>(assetUrl('fx/spark.png')),
  ]);
  return { smoke, spark };
}

/**
 * Registra e carrega os esqueletos Spine. `Spine.from` trabalha com apelidos
 * de asset, então cada personagem ganha dois: o JSON e o atlas.
 */
export async function loadSpineKarts(): Promise<Set<string>> {
  const aliases: string[] = [];
  for (const character of CHARACTERS) {
    const skeleton = `spine-${character.id}-skel`;
    const atlas = `spine-${character.id}-atlas`;
    Assets.add({ alias: skeleton, src: assetUrl(`spine/kart-${character.id}.json`) });
    Assets.add({ alias: atlas, src: assetUrl(`spine/kart-${character.id}.atlas`) });
    aliases.push(skeleton, atlas);
  }
  await Assets.load(aliases);
  return new Set(CHARACTERS.map((c) => c.id));
}

/** Cria uma instância Spine para um personagem já carregado. */
export function makeSpineKart(characterId: string): Spine {
  return Spine.from({
    skeleton: `spine-${characterId}-skel`,
    atlas: `spine-${characterId}-atlas`,
    autoUpdate: false,
  });
}

export function loadDetail(): Promise<Texture> {
  return Assets.load<Texture>(assetUrl('detail.png'));
}

export async function loadKartSheets(): Promise<Map<string, Texture>> {
  const entries = await Promise.all(
    CHARACTERS.map(async (c) => [c.id, await Assets.load<Texture>(assetUrl(`karts/${c.id}.png`))] as const),
  );
  return new Map(entries);
}

async function loadImageBitmap(url: string): Promise<ImageBitmap> {
  const response = await fetch(url);
  if (!response.ok) throw new Error(`falha ao carregar ${url}: ${response.status}`);
  return createImageBitmap(await response.blob());
}
