/**
 * Loop único do jogo. Um só `requestAnimationFrame` manda em tudo, nesta
 * ordem: simulação (passo fixo) → GSAP → render. Ver PLAN.md §11.
 *
 * O passo fixo é o que torna a física reproduzível; o render interpola entre
 * os dois últimos estados para não tremer quando o monitor é de 144 Hz.
 */
import gsap from 'gsap';

/** Passo da simulação, em segundos. */
export const FIXED_DT = 1 / 60;
/** Teto de passos por quadro — evita a espiral da morte depois de um engasgo. */
const MAX_STEPS = 5;
/** Maior salto de tempo aceito entre quadros, em segundos. */
const MAX_FRAME = 0.25;

export interface LoopStats {
  /** Milissegundos gastos na simulação no último quadro. */
  simMs: number;
  /** Milissegundos gastos no render no último quadro. */
  renderMs: number;
  fps: number;
  steps: number;
}

export class Loop {
  readonly stats: LoopStats = { simMs: 0, renderMs: 0, fps: 0, steps: 0 };

  private accumulator = 0;
  private lastTime = 0;
  private running = false;
  private frameHandle = 0;
  private fpsAccum = 0;
  private fpsFrames = 0;
  /** Intervalo mínimo entre quadros desenhados, em segundos. 0 = sem limite. */
  private minFrameTime = 0;
  private sinceRender = 0;

  constructor(
    private readonly onFixed: (dt: number) => void,
    private readonly onRender: (alpha: number, dt: number) => void,
  ) {
    // GSAP sai do próprio rAF: quem dá o tempo a ele somos nós, logo após a
    // simulação. Sem isso haveria dois rAF e ordem imprevisível.
    gsap.ticker.remove(gsap.updateRoot);
    gsap.ticker.lagSmoothing(0);
  }

  start(): void {
    if (this.running) return;
    this.running = true;
    this.lastTime = performance.now();
    this.frameHandle = requestAnimationFrame(this.tick);
  }

  stop(): void {
    this.running = false;
    cancelAnimationFrame(this.frameHandle);
  }

  /** Limita os quadros desenhados. A simulação continua a 60 Hz. */
  setFpsCap(cap: number): void {
    this.minFrameTime = cap > 0 ? 1 / cap - 0.001 : 0;
  }

  /** Zera o acumulador: use ao voltar de pausa, para não disparar vários passos. */
  resync(): void {
    this.lastTime = performance.now();
    this.accumulator = 0;
  }

  private tick = (now: number): void => {
    if (!this.running) return;
    this.frameHandle = requestAnimationFrame(this.tick);

    const frame = Math.min((now - this.lastTime) / 1000, MAX_FRAME);
    this.lastTime = now;
    this.accumulator += frame;

    const simStart = performance.now();
    let steps = 0;
    while (this.accumulator >= FIXED_DT && steps < MAX_STEPS) {
      this.onFixed(FIXED_DT);
      this.accumulator -= FIXED_DT;
      steps++;
    }
    if (steps === MAX_STEPS) this.accumulator = 0;
    const simEnd = performance.now();

    gsap.updateRoot(now / 1000);

    this.sinceRender += frame;
    let renderEnd = simEnd;
    if (this.minFrameTime === 0 || this.sinceRender >= this.minFrameTime) {
      const alpha = this.accumulator / FIXED_DT;
      this.onRender(alpha, this.sinceRender);
      this.sinceRender = 0;
      renderEnd = performance.now();
    }

    this.stats.simMs = simEnd - simStart;
    this.stats.renderMs = renderEnd - simEnd;
    this.stats.steps = steps;

    this.fpsAccum += frame;
    this.fpsFrames++;
    if (this.fpsAccum >= 0.5) {
      this.stats.fps = this.fpsFrames / this.fpsAccum;
      this.fpsAccum = 0;
      this.fpsFrames = 0;
    }
  };
}
