/**
 * Caixas, sorteio e os cinco itens. Tudo determinístico: o sorteio passa pelo
 * `Rng` com semente, nunca por `Math.random`, para que replays e o servidor
 * reproduzam a mesma corrida. Ver PLAN.md §6.6.
 */
import { angleDelta, clamp, moveToward } from '@/core/math';
import type { Rng } from '@/core/rng';
import { ITEMS, ITEM_KINDS, ITEM_TUNING, weightsForPosition, type ItemKind } from '@/data/items';
import type { TrackData } from '@/data/TrackData';
import type { InputFrame } from '@/input/InputFrame';
import type { SimEvent } from '../SimEvents';
import type { Kart } from '../entities/Kart';
import type { Hazard, ItemBoxState, Projectile } from '../entities/Item';
import type { KartProgress } from './LapSystem';

export class ItemSystem {
  readonly boxes: ItemBoxState[];
  readonly projectiles: Projectile[] = [];
  readonly hazards: Hazard[] = [];

  private nextId = 1;

  constructor(track: TrackData) {
    this.boxes = track.itemBoxes.map((box) => ({ x: box.x, y: box.y, cooldown: 0 }));
  }

  update(
    dt: number,
    karts: readonly Kart[],
    progress: readonly (KartProgress | undefined)[],
    inputs: ReadonlyMap<number, InputFrame>,
    rng: Rng,
    events: SimEvent[],
  ): void {
    this.updateBoxes(dt, karts, progress, rng, events);
    this.updateUse(karts, inputs, events);
    this.updateProjectiles(dt, karts, events);
    this.updateHazards(dt, karts, events);
  }

  /* ─────────────────────────────── caixas ─────────────────────────────── */

  private updateBoxes(
    dt: number,
    karts: readonly Kart[],
    progress: readonly (KartProgress | undefined)[],
    rng: Rng,
    events: SimEvent[],
  ): void {
    const radiusSq = ITEM_TUNING.boxRadius ** 2;
    for (const box of this.boxes) {
      if (box.cooldown > 0) {
        box.cooldown -= dt;
        continue;
      }
      for (const kart of karts) {
        if (kart.heldItem) continue;
        if (kart.z > 1) continue;
        const dx = kart.x - box.x;
        const dy = kart.y - box.y;
        if (dx * dx + dy * dy > radiusSq) continue;

        const position = progress[kart.id]?.position ?? karts.length;
        kart.heldItem = { kind: this.roll(rng, position, karts.length), charges: 0 };
        kart.heldItem.charges = ITEMS[kart.heldItem.kind].charges;
        box.cooldown = ITEM_TUNING.boxRespawn;
        events.push({ type: 'itemGet', kartId: kart.id, item: kart.heldItem.kind });
        break;
      }
    }
  }

  /** Roleta compensatória: quem está atrás tem chance de item melhor. */
  private roll(rng: Rng, position: number, gridSize: number): ItemKind {
    const weights = weightsForPosition(position, gridSize);
    return ITEM_KINDS[rng.weighted(weights)] ?? 'turbo';
  }

  /* ──────────────────────────────── uso ──────────────────────────────── */

  private updateUse(
    karts: readonly Kart[],
    inputs: ReadonlyMap<number, InputFrame>,
    events: SimEvent[],
  ): void {
    for (const kart of karts) {
      const input = inputs.get(kart.id);
      if (!input?.item || !kart.heldItem || kart.itemCooldown > 0 || kart.spinning) continue;

      const kind = kart.heldItem.kind;
      this.use(kind, kart, events);
      kart.itemCooldown = 0.35;
      kart.heldItem.charges--;
      if (kart.heldItem.charges <= 0) kart.heldItem = null;
      events.push({ type: 'itemUse', kartId: kart.id, item: kind });
    }
  }

  private use(kind: ItemKind, kart: Kart, events: SimEvent[]): void {
    switch (kind) {
      case 'turbo':
      case 'tripleTurbo':
        kart.applyBoost(ITEM_TUNING.turboDuration, ITEM_TUNING.turboForce);
        events.push({ type: 'boost', kartId: kart.id, stage: 2 });
        break;
      case 'beetle':
        this.spawnProjectile(kart);
        break;
      case 'mud':
        this.spawnHazard(kart);
        break;
      case 'bubble':
        kart.shield = true;
        break;
    }
  }

  private spawnProjectile(owner: Kart): void {
    const forwardX = Math.cos(owner.angle);
    const forwardY = Math.sin(owner.angle);
    const reused = this.projectiles.find((p) => !p.active);
    const projectile: Projectile = reused ?? {
      id: 0, ownerId: 0, x: 0, y: 0, angle: 0, life: 0, targetId: -1, active: false,
    };
    projectile.id = this.nextId++;
    projectile.ownerId = owner.id;
    projectile.x = owner.x + forwardX * 2.4;
    projectile.y = owner.y + forwardY * 2.4;
    projectile.angle = owner.angle;
    projectile.life = ITEM_TUNING.beetleLife;
    projectile.targetId = -1;
    projectile.active = true;
    if (!reused) this.projectiles.push(projectile);
  }

  private spawnHazard(owner: Kart): void {
    const backX = -Math.cos(owner.angle);
    const backY = -Math.sin(owner.angle);
    const reused = this.hazards.find((h) => !h.active);
    const hazard: Hazard = reused ?? { id: 0, ownerId: 0, x: 0, y: 0, life: 0, active: false };
    hazard.id = this.nextId++;
    hazard.ownerId = owner.id;
    hazard.x = owner.x + backX * 3;
    hazard.y = owner.y + backY * 3;
    hazard.life = ITEM_TUNING.mudLife;
    hazard.active = true;
    if (!reused) this.hazards.push(hazard);
  }

  /* ───────────────────────────── projéteis ───────────────────────────── */

  private updateProjectiles(dt: number, karts: readonly Kart[], events: SimEvent[]): void {
    const hitRadiusSq = ITEM_TUNING.beetleRadius ** 2;

    for (const projectile of this.projectiles) {
      if (!projectile.active) continue;
      projectile.life -= dt;
      if (projectile.life <= 0) {
        projectile.active = false;
        continue;
      }

      if (projectile.targetId < 0) {
        projectile.targetId = this.findTarget(projectile, karts);
      }

      const target = karts[projectile.targetId];
      if (target) {
        const desired = Math.atan2(target.y - projectile.y, target.x - projectile.x);
        const turn = ITEM_TUNING.beetleTurnRate * dt;
        projectile.angle = moveToward(
          projectile.angle,
          projectile.angle + angleDelta(projectile.angle, desired),
          turn,
        );
      }

      projectile.x += Math.cos(projectile.angle) * ITEM_TUNING.beetleSpeed * dt;
      projectile.y += Math.sin(projectile.angle) * ITEM_TUNING.beetleSpeed * dt;

      for (const kart of karts) {
        // não acerta quem atirou enquanto ainda está saindo de perto
        if (kart.id === projectile.ownerId && projectile.life > ITEM_TUNING.beetleLife - 0.6) continue;
        if (kart.spinning || kart.invulnerableTime > 0) continue;
        const dx = kart.x - projectile.x;
        const dy = kart.y - projectile.y;
        if (dx * dx + dy * dy > hitRadiusSq) continue;

        projectile.active = false;
        this.strike(kart, events);
        break;
      }
    }
  }

  /** Mira em quem está logo à frente de quem atirou. */
  private findTarget(projectile: Projectile, karts: readonly Kart[]): number {
    let best = -1;
    let bestDistance = ITEM_TUNING.beetleLockRange ** 2;
    const forwardX = Math.cos(projectile.angle);
    const forwardY = Math.sin(projectile.angle);

    for (const kart of karts) {
      if (kart.id === projectile.ownerId) continue;
      const dx = kart.x - projectile.x;
      const dy = kart.y - projectile.y;
      // só considera quem está no hemisfério da frente
      if (dx * forwardX + dy * forwardY <= 0) continue;
      const distance = dx * dx + dy * dy;
      if (distance < bestDistance) {
        bestDistance = distance;
        best = kart.id;
      }
    }
    return best;
  }

  /** Acerto: a bolha absorve; sem ela, o kart roda. */
  private strike(kart: Kart, events: SimEvent[]): void {
    if (kart.shield) {
      kart.shield = false;
      events.push({ type: 'shieldBreak', kartId: kart.id });
      return;
    }
    kart.pendingSpin = true;
    events.push({ type: 'impact', kartId: kart.id, strength: 1 });
  }

  /* ───────────────────────────── armadilhas ──────────────────────────── */

  private updateHazards(dt: number, karts: readonly Kart[], events: SimEvent[]): void {
    const radiusSq = ITEM_TUNING.mudRadius ** 2;
    for (const hazard of this.hazards) {
      if (!hazard.active) continue;
      hazard.life -= dt;
      if (hazard.life <= 0) {
        hazard.active = false;
        continue;
      }

      for (const kart of karts) {
        if (kart.slipTime > 0 || kart.z > 1 || kart.spinning) continue;
        const dx = kart.x - hazard.x;
        const dy = kart.y - hazard.y;
        if (dx * dx + dy * dy > radiusSq) continue;

        if (kart.shield) {
          kart.shield = false;
          events.push({ type: 'shieldBreak', kartId: kart.id });
        } else {
          kart.slipTime = ITEM_TUNING.mudSlipDuration;
          const velocity = kart.body.getLinearVelocity();
          const keep = ITEM_TUNING.mudSpeedKeep;
          kart.body.setLinearVelocity({ x: velocity.x * keep, y: velocity.y * keep });
          events.push({ type: 'slip', kartId: kart.id });
        }
        hazard.active = false;
        break;
      }
    }
  }

  /** Decrementa temporizadores por kart ligados a itens. */
  static tickKart(kart: Kart, dt: number): void {
    if (kart.itemCooldown > 0) kart.itemCooldown = Math.max(0, kart.itemCooldown - dt);
    if (kart.slipTime > 0) kart.slipTime = Math.max(0, kart.slipTime - dt);
  }
}

export function clampCharges(value: number): number {
  return clamp(value, 0, 9);
}
