/**
 * O que a simulação recebe por kart, por tick. É o ÚNICO canal entre quem
 * joga (humano, bot ou, no futuro, alguém pela rede) e a física.
 * Mantido pequeno e serializável de propósito. Ver PLAN.md §8.1.
 */
export interface InputFrame {
  tick: number;
  /** Esterço analógico, -1 (esquerda) a 1 (direita). */
  steer: number;
  /** Acelerador, 0 a 1. */
  throttle: number;
  /** Freio/ré, 0 a 1. */
  brake: number;
  drift: boolean;
  item: boolean;
  respawn: boolean;
}

export function emptyInput(tick = 0): InputFrame {
  return { tick, steer: 0, throttle: 0, brake: 0, drift: false, item: false, respawn: false };
}

export function copyInput(target: InputFrame, source: InputFrame): InputFrame {
  target.tick = source.tick;
  target.steer = source.steer;
  target.throttle = source.throttle;
  target.brake = source.brake;
  target.drift = source.drift;
  target.item = source.item;
  target.respawn = source.respawn;
  return target;
}
