/**
 * Menu de configurações: controles, áudio, gráficos e jogo.
 * Em DOM sobre o canvas — sliders, foco e rolagem nativos, e acessível de
 * graça. Ver PLAN.md §8.3.
 */
import { clamp } from '@/core/math';
import { DIFFICULTIES } from '@/data/difficulty';
import {
  isTouchScheme,
  settingsStore,
  type ControlScheme,
  type Settings,
} from '@/data/settings';
import { t } from '@/i18n';
import { availableLanguages } from '@/i18n';
import type { KeyBindings } from '@/input/Bindings';
import type { GyroDevice, GyroStatus } from '@/input/devices/GyroDevice';
import { clear, el } from '../dom/elements';

type Tab = 'controls' | 'audio' | 'graphics' | 'game';

const KEY_ACTIONS: (keyof KeyBindings)[] = [
  'accelerate', 'brake', 'left', 'right', 'drift', 'item', 'respawn', 'pause',
];

export interface SettingsScreenOptions {
  readonly gyro: GyroDevice;
  readonly onChange: (settings: Settings) => void;
  readonly onClose: () => void;
}

export class SettingsScreen {
  readonly root: HTMLElement;

  private settings: Settings;
  private tab: Tab = 'controls';
  private readonly body: HTMLElement;
  private readonly tabsBar: HTMLElement;
  private capturing: { action: keyof KeyBindings; index: number; button: HTMLElement } | null = null;

  constructor(private readonly options: SettingsScreenOptions) {
    this.settings = settingsStore.get();
    this.body = el('div', { class: 'panel-body' });
    this.tabsBar = el('div', { class: 'tabs', role: 'tablist' });

    this.root = el('div', { class: 'overlay', role: 'dialog', 'aria-modal': 'true' }, [
      el('div', { class: 'panel' }, [
        el('div', { class: 'panel-head' }, [
          el('h2', { text: t('settings.title') }),
          el('button', { class: 'btn btn-ghost', text: t('action.close'), onClick: () => this.close() }),
        ]),
        this.tabsBar,
        this.body,
        el('div', { class: 'panel-foot' }, [
          el('button', {
            class: 'btn btn-ghost',
            text: t('action.reset'),
            onClick: () => this.resetAll(),
          }),
          el('button', { class: 'btn btn-primary', text: t('action.back'), onClick: () => this.close() }),
        ]),
      ]),
    ]);

    options.gyro.observe(() => { if (this.tab === 'controls') this.renderBody(); });
    window.addEventListener('keydown', this.onKeyDown, true);
    this.renderTabs();
    this.renderBody();
  }

  get isOpen(): boolean {
    return this.root.classList.contains('show');
  }

  open(): void {
    this.settings = settingsStore.get();
    this.renderBody();
    this.root.classList.add('show');
  }

  /** `silent` fecha sem avisar quem abriu — evita reabrir a pausa em cascata. */
  close(silent = false): void {
    const wasOpen = this.isOpen;
    this.cancelCapture();
    this.root.classList.remove('show');
    if (wasOpen && !silent) this.options.onClose();
  }

  destroy(): void {
    window.removeEventListener('keydown', this.onKeyDown, true);
    this.root.remove();
  }

  /* ─────────────────────────────── estrutura ─────────────────────────────── */

  private renderTabs(): void {
    const tabs: [Tab, string][] = [
      ['controls', t('settings.tab.controls')],
      ['audio', t('settings.tab.audio')],
      ['graphics', t('settings.tab.graphics')],
      ['game', t('settings.tab.game')],
    ];
    clear(this.tabsBar);
    for (const [id, label] of tabs) {
      this.tabsBar.append(
        el('button', {
          class: 'tab',
          role: 'tab',
          type: 'button',
          'aria-selected': this.tab === id,
          text: label,
          onClick: () => {
            this.tab = id;
            this.renderTabs();
            this.renderBody();
          },
        }),
      );
    }
  }

  private renderBody(): void {
    clear(this.body);
    switch (this.tab) {
      case 'controls': this.renderControls(); break;
      case 'audio': this.renderAudio(); break;
      case 'graphics': this.renderGraphics(); break;
      case 'game': this.renderGame(); break;
    }
  }

  private commit(): void {
    settingsStore.set(this.settings);
    this.options.onChange(this.settings);
  }

  private resetAll(): void {
    this.settings = settingsStore.reset();
    this.options.onChange(this.settings);
    this.renderBody();
  }

  /* ─────────────────────────────── controles ─────────────────────────────── */

  private renderControls(): void {
    const c = this.settings.controls;

    const schemes: [ControlScheme, string][] = [
      ['keyboard', t('controls.scheme.keyboard')],
      ['gamepad', t('controls.scheme.gamepad')],
      ['dpad', t('controls.scheme.dpad')],
      ['joystick', t('controls.scheme.joystick')],
      ['gyro', t('controls.scheme.gyro')],
    ];

    this.body.append(
      group(t('controls.scheme'), [
        segmented(schemes, c.scheme, (value) => {
          c.scheme = value;
          this.commit();
          this.renderBody();
        }),
        el('p', { class: 'hint', text: t('controls.scheme.hint') }),
      ]),
    );

    this.body.append(
      group(t('controls.keys'), [
        el('p', { class: 'hint', text: t('controls.keys.hint') }),
        ...KEY_ACTIONS.map((action) => this.keyRow(action)),
      ]),
    );

    const analog = [
      slider(t('controls.sensitivity'), c.sensitivity, 0.5, 1.6, 0.05, (v) => {
        c.sensitivity = v;
        this.commit();
      }, (v) => `${v.toFixed(2)}×`),
      slider(t('controls.deadzone'), c.deadzone, 0, 0.4, 0.01, (v) => {
        c.deadzone = v;
        this.commit();
      }, (v) => `${Math.round(v * 100)}%`),
    ];
    this.body.append(group(t('settings.tab.controls'), analog));

    if (isTouchScheme(c.scheme)) {
      this.body.append(
        group(t('controls.touch'), [
          toggle(t('controls.autoAccelerate'), c.autoAccelerate, (v) => {
            c.autoAccelerate = v;
            this.commit();
          }),
          toggle(t('controls.leftHanded'), c.leftHanded, (v) => {
            c.leftHanded = v;
            this.commit();
          }),
          toggle(t('controls.vibration'), c.vibration, (v) => {
            c.vibration = v;
            this.commit();
          }),
        ]),
      );
    }

    if (c.scheme === 'gyro') this.body.append(this.gyroGroup());
  }

  private gyroGroup(): HTMLElement {
    const c = this.settings.controls;
    const gyro = this.options.gyro;
    const status = gyro.status;

    return group(t('controls.gyro'), [
      el('p', { class: 'hint', text: t('controls.gyro.hint') }),
      el('div', { class: 'row' }, [
        el('span', { text: t('controls.gyro.enable') }),
        el('div', { class: 'control' }, [
          el('span', { class: statusClass(status), text: statusLabel(status) }),
          el('button', {
            class: 'btn',
            text: status === 'granted' ? t('controls.gyro.calibrate') : t('controls.gyro.enable'),
            onClick: () => {
              if (status === 'granted') gyro.calibrate();
              else void gyro.requestAccess().then(() => this.renderBody());
            },
          }),
        ]),
      ]),
      slider(t('controls.gyro.range'), c.gyroRange, 12, 50, 1, (v) => {
        c.gyroRange = v;
        this.commit();
      }, (v) => `${v}${t('unit.degrees')}`),
      toggle(t('controls.gyro.invert'), c.gyroInverted, (v) => {
        c.gyroInverted = v;
        this.commit();
      }),
    ]);
  }

  private keyRow(action: keyof KeyBindings): HTMLElement {
    const codes = this.settings.controls.keys[action];
    const buttons = codes.map((code, index) =>
      el('button', {
        class: 'key',
        type: 'button',
        text: keyLabel(code),
        onClick: (event: Event) => this.startCapture(action, index, event.currentTarget as HTMLElement),
      }),
    );
    return el('div', { class: 'row' }, [
      el('span', { text: t(`controls.key.${action}` as 'controls.key.left') }),
      el('div', { class: 'keys' }, buttons),
    ]);
  }

  private startCapture(action: keyof KeyBindings, index: number, button: HTMLElement): void {
    this.cancelCapture();
    this.capturing = { action, index, button };
    button.classList.add('capturing');
    button.textContent = '…';
  }

  private cancelCapture(): void {
    if (!this.capturing) return;
    const { action, index, button } = this.capturing;
    button.classList.remove('capturing');
    button.textContent = keyLabel(this.settings.controls.keys[action][index] ?? '');
    this.capturing = null;
  }

  private onKeyDown = (event: KeyboardEvent): void => {
    if (!this.capturing) return;
    event.preventDefault();
    event.stopPropagation();
    if (event.code === 'Escape') {
      this.cancelCapture();
      return;
    }
    const { action, index } = this.capturing;
    // tira a tecla de qualquer outra ação, senão duas ações disputam o mesmo botão
    const keys = this.settings.controls.keys;
    for (const other of Object.keys(keys) as (keyof KeyBindings)[]) {
      keys[other] = keys[other].filter((code) => code !== event.code);
    }
    const list = keys[action];
    while (list.length <= index) list.push('');
    list[index] = event.code;
    keys[action] = list.filter((code) => code !== '');
    this.capturing = null;
    this.commit();
    this.renderBody();
  };

  /* ───────────────────────── áudio, gráficos e jogo ───────────────────────── */

  private renderAudio(): void {
    const a = this.settings.audio;
    const percent = (v: number): string => `${Math.round(v * 100)}%`;
    this.body.append(
      group(t('settings.tab.audio'), [
        slider(t('audio.master'), a.master, 0, 1, 0.01, (v) => { a.master = v; this.commit(); }, percent),
        slider(t('audio.music'), a.music, 0, 1, 0.01, (v) => { a.music = v; this.commit(); }, percent),
        slider(t('audio.sfx'), a.sfx, 0, 1, 0.01, (v) => { a.sfx = v; this.commit(); }, percent),
        toggle(t('audio.muteOnBlur'), a.muteOnBlur, (v) => { a.muteOnBlur = v; this.commit(); }),
      ]),
    );
  }

  private renderGraphics(): void {
    const g = this.settings.graphics;
    this.body.append(
      group(t('settings.tab.graphics'), [
        segmentedRow(t('graphics.renderScale'), [
          [0.5, '50%'], [0.75, '75%'], [1, '100%'],
        ], g.renderScale, (v) => { g.renderScale = v; this.commit(); }),
        el('p', { class: 'hint', text: t('graphics.renderScale.hint') }),
        slider(t('graphics.viewDistance'), g.viewDistance, 120, 320, 10, (v) => {
          g.viewDistance = v;
          this.commit();
        }, (v) => `${v} ${t('unit.meters')}`),
        segmentedRow(t('graphics.fpsCap'), [
          [0, t('graphics.fpsCap.none')], [60, '60'], [30, '30'],
        ], g.fpsCap, (v) => { g.fpsCap = v; this.commit(); }),
        toggle(t('graphics.showFps'), g.showFps, (v) => { g.showFps = v; this.commit(); }),
      ]),
    );
  }

  private renderGame(): void {
    const g = this.settings.game;
    this.body.append(
      group(t('settings.tab.game'), [
        segmentedRow(
          t('game.difficulty'),
          DIFFICULTIES.map((d) => [d.id, d.name] as [string, string]),
          g.difficulty,
          (v) => { g.difficulty = v; this.commit(); },
        ),
        segmentedRow(t('game.laps'), [[1, '1'], [3, '3'], [5, '5']], g.laps, (v) => {
          g.laps = v;
          this.commit();
        }),
        slider(t('game.opponents'), g.opponents, 0, 7, 1, (v) => {
          g.opponents = clamp(v, 0, 7);
          this.commit();
        }, (v) => String(v)),
        segmentedRow(
          t('game.language'),
          availableLanguages().map((code) => [code, code] as [string, string]),
          g.language,
          (v) => { g.language = v; this.commit(); },
        ),
      ]),
    );
  }
}

/* ────────────────────────────── componentes ────────────────────────────── */

function group(title: string, children: (Node | string)[]): HTMLElement {
  return el('div', { class: 'group' }, [el('h3', { text: title }), ...children]);
}

function slider(
  label: string,
  value: number,
  min: number,
  max: number,
  step: number,
  onInput: (value: number) => void,
  format: (value: number) => string,
): HTMLElement {
  const readout = el('span', { class: 'value', text: format(value) });
  const input = el('input', {
    type: 'range',
    min, max, step,
    value,
    'aria-label': label,
    onInput: (event: Event) => {
      const next = Number((event.target as HTMLInputElement).value);
      readout.textContent = format(next);
      onInput(next);
    },
  });
  return el('div', { class: 'row' }, [
    el('span', { text: label }),
    el('div', { class: 'control' }, [input, readout]),
  ]);
}

function toggle(label: string, value: boolean, onChange: (value: boolean) => void): HTMLElement {
  const input = el('input', {
    type: 'checkbox',
    checked: value,
    'aria-label': label,
    onChange: (event: Event) => onChange((event.target as HTMLInputElement).checked),
  });
  return el('div', { class: 'row' }, [
    el('span', { text: label }),
    el('label', { class: 'switch' }, [input, el('span', {})]),
  ]);
}

function segmented<T extends string | number>(
  options: [T, string][],
  value: T,
  onChange: (value: T) => void,
): HTMLElement {
  return el(
    'div',
    { class: 'seg' },
    options.map(([id, label]) =>
      el('button', {
        type: 'button',
        'aria-pressed': id === value,
        text: label,
        onClick: () => onChange(id),
      }),
    ),
  );
}

function segmentedRow<T extends string | number>(
  label: string,
  options: [T, string][],
  value: T,
  onChange: (value: T) => void,
): HTMLElement {
  return el('div', { class: 'row' }, [
    el('span', { text: label }),
    el('div', { class: 'control' }, [segmented(options, value, onChange)]),
  ]);
}

/** Nome legível para um `KeyboardEvent.code`. */
export function keyLabel(code: string): string {
  if (!code) return '—';
  if (code.startsWith('Key')) return code.slice(3);
  if (code.startsWith('Digit')) return code.slice(5);
  const named: Record<string, string> = {
    ArrowUp: '↑', ArrowDown: '↓', ArrowLeft: '←', ArrowRight: '→',
    Space: 'Espaço', ShiftLeft: 'Shift E', ShiftRight: 'Shift D',
    ControlLeft: 'Ctrl E', ControlRight: 'Ctrl D', Escape: 'Esc',
    Enter: 'Enter', Tab: 'Tab', Backspace: '⌫',
  };
  return named[code] ?? code;
}

function statusLabel(status: GyroStatus): string {
  return t(`controls.gyro.status.${status}` as 'controls.gyro.status.idle');
}

function statusClass(status: GyroStatus): string {
  if (status === 'granted') return 'status ok';
  if (status === 'denied' || status === 'unsupported' || status === 'silent') return 'status bad';
  return 'status';
}
