/**
 * Céu e montanhas. Uma textura panorâmica de 360° que desliza conforme o
 * ângulo da câmera — é o que faz o mundo parecer girar em volta do jogador.
 */
import { TilingSprite, type Texture } from 'pixi.js';
import { TAU } from '@/core/math';
import type { Mode7Camera } from './Mode7Camera';

/** Fração da altura da textura onde está a linha do horizonte (ver tools/art/sky.ts). */
const HORIZON_AT = 0.76;

export class SkyLayer {
  readonly sprite: TilingSprite;

  private height = 0;
  private pixelsPer360 = 0;

  constructor(texture: Texture) {
    texture.source.style.addressMode = 'repeat';
    texture.source.style.update();
    this.sprite = new TilingSprite({ texture, width: 1, height: 1 });
  }

  resize(width: number, height: number, camera: Mode7Camera): void {
    this.height = height;
    this.sprite.width = width;
    this.sprite.height = height;

    // campo de visão horizontal implícito na projeção: nos bordos da tela,
    // o desvio lateral por unidade de profundidade é (aspect/2)/k
    const halfFov = Math.atan((0.5 * camera.aspect) / camera.k);
    this.pixelsPer360 = (width * TAU) / (halfFov * 2);

    const texWidth = this.sprite.texture.width;
    const scale = this.pixelsPer360 / texWidth;
    this.sprite.tileScale.set(scale, scale);

    this.alignHorizon(camera);
  }

  update(camera: Mode7Camera): void {
    this.sprite.tilePosition.x = -(camera.angle / TAU) * this.pixelsPer360;
    this.alignHorizon(camera);
  }

  /** Mantém a linha do horizonte da textura exatamente sobre a da câmera. */
  private alignHorizon(camera: Mode7Camera): void {
    const texHeight = this.sprite.texture.height * this.sprite.tileScale.y;
    this.sprite.tilePosition.y = camera.horizon * this.height - texHeight * HORIZON_AT;
  }
}
