/** Utilitários matemáticos puros. Sem dependências — usados pela sim e pelo render. */

export const TAU = Math.PI * 2;

export function clamp(v: number, min: number, max: number): number {
  return v < min ? min : v > max ? max : v;
}

export function lerp(a: number, b: number, t: number): number {
  return a + (b - a) * t;
}

/** Interpolação independente de framerate: `t` é a fração restante por segundo. */
export function damp(a: number, b: number, lambda: number, dt: number): number {
  return lerp(a, b, 1 - Math.exp(-lambda * dt));
}

/** Normaliza um ângulo para (-PI, PI]. */
export function wrapAngle(a: number): number {
  let x = (a + Math.PI) % TAU;
  if (x < 0) x += TAU;
  return x - Math.PI;
}

/** Menor diferença angular de `a` para `b`, em (-PI, PI]. */
export function angleDelta(a: number, b: number): number {
  return wrapAngle(b - a);
}

/** Interpola ângulos pelo caminho mais curto. */
export function lerpAngle(a: number, b: number, t: number): number {
  return wrapAngle(a + angleDelta(a, b) * t);
}

export function dampAngle(a: number, b: number, lambda: number, dt: number): number {
  return lerpAngle(a, b, 1 - Math.exp(-lambda * dt));
}

/** Move `a` na direção de `b` no máximo `maxDelta`. */
export function moveToward(a: number, b: number, maxDelta: number): number {
  const d = b - a;
  return Math.abs(d) <= maxDelta ? b : a + Math.sign(d) * maxDelta;
}

/** Remapeia `v` de [inMin,inMax] para [outMin,outMax], com clamp. */
export function remap(v: number, inMin: number, inMax: number, outMin: number, outMax: number): number {
  const t = clamp((v - inMin) / (inMax - inMin), 0, 1);
  return outMin + (outMax - outMin) * t;
}

export function smoothstep(edge0: number, edge1: number, v: number): number {
  const t = clamp((v - edge0) / (edge1 - edge0), 0, 1);
  return t * t * (3 - 2 * t);
}

/** Zona morta radial com recuperação de escala: evita o degrau no limiar. */
export function deadzone(v: number, dz: number): number {
  const a = Math.abs(v);
  if (a <= dz) return 0;
  return Math.sign(v) * ((a - dz) / (1 - dz));
}

export const DEG = Math.PI / 180;
