/**
 * A simulação. Função pura de (estado, inputs) → estado: nenhum import de
 * Pixi, GSAP, Howler ou DOM entra aqui, e é isso que permite rodar este mesmo
 * arquivo no servidor quando o multiplayer chegar. Ver PLAN.md §3.
 */
import { Box, Chain, Vec2, World as PhysicsWorld, type Body, type Contact, type ContactImpulse } from 'planck';
import { Rng } from '@/core/rng';
import { BOOST_PAD, KART, RACE } from '@/data/tuning';
import { SURFACE_PROPS, type TrackData } from '@/data/TrackData';
import type { InputFrame } from '@/input/InputFrame';
import { emptyInput } from '@/input/InputFrame';
import { Kart } from './entities/Kart';
import type { SurfaceMap } from './physics/SurfaceMap';
import type { SimEvent } from './SimEvents';
import { driveKart } from './systems/DriveSystem';
import { LapSystem } from './systems/LapSystem';
import { launch, updateAir } from './systems/AirSystem';
import { ItemSystem } from './systems/ItemSystem';
import { resolveImpacts, updateSpin, type PendingImpact } from './systems/SpinOutSystem';

const VELOCITY_ITERATIONS = 8;
const POSITION_ITERATIONS = 3;

export class SimWorld {
  readonly physics: PhysicsWorld;
  readonly karts: Kart[] = [];
  readonly rng: Rng;
  readonly laps: LapSystem;
  readonly items: ItemSystem;

  /** O que aconteceu neste tick. Quem apresenta esvazia a lista. */
  readonly events: SimEvent[] = [];

  tick = 0;
  /** Tempo de corrida decorrido, em segundos. Só anda depois da largada. */
  time = 0;
  /** Segundos restantes de contagem regressiva; 0 significa correndo. */
  countdown = 0;

  private readonly idleTime = new Map<number, number>();
  private readonly fallbackInput = emptyInput();
  /** Durante a contagem, todo mundo recebe este quadro vazio. */
  private readonly frozenInputs = new Map<number, InputFrame>();
  /** Batidas vistas pelo Box2D neste passo, resolvidas depois dele. */
  private readonly impacts: PendingImpact[] = [];
  private readonly lastLap = new Map<number, number>();
  /** Superfície do tick anterior: faixas e rampas só disparam ao PISAR nelas. */
  private readonly lastSurface = new Map<number, string>();

  constructor(
    readonly track: TrackData,
    readonly surfaces: SurfaceMap,
    seed = 1,
    totalLaps: number = RACE.laps,
  ) {
    this.rng = new Rng(seed);
    this.physics = new PhysicsWorld({ gravity: new Vec2(0, 0) });
    this.laps = new LapSystem(track, totalLaps);
    this.items = new ItemSystem(track);
    this.createWalls();
    // o Box2D proíbe mexer no mundo durante o callback, então só anotamos
    this.physics.on('post-solve', this.onPostSolve);
  }

  /** Põe um kart no slot do grid de largada. */
  spawnKart(slot: number): Kart {
    const spawn = this.track.spawns[slot % this.track.spawns.length]!;
    const body = this.physics.createBody({
      type: 'dynamic',
      position: new Vec2(spawn.x, spawn.y),
      angle: spawn.angle,
      // o kart é rápido e a parede é fina: sem isto ele atravessa em alta velocidade
      bullet: true,
      angularDamping: 0.4,
      allowSleep: false,
    });
    body.createFixture({
      shape: new Box(KART.halfLength, KART.halfWidth),
      density: KART.mass / (4 * KART.halfLength * KART.halfWidth),
      friction: 0.15,
      restitution: 0.22,
    });

    const kart = new Kart(this.karts.length, body);
    body.setUserData(kart);
    this.karts.push(kart);
    this.idleTime.set(kart.id, 0);
    this.laps.register(kart);
    this.frozenInputs.set(kart.id, this.fallbackInput);
    this.lastLap.set(kart.id, 0);
    return kart;
  }

  /** Trava o grid por alguns segundos antes de liberar a corrida. */
  startCountdown(seconds: number): void {
    this.countdown = seconds;
  }

  /** Um passo de tamanho fixo. `inputs` é indexado pelo id do kart. */
  step(dt: number, playerInputs: ReadonlyMap<number, InputFrame>): void {
    // na contagem a física continua rodando, mas ninguém acelera
    const counting = this.countdown > 0;
    const inputs = counting ? this.frozenInputs : playerInputs;
    if (counting) this.countdown = Math.max(0, this.countdown - dt);

    this.impacts.length = 0;

    for (const kart of this.karts) {
      kart.snapshotPrevious();
      const input = inputs.get(kart.id) ?? this.fallbackInput;
      const surfaceName = this.surfaces.at(kart.x, kart.y);
      kart.surface = surfaceName;
      this.applySurfaceTriggers(kart, surfaceName);
      updateAir(kart, dt);
      updateSpin(kart, dt);
      ItemSystem.tickKart(kart, dt);
      driveKart(kart, input, SURFACE_PROPS[surfaceName], dt);
      if (kart.pendingBoostStage !== null) {
        this.events.push({ type: 'boost', kartId: kart.id, stage: kart.pendingBoostStage });
        kart.pendingBoostStage = null;
      }
    }

    this.physics.step(dt, VELOCITY_ITERATIONS, POSITION_ITERATIONS);
    resolveImpacts(this.impacts, this.events);

    for (const kart of this.karts) {
      kart.syncFromBody();
      this.checkRespawn(kart, inputs.get(kart.id) ?? this.fallbackInput, dt);
    }

    if (!counting) this.time += dt;
    this.laps.update(this.karts, this.time);
    if (!counting) {
      this.items.update(dt, this.karts, this.laps.progress, inputs, this.rng, this.events);
    }
    this.emitLapEvents();
    this.tick++;
  }

  /** Devolve o kart ao waypoint mais próximo, olhando para o próximo. */
  respawn(kart: Kart): void {
    const index = this.nearestWaypoint(kart.x, kart.y);
    const here = this.track.waypoints[index]!;
    const next = this.track.waypoints[(index + 1) % this.track.waypoints.length]!;
    kart.reset(here.x, here.y, Math.atan2(next.y - here.y, next.x - here.x));
    this.idleTime.set(kart.id, 0);
    this.events.push({ type: 'respawn', kartId: kart.id });
  }

  /** Esvazia a fila de eventos, devolvendo o que havia. */
  drainEvents(into: SimEvent[]): SimEvent[] {
    into.length = 0;
    for (const event of this.events) into.push(event);
    this.events.length = 0;
    return into;
  }

  nearestWaypoint(x: number, y: number): number {
    let best = 0;
    let bestDistance = Infinity;
    const points = this.track.waypoints;
    for (let i = 0; i < points.length; i++) {
      const p = points[i]!;
      const d = (p.x - x) ** 2 + (p.y - y) ** 2;
      if (d < bestDistance) {
        bestDistance = d;
        best = i;
      }
    }
    return best;
  }

  private checkRespawn(kart: Kart, input: InputFrame, dt: number): void {
    if (input.respawn || SURFACE_PROPS[kart.surface].respawn) {
      this.respawn(kart);
      return;
    }
    // parado fora do asfalto por tempo demais: provavelmente encalhou
    const stuck = Math.abs(kart.speed) < 1.2 && kart.surface !== 'asphalt';
    const idle = (this.idleTime.get(kart.id) ?? 0) + (stuck ? dt : -dt * 2);
    const clamped = Math.max(0, idle);
    this.idleTime.set(kart.id, clamped);
    if (clamped >= RACE.stuckSeconds) this.respawn(kart);
  }

  /** Faixa de turbo e rampa agem uma vez, na transição para a superfície. */
  private applySurfaceTriggers(kart: Kart, surface: string): void {
    const previous = this.lastSurface.get(kart.id);
    this.lastSurface.set(kart.id, surface);
    if (surface === previous) return;

    if (surface === 'boost') {
      kart.applyBoost(BOOST_PAD.duration, BOOST_PAD.force);
      this.events.push({ type: 'boost', kartId: kart.id, stage: 1 });
    } else if (surface === 'ramp') {
      launch(kart);
    }
  }

  private emitLapEvents(): void {
    for (const kart of this.karts) {
      const state = this.laps.progress[kart.id];
      if (!state) continue;
      const previous = this.lastLap.get(kart.id) ?? 0;
      if (state.lap === previous) continue;
      this.lastLap.set(kart.id, state.lap);
      if (state.finished) this.events.push({ type: 'finish', kartId: kart.id, time: state.finishTime });
      else if (state.lap > 1) this.events.push({ type: 'lap', kartId: kart.id, lap: state.lap });
    }
  }

  /** Anota a batida; a resolução acontece depois do passo da física. */
  private onPostSolve = (contact: Contact, impulse: ContactImpulse): void => {
    let strongest = 0;
    for (const value of impulse.normalImpulses) strongest = Math.max(strongest, value);
    if (strongest <= 0) return;

    const a = contact.getFixtureA().getBody().getUserData();
    const b = contact.getFixtureB().getBody().getUserData();
    const kartA = a instanceof Kart ? a : null;
    const kartB = b instanceof Kart ? b : null;
    if (!kartA && !kartB) return;

    this.impacts.push({
      a: (kartA ?? kartB)!,
      b: kartA && kartB ? kartB : null,
      impulse: strongest,
    });
  };

  private createWalls(): void {
    const body: Body = this.physics.createBody({ type: 'static' });
    for (const wall of this.track.walls) {
      const vertices: Vec2[] = [];
      for (let i = 0; i < wall.points.length; i += 2) {
        vertices.push(new Vec2(wall.points[i]!, wall.points[i + 1]!));
      }
      body.createFixture({
        shape: new Chain(vertices, wall.closed),
        friction: 0.1,
        restitution: 0.25,
      });
    }
  }
}
