/**
 * O que fica salvo entre sessões: recordes por pista, fantasma da melhor
 * volta, copa em andamento e último personagem. Ver PLAN.md §13.5.
 */
import { Store } from '@/core/Storage';
import type { Standing } from './Scoring';

export interface TrackRecord {
  bestLap: number;
  bestRace: number;
  /** Amostras do fantasma da melhor volta (ver Ghost.ts). */
  ghost: number[] | null;
}

export interface ChampionshipSave {
  cupId: string;
  raceIndex: number;
  characterId: string;
  standings: Standing[];
}

export interface SaveData {
  tracks: Record<string, TrackRecord>;
  championship: ChampionshipSave | null;
  completedCups: Record<string, number>;
  lastCharacter: string;
}

function emptySave(): SaveData {
  return { tracks: {}, championship: null, completedCups: {}, lastCharacter: 'capivara' };
}

export const saveStore = new Store<SaveData>({
  key: 'kart.save.v1',
  version: 1,
  fallback: emptySave,
  migrate: () => emptySave(),
});

export function recordFor(trackId: string): TrackRecord {
  return saveStore.get().tracks[trackId] ?? { bestLap: Infinity, bestRace: Infinity, ghost: null };
}

/** Guarda um resultado e devolve o que melhorou. */
export function submitResult(
  trackId: string,
  lapTime: number,
  raceTime: number,
  ghost: number[] | null,
): { newBestLap: boolean; newBestRace: boolean } {
  const current = recordFor(trackId);
  const newBestLap = Number.isFinite(lapTime) && lapTime < (current.bestLap || Infinity);
  const newBestRace = Number.isFinite(raceTime) && raceTime < (current.bestRace || Infinity);

  if (!newBestLap && !newBestRace) return { newBestLap, newBestRace };

  saveStore.update((save) => ({
    ...save,
    tracks: {
      ...save.tracks,
      [trackId]: {
        bestLap: newBestLap ? lapTime : current.bestLap,
        bestRace: newBestRace ? raceTime : current.bestRace,
        // o fantasma acompanha a melhor VOLTA, não a melhor corrida
        ghost: newBestLap && ghost ? ghost : current.ghost,
      },
    },
  }));
  return { newBestLap, newBestRace };
}

export function saveChampionship(state: ChampionshipSave | null): void {
  saveStore.update((save) => ({ ...save, championship: state }));
}

export function loadChampionship(): ChampionshipSave | null {
  return saveStore.get().championship;
}

export function rememberCharacter(characterId: string): void {
  saveStore.update((save) => ({ ...save, lastCharacter: characterId }));
}

export function completeCup(cupId: string, position: number): void {
  saveStore.update((save) => {
    const previous = save.completedCups[cupId] ?? Infinity;
    return {
      ...save,
      championship: null,
      completedCups: { ...save.completedCups, [cupId]: Math.min(previous, position) },
    };
  });
}
