/** Números crus na tela: FPS, custo de simulação e render, estado do kart. */
import { Container, Text, TextStyle } from 'pixi.js';
import type { LoopStats } from '@/app/Loop';
import type { Kart } from '@/sim/entities/Kart';

const STYLE = new TextStyle({
  fontFamily: 'ui-monospace, SFMono-Regular, Menlo, monospace',
  fontSize: 13,
  fill: 0xe8eef5,
  lineHeight: 17,
});

export class DebugOverlay {
  readonly container = new Container();

  private readonly text = new Text({ text: '', style: STYLE });
  private elapsed = 0;

  constructor() {
    this.text.x = 12;
    this.text.y = 10;
    this.container.addChild(this.text);
    this.container.visible = false;
  }

  toggle(): void {
    this.container.visible = !this.container.visible;
  }

  setVisible(visible: boolean): void {
    this.container.visible = visible;
  }

  update(stats: LoopStats, kart: Kart, dt: number): void {
    if (!this.container.visible) return;
    this.elapsed += dt;
    if (this.elapsed < 0.1) return;
    this.elapsed = 0;

    const kmh = kart.speed * 3.6;
    this.text.text =
      `${stats.fps.toFixed(0)} fps   sim ${stats.simMs.toFixed(1)}ms   render ${stats.renderMs.toFixed(1)}ms\n` +
      `${kmh.toFixed(0)} km/h   lateral ${kart.lateralSpeed.toFixed(1)}\n` +
      `${kart.surface}${kart.drifting ? `   drift ${kart.driftCharge.toFixed(2)}` : ''}\n` +
      `pos ${kart.x.toFixed(1)}, ${kart.y.toFixed(1)}`;
  }
}
