/** Formato dos esqueletos gerados, espelhando tools/spine/kart.ts. */
export const SPINE_ANGLES = 8;
export const SPINE_PX_PER_METER = 46;

export function spineSkinFor(relativeTurns: number): string {
  const index = Math.round(relativeTurns * SPINE_ANGLES) % SPINE_ANGLES;
  return `angle${index < 0 ? index + SPINE_ANGLES : index}`;
}

/** Animações disponíveis no esqueleto. */
export const SPINE_ANIMATIONS = [
  'idle', 'steer_left', 'steer_right', 'drift_left', 'drift_right', 'boost', 'hit', 'air',
] as const;
export type SpineAnimation = (typeof SPINE_ANIMATIONS)[number];
