/**
 * Câmera Mode 7 — a fonte ÚNICA de verdade da projeção.
 *
 * Ela alimenta os uniforms do shader (que desenha o chão) e projeta os
 * billboards (karts, itens, cenário). Se as duas contas divergirem, os karts
 * deslizam sobre a pista e a ilusão morre. Por isso vivem no mesmo lugar e há
 * um teste de ida-e-volta garantindo que `unproject(project(p)) === p`.
 *
 * Convenções (PLAN.md §6.1):
 *   mundo  — X para a direita, Y para baixo, em metros
 *   ângulo — frente F = (cos a, sin a); direita da tela R = (-sin a, cos a)
 *   tela   — normalizada, x de 0 (esquerda) a 1, y de 0 (topo) a 1
 */
import { dampAngle, damp } from '@/core/math';

export interface ProjectedPoint {
  /** Posição na tela normalizada, x e y em 0..1. */
  sx: number;
  sy: number;
  /** Distância à frente da câmera, em metros. */
  depth: number;
  /** Quantos pixels de tela vale um metro nesta profundidade. */
  pxPerMeter: number;
}

export class Mode7Camera {
  /** Posição da câmera no plano do mundo, em metros. */
  x = 0;
  y = 0;
  /** Para onde a câmera olha, em radianos. */
  angle = 0;
  /** Altura da câmera acima do plano, em metros. */
  height = 5.4;
  /** Altura do horizonte na tela, normalizada. */
  horizon = 0.4;
  /** Escala focal: maior = mais "zoom", campo de visão mais fechado. */
  k = 0.55;
  /** Recortes de profundidade, em metros. */
  near = 1.2;
  far = 260;

  /** Proporção da tela (largura/altura) e altura em pixels. */
  aspect = 16 / 9;
  screenHeight = 720;

  /** Distância entre a câmera e o kart que ela segue, em metros. */
  trail = 7.5;

  /**
   * Põe a câmera atrás do alvo. `instant` reposiciona sem suavizar —
   * use na largada e depois de um respawn.
   */
  follow(targetX: number, targetY: number, targetAngle: number, dt: number, instant = false): void {
    if (instant) {
      this.angle = targetAngle;
    } else {
      // a câmera gira um pouco depois do kart: é isso que dá peso à curva
      this.angle = dampAngle(this.angle, targetAngle, 9, dt);
    }
    const fx = Math.cos(this.angle);
    const fy = Math.sin(this.angle);
    const desiredX = targetX - fx * this.trail;
    const desiredY = targetY - fy * this.trail;
    if (instant) {
      this.x = desiredX;
      this.y = desiredY;
    } else {
      this.x = damp(this.x, desiredX, 18, dt);
      this.y = damp(this.y, desiredY, 18, dt);
    }
  }

  /**
   * Mundo → tela. Devolve `false` quando o ponto está atrás da câmera
   * (ou perto demais) e não deve ser desenhado.
   */
  project(wx: number, wy: number, wz: number, out: ProjectedPoint): boolean {
    const dx = wx - this.x;
    const dy = wy - this.y;
    const c = Math.cos(this.angle);
    const s = Math.sin(this.angle);

    const depth = dx * c + dy * s;
    if (depth < this.near) return false;

    const side = -dx * s + dy * c;
    const scale = this.k / depth;

    out.sx = 0.5 + (side * scale) / this.aspect;
    out.sy = this.horizon + (this.height - wz) * scale;
    out.depth = depth;
    out.pxPerMeter = scale * this.screenHeight;
    return true;
  }

  /**
   * Tela → mundo, no plano do chão (z = 0). É exatamente a inversa de
   * `project`, e é o que o fragment shader faz por pixel.
   * Devolve `false` acima da linha do horizonte.
   */
  unproject(sx: number, sy: number, out: { x: number; y: number; depth: number }): boolean {
    const dy = sy - this.horizon;
    if (dy <= 1e-6) return false;

    const depth = (this.k * this.height) / dy;
    if (depth > this.far) return false;

    const side = ((sx - 0.5) * this.aspect * depth) / this.k;
    const c = Math.cos(this.angle);
    const s = Math.sin(this.angle);

    out.x = this.x + c * depth - s * side;
    out.y = this.y + s * depth + c * side;
    out.depth = depth;
    return true;
  }

  /** Reaproveita o viewport atual para manter `aspect` e `screenHeight` em dia. */
  resize(widthPx: number, heightPx: number): void {
    this.aspect = widthPx / heightPx;
    this.screenHeight = heightPx;
  }
}
