/**
 * Bot. Segue a linha ideal do `track.json`, freia antes das curvas e derrapa
 * quando compensa — produzindo `InputFrame` exatamente como um humano.
 * Nada de velocidade extra ou aderência mágica. Ver PLAN.md §7.
 */
import { angleDelta, clamp } from '@/core/math';
import type { Rng } from '@/core/rng';
import type { DifficultyProfile } from '@/data/difficulty';
import type { TrackData } from '@/data/TrackData';
import { emptyInput, type InputFrame } from '@/input/InputFrame';
import type { Kart } from '@/sim/entities/Kart';
import type { Controller } from './Controller';

/** Alcance em que o bot considera que vale atirar o besouro, em metros. */
const BEETLE_RANGE = 70;

/**
 * Perseguição pura: o bot mira num ponto a uma distância fixa EM METROS à
 * frente, não a um número de waypoints. Medir em waypoints fazia o alvo ficar
 * a 60 m em alta velocidade, e o bot cortava a curva e saía para a areia.
 */
const LOOKAHEAD_BASE = 7;
const LOOKAHEAD_PER_MPS = 0.75;
const LOOKAHEAD_MIN = 9;
const LOOKAHEAD_MAX = 26;

/** Ganho do esterço: quantas unidades por radiano de erro. */
const STEER_GAIN = 1.9;
/** Acima desta razão entre velocidade e limite da curva, o bot freia. */
const BRAKE_RATIO = 1.07;
/** Fora da pista, o bot encurta a mira e volta para o traçado. */
const RECOVERY_LOOKAHEAD = 7;

export class AIController implements Controller {
  readonly kartId: number;

  private readonly frame = emptyInput();
  private waypoint = 0;
  private noise = 0;
  private noiseTimer = 0;
  /** Distância entre waypoints consecutivos, em metros. */
  private readonly spacing: number;

  constructor(
    private readonly kart: Kart,
    private readonly track: TrackData,
    private readonly profile: DifficultyProfile,
    private readonly rng: Rng,
    /** Deslocamento lateral da linha ideal, em metros — espalha o pelotão. */
    private readonly lineOffset: number,
    /** Todos os karts, para decidir quando usar item ofensivo. */
    private readonly karts: readonly Kart[] = [],
  ) {
    this.kartId = kart.id;
    const points = track.waypoints;
    this.spacing = points.length > 1 ? Math.max(1, points[1]!.distance - points[0]!.distance) : 6;
  }

  poll(_tick: number, dt: number): InputFrame {
    const points = this.track.waypoints;
    const count = points.length;
    this.advanceWaypoint();

    const speed = Math.max(0, this.kart.speed);
    const here = points[this.waypoint]!;

    // quanto mais longe do traçado, mais curto o alvo — é assim que ele volta
    const offLine = Math.hypot(here.x - this.kart.x, here.y - this.kart.y) > here.halfWidth;
    const lookaheadMeters = offLine
      ? RECOVERY_LOOKAHEAD
      : clamp(
          (LOOKAHEAD_BASE + speed * LOOKAHEAD_PER_MPS) * this.profile.lookaheadScale,
          LOOKAHEAD_MIN,
          LOOKAHEAD_MAX,
        );
    const steps = Math.max(1, Math.round(lookaheadMeters / this.spacing));

    const targetIndex = (this.waypoint + steps) % count;
    const target = points[targetIndex]!;
    const after = points[(targetIndex + 1) % count]!;

    // desloca o alvo na perpendicular para cada bot ter a sua linha
    const dx = after.x - target.x;
    const dy = after.y - target.y;
    const length = Math.hypot(dx, dy) || 1;
    const offset = offLine
      ? 0
      : clamp(this.lineOffset, -target.halfWidth * 0.65, target.halfWidth * 0.65);
    const aimX = target.x + (-dy / length) * offset;
    const aimY = target.y + (dx / length) * offset;

    this.updateNoise(dt);

    const desired = Math.atan2(aimY - this.kart.y, aimX - this.kart.x);
    const error = angleDelta(this.kart.angle, desired);
    const steer = clamp(error * STEER_GAIN + this.noise, -1, 1);

    const limit = this.speedLimitAhead() * this.profile.paceFactor;
    const braking = speed > limit * BRAKE_RATIO;

    this.frame.tick = _tick;
    this.frame.steer = steer;
    this.frame.throttle = braking ? 0 : 1;
    this.frame.brake = braking ? 1 : 0;
    this.frame.drift = this.shouldDrift(steer, speed, limit);
    this.frame.item = this.shouldUseItem(steer, speed);
    this.frame.respawn = false;
    return this.frame;
  }

  /** Anda o índice enquanto o waypoint seguinte estiver mais perto que o atual. */
  private advanceWaypoint(): void {
    const points = this.track.waypoints;
    const count = points.length;
    for (let step = 0; step < 4; step++) {
      const here = points[this.waypoint]!;
      const next = points[(this.waypoint + 1) % count]!;
      const dHere = (here.x - this.kart.x) ** 2 + (here.y - this.kart.y) ** 2;
      const dNext = (next.x - this.kart.x) ** 2 + (next.y - this.kart.y) ** 2;
      if (dNext >= dHere) break;
      this.waypoint = (this.waypoint + 1) % count;
    }
  }

  /** Menor velocidade exigida nos próximos waypoints — é por ela que freia. */
  private speedLimitAhead(): number {
    const points = this.track.waypoints;
    const count = points.length;
    let limit = Infinity;
    for (let i = 0; i <= this.profile.brakeLookahead; i++) {
      const point = points[(this.waypoint + i) % count]!;
      if (point.targetSpeed < limit) limit = point.targetSpeed;
    }
    return limit;
  }

  private shouldDrift(steer: number, speed: number, limit: number): boolean {
    if (this.profile.driftSkill <= 0) return false;
    const committed = Math.abs(steer) > 0.45 && speed > 11;
    // só derrapa quando a curva é realmente fechada para o perfil dele
    return committed && limit < 18 * (0.6 + this.profile.driftSkill * 0.6);
  }

  /**
   * Quando apertar o botão de item. Cada item tem o seu momento: turbo na
   * reta, besouro com alguém à frente, bolha na hora, lama a qualquer momento.
   */
  private shouldUseItem(steer: number, speed: number): boolean {
    const held = this.kart.heldItem;
    if (!held || this.kart.itemCooldown > 0) return false;
    // o perfil fraco demora a usar
    if (this.rng.next() > 0.08 + this.profile.driftSkill * 0.25) return false;

    switch (held.kind) {
      case 'turbo':
      case 'tripleTurbo':
        return Math.abs(steer) < 0.3 && speed > 12;
      case 'beetle':
        return this.hasTargetAhead();
      case 'bubble':
        return true;
      case 'mud':
        return speed > 8;
    }
  }

  private hasTargetAhead(): boolean {
    const forwardX = Math.cos(this.kart.angle);
    const forwardY = Math.sin(this.kart.angle);
    for (const other of this.karts) {
      if (other.id === this.kart.id) continue;
      const dx = other.x - this.kart.x;
      const dy = other.y - this.kart.y;
      const ahead = dx * forwardX + dy * forwardY;
      if (ahead <= 2 || ahead > BEETLE_RANGE) continue;
      // precisa estar mais ou menos na mesma direção, não ao lado
      const lateral = Math.abs(-dx * forwardY + dy * forwardX);
      if (lateral < 14) return true;
    }
    return false;
  }

  /** Ruído de esterço lento, para o bot não parecer um trilho. */
  private updateNoise(dt: number): void {
    this.noiseTimer -= dt;
    if (this.noiseTimer <= 0) {
      this.noiseTimer = this.rng.range(0.4, 1.1);
      this.noise = this.rng.range(-1, 1) * this.profile.steerNoise;
    }
  }
}
