/**
 * Avisa quando o jogo deixa de estar visível — trocar de aba, atender uma
 * ligação, bloquear a tela. Sem isso o jogador volta e já bateu.
 */
export function onHidden(callback: (hidden: boolean) => void): () => void {
  const handleVisibility = (): void => callback(document.hidden);
  const handleBlur = (): void => callback(true);

  document.addEventListener('visibilitychange', handleVisibility);
  window.addEventListener('blur', handleBlur);

  return () => {
    document.removeEventListener('visibilitychange', handleVisibility);
    window.removeEventListener('blur', handleBlur);
  };
}
