/**
 * Tudo que o jogador pode configurar, e como isso é guardado.
 * Ver PLAN.md §8.3.
 */
import { Store } from '@/core/Storage';
import { cloneBindings, DEFAULT_KEY_BINDINGS, type KeyBindings } from '@/input/Bindings';

export type ControlScheme = 'keyboard' | 'gamepad' | 'dpad' | 'joystick' | 'gyro';

export interface ControlSettings {
  scheme: ControlScheme;
  keys: KeyBindings;
  /** Multiplica o esterço analógico. */
  sensitivity: number;
  /** Zona morta de stick e giroscópio, 0 a 0.4. */
  deadzone: number;
  /** Inclinação, em graus, que corresponde a esterço total. */
  gyroRange: number;
  gyroInverted: boolean;
  autoAccelerate: boolean;
  /** Direção do lado direito da tela. */
  leftHanded: boolean;
  vibration: boolean;
}

export interface AudioSettings {
  master: number;
  music: number;
  sfx: number;
  muteOnBlur: boolean;
}

export interface GraphicsSettings {
  /** Escala do render do Mode 7: 0.5, 0.75 ou 1. */
  renderScale: number;
  /** Distância de visão em metros — a névoa acompanha. */
  viewDistance: number;
  showFps: boolean;
  /** 0 = sem limite. */
  fpsCap: number;
}

export interface GameSettings {
  difficulty: string;
  laps: number;
  opponents: number;
  language: string;
}

export interface Settings {
  controls: ControlSettings;
  audio: AudioSettings;
  graphics: GraphicsSettings;
  game: GameSettings;
}

/** Detecta um padrão sensato olhando o aparelho, sem perguntar nada. */
export function defaultSettings(): Settings {
  const touch = matchMedia('(pointer: coarse)').matches;
  const cores = navigator.hardwareConcurrency ?? 4;
  const lowEnd = touch && cores <= 4;

  return {
    controls: {
      scheme: touch ? 'joystick' : 'keyboard',
      keys: cloneBindings(DEFAULT_KEY_BINDINGS),
      sensitivity: 1,
      deadzone: 0.12,
      gyroRange: 28,
      gyroInverted: false,
      autoAccelerate: touch,
      leftHanded: false,
      vibration: true,
    },
    audio: { master: 0.8, music: 0.6, sfx: 0.9, muteOnBlur: true },
    graphics: {
      renderScale: lowEnd ? 0.75 : 1,
      viewDistance: lowEnd ? 180 : 260,
      showFps: false,
      fpsCap: 0,
    },
    game: { difficulty: 'normal', laps: 3, opponents: 7, language: 'pt-BR' },
  };
}

export const settingsStore = new Store<Settings>({
  key: 'kart.settings.v1',
  version: 1,
  fallback: defaultSettings,
  migrate: (old, from) => {
    // nenhuma versão anterior ainda; a função existe para a próxima mudança
    void old;
    void from;
    return defaultSettings();
  },
});

/** Esquemas que usam a tela como controle. */
export function isTouchScheme(scheme: ControlScheme): boolean {
  return scheme === 'dpad' || scheme === 'joystick';
}
