/**
 * Orquestra tudo: assets, simulação, render, entrada, interface, modos e
 * configurações. A simulação roda sozinha e o render só a observa (PLAN.md §3).
 */
import type { Texture } from 'pixi.js';
import { AudioBus } from '@/audio/AudioBus';
import { AIController } from '@/controllers/AIController';
import type { Controller } from '@/controllers/Controller';
import { CHARACTERS } from '@/data/characters';
import { difficultyById } from '@/data/difficulty';
import { isTouchScheme, settingsStore, type Settings } from '@/data/settings';
import { setLanguage } from '@/i18n';
import { copyInput, emptyInput, type InputFrame } from '@/input/InputFrame';
import { InputManager } from '@/input/InputManager';
import { GamepadDevice } from '@/input/devices/GamepadDevice';
import { GyroDevice } from '@/input/devices/GyroDevice';
import { KeyboardDevice } from '@/input/devices/KeyboardDevice';
import { TouchDevice } from '@/input/devices/TouchDevice';
import { GhostPlayer, GhostRecorder, type GhostPose } from '@/meta/Ghost';
import { submitResult } from '@/meta/Records';
import { DebugOverlay } from '@/render/debug/DebugOverlay';
import { RaceView } from '@/render/RaceView';
import type { SimEvent } from '@/sim/SimEvents';
import { SimWorld } from '@/sim/World';
import { Hud } from '@/ui/Hud';
import { TouchControls } from '@/ui/TouchControls';
import { PauseMenu, StartScreen } from '@/ui/screens/Menus';
import { SettingsScreen } from '@/ui/screens/SettingsScreen';
import {
  loadDetail, loadItemAssets, loadKartSheets, loadParticles, loadSpineKarts, loadTrack,
  makeSpineKart, type ItemAssets, type ParticleAssets, type TrackBundle,
} from './assets';
import { SpineKartView } from '@/render/billboards/SpineKartView';
import { Flow } from './Flow';
import { Loop } from './Loop';
import type { RaceRequest, RaceSummary } from './Session';
import { Stage } from './Stage';
import { onHidden } from './visibility';

/** Segundos de grid parado antes da largada. */
const COUNTDOWN_SECONDS = 3;
/** Quanto tempo o "VALENDO!" fica na tela depois da largada. */
const GO_FLASH_SECONDS = 0.9;
/** Espera entre cruzar a linha e abrir o resultado, em segundos. */
const RESULTS_DELAY = 2.2;
/**
 * Prazo para o jogador terminar depois que todos os adversários terminaram.
 * Sem isto, quem desiste no meio deixa a corrida sem fim.
 */
const GRACE_SECONDS = 25;
/** Velocidade máxima de referência para o som do motor, em m/s. */
const TOP_SPEED = 20;

export class Game {
  readonly stage = new Stage();
  readonly input = new InputManager();

  private loop!: Loop;
  private sim!: SimWorld;
  private view!: RaceView;
  private hud!: Hud;
  private flow!: Flow;

  private readonly tracks = new Map<string, TrackBundle>();
  private kartSheets!: ReadonlyMap<string, Texture>;
  private detail!: Texture;
  private itemAssets!: ItemAssets;
  private particleAssets!: ParticleAssets;
  private spineReady = new Set<string>();
  private track!: TrackBundle;

  private readonly audio = new AudioBus();
  private readonly debug = new DebugOverlay();
  private readonly touchControls = new TouchControls();
  private readonly keyboard = new KeyboardDevice();
  private readonly gamepad = new GamepadDevice();
  private readonly gyro = new GyroDevice();
  private readonly touch = new TouchDevice(this.touchControls.state);

  private settings: Settings = settingsStore.get();
  private settingsScreen!: SettingsScreen;
  private pauseMenu!: PauseMenu;
  private startScreen!: StartScreen;

  private readonly inputs = new Map<number, InputFrame>();
  private readonly bots: Controller[] = [];
  private readonly drained: SimEvent[] = [];
  private roster: string[] = [];
  private request: RaceRequest | null = null;

  private readonly ghostRecorder = new GhostRecorder();
  private readonly ghostPose: GhostPose = { x: 0, y: 0, angle: 0, z: 0 };
  private ghostPlayer: GhostPlayer | null = null;
  private bestLapGhost: number[] | null = null;
  private lastLapIndex = 0;

  private playerId = 0;
  private lastCountdownStep = -1;
  private resultsTimer = -1;
  private graceTimer = -1;
  private raceOver = false;
  private pausedByMenu = false;
  private pausedBySystem = false;
  private started = false;

  async start(host: HTMLElement): Promise<void> {
    await this.stage.init(host);

    setLanguage(this.settings.game.language);
    const [track, kartSheets, detail, itemAssets, particleAssets] = await Promise.all([
      this.getTrack('track01'),
      loadKartSheets(),
      loadDetail(),
      loadItemAssets(),
      loadParticles(),
    ]);
    this.particleAssets = particleAssets;
    // o Spine é opcional: se falhar, os karts continuam como sprites
    this.spineReady = await loadSpineKarts().catch((error: unknown) => {
      console.warn('Spine indisponível, usando sprites', error);
      return new Set<string>();
    });
    this.kartSheets = kartSheets;
    this.detail = detail;
    this.itemAssets = itemAssets;
    this.track = track;

    await this.audio.load().catch((error: unknown) => {
      // sem áudio o jogo continua: é incômodo, não impeditivo
      console.warn('áudio indisponível', error);
    });

    this.flow = new Flow({
      onStartRace: (request) => void this.startRace(request),
      onPlaySound: (name) => this.audio.play(name, 0.5),
    });

    // uma corrida de fundo roda atrás da tela inicial, como pano de fundo vivo
    this.buildRace({
      mode: 'quick',
      trackId: 'track01',
      characterId: 'capivara',
      opponents: this.settings.game.opponents,
      ghost: null,
    });
    this.buildMenus();
    this.bindInput();

    this.stage.events.on('resize', ({ width, height }) => this.resize(width, height));
    this.stage.events.on('orientation', ({ portrait }) => this.setSystemPaused(portrait));
    onHidden((hidden) => this.setSystemPaused(hidden));

    this.loop = new Loop(this.onFixed, this.onRender);
    this.applySettings(this.settings);
    this.loop.start();

    if (import.meta.env.DEV) {
      (window as unknown as { game: Game }).game = this;
    }
  }

  /* ──────────────────────────────── corrida ──────────────────────────────── */

  private async getTrack(id: string): Promise<TrackBundle> {
    const cached = this.tracks.get(id);
    if (cached) return cached;
    const bundle = await loadTrack(id);
    this.tracks.set(id, bundle);
    return bundle;
  }

  private async startRace(request: RaceRequest): Promise<void> {
    this.track = await this.getTrack(request.trackId);
    this.buildRace(request);
    this.applySettings(this.settings);
    this.audio.playMusic(this.track.data.theme);
    this.closeMenus();
    this.sim.startCountdown(COUNTDOWN_SECONDS);
    this.lastCountdownStep = -1;
    this.loop.resync();
  }

  /** Cria (ou recria) a corrida inteira. O jogador é sempre o kart 0. */
  private buildRace(request: RaceRequest): void {
    this.request = request;
    const laps = this.settings.game.laps;
    const others = CHARACTERS.filter((c) => c.id !== request.characterId).map((c) => c.id);
    this.roster = [request.characterId, ...others.slice(0, Math.max(0, request.opponents))];

    this.sim = new SimWorld(this.track.data, this.track.surfaces, 1, laps);
    this.inputs.clear();
    this.bots.length = 0;

    for (let slot = 0; slot < this.roster.length; slot++) {
      const kart = this.sim.spawnKart(slot);
      this.inputs.set(kart.id, emptyInput());
    }
    this.playerId = 0;

    const profile = difficultyById(this.settings.game.difficulty);
    for (const kart of this.sim.karts) {
      if (kart.id === this.playerId) continue;
      const offset = this.sim.rng.range(-3.2, 3.2);
      this.bots.push(
        new AIController(kart, this.track.data, profile, this.sim.rng, offset, this.sim.karts),
      );
    }

    this.view?.destroy();
    this.view = new RaceView(this.sim, this.track, this.kartSheets, this.roster, this.detail);
    this.view.enableSpine((characterId) =>
      this.spineReady.has(characterId) ? new SpineKartView(makeSpineKart(characterId)) : null,
    );
    this.view.enableFx(this.particleAssets);
    this.view.enableItems(
      { box: this.itemAssets.box, beetle: this.itemAssets.beetle, mud: this.itemAssets.mud },
      this.itemAssets.bubble,
    );
    this.hud = new Hud(laps, this.roster.length, this.itemAssets.icons);

    this.ghostRecorder.reset();
    this.bestLapGhost = null;
    this.lastLapIndex = 0;
    this.raceOver = false;
    this.resultsTimer = -1;
    this.graceTimer = -1;

    this.ghostPlayer = null;
    if (request.ghost) {
      const player = new GhostPlayer(request.ghost);
      if (!player.isEmpty) {
        this.ghostPlayer = player;
        const sheet = this.kartSheets.get(request.characterId);
        if (sheet) this.view.enableGhost(sheet);
      }
    }

    this.stage.root.removeChildren();
    this.stage.root.addChild(
      this.view.container,
      this.hud.container,
      this.touchControls.container,
      this.debug.container,
    );
    this.resize(this.stage.width, this.stage.height);
    this.view.snapCamera();
    this.sim.startCountdown(COUNTDOWN_SECONDS);
  }

  private restart(): void {
    if (!this.request) return;
    this.lastCountdownStep = -1;
    void this.startRace(this.request);
  }

  /** Monta o resumo e entrega ao fluxo de telas. */
  private finishRace(): void {
    const progress = this.sim.laps.progress[this.playerId];
    if (!progress || !this.request) return;

    const order = this.sim.karts
      .map((kart) => ({
        kartId: kart.id,
        characterId: this.roster[kart.id] ?? 'capivara',
        position: this.sim.laps.progress[kart.id]?.position ?? kart.id + 1,
      }))
      .sort((a, b) => a.position - b.position);

    const summary: RaceSummary = {
      position: progress.position,
      totalTime: progress.finishTime || this.sim.time,
      bestLap: progress.bestLap,
      finished: progress.finished,
      order,
    };

    const records = submitResult(
      this.request.trackId,
      progress.bestLap,
      summary.totalTime,
      this.bestLapGhost,
    );

    this.setMenuPaused(true);
    this.flow.showResults(summary, records);
  }

  /* ───────────────────────────────── menus ───────────────────────────────── */

  private buildMenus(): void {
    this.settingsScreen = new SettingsScreen({
      gyro: this.gyro,
      onChange: (settings) => this.applySettings(settings),
      onClose: () => {
        if (this.started) this.pauseMenu.open();
        else this.startScreen.root.classList.add('show');
      },
    });

    this.pauseMenu = new PauseMenu({
      onResume: () => this.closeMenus(),
      onSettings: () => {
        this.pauseMenu.close();
        this.settingsScreen.open();
      },
      onRestart: () => this.restart(),
    });

    this.startScreen = new StartScreen(() => {
      this.started = true;
      // o áudio só pode ser liberado dentro de um gesto do usuário
      this.audio.unlock();
      this.audio.startLoops();
      this.setMenuPaused(true);
      this.flow.showModeSelect();
      void this.stage.requestFullscreen();
    });

    document.body.append(
      this.startScreen.root,
      this.flow.panel.root,
      this.pauseMenu.root,
      this.settingsScreen.root,
    );
    this.setMenuPaused(true);
  }

  private closeMenus(): void {
    this.pauseMenu.close();
    this.settingsScreen.close(true);
    this.flow.panel.hide();
    this.setMenuPaused(false);
  }

  /** Esc: das configurações volta para a pausa; da pausa volta para a corrida. */
  private togglePause(): void {
    if (!this.started || this.flow.isOpen) return;
    if (this.settingsScreen.isOpen) {
      this.settingsScreen.close();
      return;
    }
    if (this.pauseMenu.isOpen) {
      this.closeMenus();
      return;
    }
    this.pauseMenu.open();
    this.setMenuPaused(true);
  }

  /* ───────────────────────────────── entrada ─────────────────────────────── */

  private bindInput(): void {
    this.input.add(this.keyboard);
    this.input.add(this.gamepad);
    this.input.add(this.touch);
    this.input.add(this.gyro);

    window.addEventListener('keydown', (event) => {
      if (event.code === 'F1') {
        event.preventDefault();
        this.debug.toggle();
        return;
      }
      if (this.settings.controls.keys.pause.includes(event.code)) {
        event.preventDefault();
        this.togglePause();
      }
    });
  }

  /* ─────────────────────────── configurações ─────────────────────────────── */

  applySettings(settings: Settings): void {
    this.settings = settings;
    const { controls, graphics, game } = settings;

    setLanguage(game.language);

    this.keyboard.setBindings(controls.keys);
    this.input.steerSensitivity = controls.sensitivity;
    this.gamepad.deadzone = controls.deadzone;
    this.gyro.deadzone = controls.deadzone;
    this.gyro.range = controls.gyroRange;
    this.gyro.inverted = controls.gyroInverted;

    this.touchControls.applySettings({
      scheme: controls.scheme === 'dpad' ? 'dpad' : 'joystick',
      leftHanded: controls.leftHanded,
      autoAccelerate: controls.autoAccelerate,
    });
    this.touchControls.setVisible(isTouchScheme(controls.scheme));

    this.view.camera.far = graphics.viewDistance;
    this.view.setFog(graphics.viewDistance * 0.38, graphics.viewDistance * 0.95);
    this.view.setRenderScale(graphics.renderScale, this.stage.app.renderer);
    this.audio.applySettings(settings.audio);
    this.debug.setVisible(graphics.showFps);
    this.loop?.setFpsCap(graphics.fpsCap);

    this.resize(this.stage.width, this.stage.height);
  }

  private resize(width: number, height: number): void {
    if (width === 0 || height === 0) return;
    this.view.resize(width, height);
    this.hud.resize(width, height);
    this.touchControls.resize(width, height);
  }

  /* ───────────────────────────────── loop ────────────────────────────────── */

  private get paused(): boolean {
    return this.pausedByMenu || this.pausedBySystem;
  }

  private setMenuPaused(paused: boolean): void {
    this.pausedByMenu = paused;
    if (!paused) this.loop?.resync();
  }

  private setSystemPaused(paused: boolean): void {
    if (this.pausedBySystem === paused) return;
    this.pausedBySystem = paused;
    if (this.settings.audio.muteOnBlur) this.audio.setMuted(paused);
    if (paused && this.started && !this.flow.isOpen) this.pauseMenu.open();
    if (!paused) this.loop?.resync();
  }

  private onFixed = (dt: number): void => {
    if (this.paused) return;
    const tick = this.sim.tick;

    const player = this.inputs.get(this.playerId);
    if (player) copyInput(player, this.input.read(tick));

    for (const bot of this.bots) {
      const slot = this.inputs.get(bot.kartId);
      if (slot) copyInput(slot, bot.poll(tick, dt));
    }

    this.sim.step(dt, this.inputs);
    this.recordGhost();
    this.checkRaceOver(dt);
  };

  /** Grava a trajetória da volta corrente e guarda a da melhor volta. */
  private recordGhost(): void {
    const kart = this.sim.karts[this.playerId];
    const progress = this.sim.laps.progress[this.playerId];
    if (!kart || !progress || this.sim.countdown > 0) return;

    if (progress.lap !== this.lastLapIndex) {
      const samples = this.ghostRecorder.finish();
      const times = progress.lapTimes;
      const justClosed = times[times.length - 1];
      if (samples && justClosed !== undefined && justClosed <= progress.bestLap) {
        this.bestLapGhost = samples;
      }
      this.ghostRecorder.reset();
      this.lastLapIndex = progress.lap;
    }
    this.ghostRecorder.sample(kart, this.sim.time - progress.lapStartTime);
  }

  private checkRaceOver(dt: number): void {
    if (this.raceOver) return;
    const progress = this.sim.laps.progress[this.playerId];
    if (!progress) return;

    if (progress.finished) {
      if (this.resultsTimer < 0) this.resultsTimer = RESULTS_DELAY;
    } else if (this.everyoneElseFinished()) {
      // todos chegaram e o jogador não: começa a contar o prazo
      if (this.graceTimer < 0) this.graceTimer = GRACE_SECONDS;
      this.graceTimer -= dt;
      if (this.graceTimer <= 0) this.resultsTimer = 0;
    }

    if (this.resultsTimer < 0) return;
    this.resultsTimer -= dt;
    if (this.resultsTimer > 0) return;

    this.raceOver = true;
    this.finishRace();
  }

  private everyoneElseFinished(): boolean {
    if (this.sim.karts.length <= 1) return false;
    for (const kart of this.sim.karts) {
      if (kart.id === this.playerId) continue;
      if (!this.sim.laps.progress[kart.id]?.finished) return false;
    }
    return true;
  }

  private onRender = (alpha: number, dt: number): void => {
    this.input.sample(dt);
    this.view.update(this.paused ? 1 : alpha, dt, this.playerId);
    this.updateGhostView();
    this.view.renderScene(this.stage.app.renderer);

    const player = this.sim.karts[this.playerId];
    const progress = this.sim.laps.progress[this.playerId];
    if (player && progress) {
      this.hud.update(progress, player.speed, player.driftCharge, this.settings.game.laps);
      this.hud.setItem(player.heldItem?.kind ?? null, player.heldItem?.charges ?? 0);
      this.hud.setTime(this.sim.time);
      const left = this.sim.countdown;
      this.hud.setCountdown(left > 0 ? left : this.sim.time < GO_FLASH_SECONDS ? 0 : null);
      this.debug.update(this.loop.stats, player, dt);
      this.updateAudio(player);
    }
    this.consumeEvents();
  };

  private updateGhostView(): void {
    if (!this.ghostPlayer) return;
    const progress = this.sim.laps.progress[this.playerId];
    if (!progress || this.sim.countdown > 0) {
      this.view.updateGhost(null);
      return;
    }
    const lapTime = this.sim.time - progress.lapStartTime;
    this.view.updateGhost(this.ghostPlayer.poseAt(lapTime, this.ghostPose));
  }

  /** Traduz o estado contínuo do kart do jogador em som. */
  private updateAudio(player: NonNullable<SimWorld['karts'][number]>): void {
    if (this.paused) {
      this.audio.setLoopLevel('tire', 0);
      this.audio.setLoopLevel('offroad', 0);
      return;
    }
    this.audio.setEngine(Math.abs(player.speed) / TOP_SPEED, player.boosting);
    this.audio.setLoopLevel('tire', player.drifting ? 0.5 : 0);
    const offroad = player.surface === 'grass' || player.surface === 'sand';
    this.audio.setLoopLevel('offroad', offroad && Math.abs(player.speed) > 2 ? 0.45 : 0);
  }

  /** Eventos da simulação viram som. Partículas entram aqui depois. */
  private consumeEvents(): void {
    for (const event of this.sim.drainEvents(this.drained)) {
      const isPlayer = event.kartId === this.playerId;
      this.view.effects?.handleEvent(event, this.sim.karts[event.kartId]);
      switch (event.type) {
        case 'impact':
          this.audio.play('impact', (isPlayer ? 0.9 : 0.35) * event.strength);
          this.view.fireKartAnimation(event.kartId, 'hit');
          break;
        case 'spinout':
          this.audio.play('spinout', isPlayer ? 1 : 0.4);
          if (isPlayer) this.audio.duck(0.55);
          break;
        case 'boost':
          this.audio.play('boost', isPlayer ? 0.9 : 0.3, 1 + event.stage * 0.08);
          this.view.fireKartAnimation(event.kartId, 'boost');
          break;
        case 'lap':
          if (isPlayer) this.audio.play('lap', 0.8);
          break;
        case 'finish':
          if (isPlayer) {
            this.audio.play('go', 1);
            this.audio.duck(0.7, 0.2, 1.4);
          }
          break;
        case 'itemGet':
          if (isPlayer) this.audio.play('itemGet', 0.8);
          break;
        case 'itemUse':
          this.audio.play('itemUse', isPlayer ? 0.8 : 0.3);
          break;
        case 'shieldBreak':
          this.audio.play('impact', isPlayer ? 0.8 : 0.3);
          break;
        case 'slip':
          this.audio.play('impact', isPlayer ? 0.6 : 0.25, 0.7);
          break;
        case 'respawn':
          break;
      }
    }
    this.updateCountdownAudio();
  }

  private updateCountdownAudio(): void {
    const left = this.sim.countdown;
    const step = left > 0 ? Math.ceil(left) : 0;
    if (step === this.lastCountdownStep) return;
    if (!this.started || this.paused) {
      this.lastCountdownStep = step;
      return;
    }
    this.lastCountdownStep = step;
    if (step > 0) this.audio.play('beep', 0.7);
    else this.audio.play('go', 0.95);
  }
}
