/**
 * Controles virtuais para celular. Desenhados em Pixi (e não em DOM) para
 * escalarem junto com o canvas e respeitarem a área segura do aparelho.
 * O estado é lido pelo `TouchDevice`. Ver PLAN.md §8.2.
 */
import { Container, FederatedPointerEvent, Graphics, Point, Text, TextStyle } from 'pixi.js';
import { clamp } from '@/core/math';
import { UI_COLORS } from '@/data/colors';

export type TouchScheme = 'dpad' | 'joystick';

export interface TouchState {
  steer: number;
  throttle: number;
  brake: number;
  drift: boolean;
  item: boolean;
}

export interface TouchSettings {
  scheme: TouchScheme;
  /** Direção à direita e botões à esquerda. */
  leftHanded: boolean;
  /** Acelera sozinho — padrão no celular. */
  autoAccelerate: boolean;
}

export const DEFAULT_TOUCH_SETTINGS: TouchSettings = {
  scheme: 'joystick',
  leftHanded: false,
  autoAccelerate: true,
};

/** Raio, em pixels de referência, em que o joystick atinge esterço total. */
const STICK_RADIUS = 72;
const BUTTON_ALPHA = 0.3;
const BUTTON_ALPHA_DOWN = 0.62;

export class TouchControls {
  readonly container = new Container();
  readonly state: TouchState = { steer: 0, throttle: 0, brake: 0, drift: false, item: false };

  private settings: TouchSettings = { ...DEFAULT_TOUCH_SETTINGS };
  private width = 0;
  private height = 0;
  private scale = 1;

  private readonly steerZone = new Graphics();
  private readonly stickBase = new Graphics();
  private readonly stickKnob = new Graphics();
  private readonly leftButton: TouchButton;
  private readonly rightButton: TouchButton;
  private readonly accelButton: TouchButton;
  private readonly brakeButton: TouchButton;
  private readonly driftButton: TouchButton;
  private readonly itemButton: TouchButton;

  private stickPointer: number | null = null;
  private readonly stickOrigin = new Point();
  private readonly localPoint = new Point();

  constructor() {
    this.leftButton = new TouchButton('◀', () => this.setSteerButton(-1, true), () => this.setSteerButton(-1, false));
    this.rightButton = new TouchButton('▶', () => this.setSteerButton(1, true), () => this.setSteerButton(1, false));
    this.accelButton = new TouchButton('▲', () => { this.state.throttle = 1; }, () => { this.state.throttle = 0; });
    this.brakeButton = new TouchButton('▼', () => { this.state.brake = 1; }, () => { this.state.brake = 0; });
    this.driftButton = new TouchButton('DRIFT', () => { this.state.drift = true; }, () => { this.state.drift = false; }, UI_COLORS.accent);
    this.itemButton = new TouchButton('ITEM', () => { this.state.item = true; }, () => { this.state.item = false; }, UI_COLORS.good);

    this.steerZone.eventMode = 'static';
    this.steerZone.on('pointerdown', this.onStickDown);
    this.steerZone.on('globalpointermove', this.onStickMove);
    this.steerZone.on('pointerup', this.onStickUp);
    this.steerZone.on('pointerupoutside', this.onStickUp);
    this.steerZone.on('pointercancel', this.onStickUp);

    this.stickBase.alpha = 0;
    this.stickKnob.alpha = 0;

    this.container.addChild(
      this.steerZone,
      this.stickBase,
      this.stickKnob,
      this.leftButton.view,
      this.rightButton.view,
      this.accelButton.view,
      this.brakeButton.view,
      this.driftButton.view,
      this.itemButton.view,
    );
    this.container.visible = false;
  }

  applySettings(settings: TouchSettings): void {
    this.settings = { ...settings };
    this.releaseAll();
    this.layout();
  }

  setVisible(visible: boolean): void {
    this.container.visible = visible;
    if (!visible) this.releaseAll();
  }

  resize(width: number, height: number): void {
    this.width = width;
    this.height = height;
    this.scale = clamp(height / 720, 0.7, 1.5);
    this.layout();
  }

  private layout(): void {
    const { width: w, height: h, scale: s } = this;
    if (w === 0 || h === 0) return;

    const steerOnLeft = !this.settings.leftHanded;
    const margin = 28 * s;
    const bottom = h - margin;

    // a zona do joystick ocupa a metade inferior do lado da direção
    const zoneWidth = w * 0.46;
    this.steerZone.clear().rect(0, 0, zoneWidth, h * 0.72).fill({ color: 0xffffff, alpha: 0.001 });
    this.steerZone.position.set(steerOnLeft ? 0 : w - zoneWidth, h * 0.28);
    this.steerZone.visible = this.settings.scheme === 'joystick';

    const dpad = this.settings.scheme === 'dpad';
    this.leftButton.setVisible(dpad);
    this.rightButton.setVisible(dpad);
    const steerX = steerOnLeft ? margin : w - margin - 170 * s;
    this.leftButton.place(steerX + 42 * s, bottom - 44 * s, 42 * s, s);
    this.rightButton.place(steerX + 134 * s, bottom - 44 * s, 42 * s, s);

    const actionX = steerOnLeft ? w - margin : margin + 170 * s;
    const dir = steerOnLeft ? -1 : 1;
    this.accelButton.setVisible(!this.settings.autoAccelerate);
    this.accelButton.place(actionX + dir * 50 * s, bottom - 50 * s, 50 * s, s);
    this.brakeButton.place(actionX + dir * 142 * s, bottom - 36 * s, 36 * s, s);
    this.driftButton.place(actionX + dir * 58 * s, bottom - 150 * s, 44 * s, s);
    this.itemButton.place(actionX + dir * 150 * s, bottom - 132 * s, 38 * s, s);

    if (this.settings.autoAccelerate) this.state.throttle = 1;
  }

  private setSteerButton(direction: -1 | 1, pressed: boolean): void {
    const other = direction === -1 ? this.rightButton : this.leftButton;
    if (pressed) this.state.steer = direction;
    else this.state.steer = other.isDown ? -direction : 0;
  }

  private onStickDown = (event: FederatedPointerEvent): void => {
    if (this.stickPointer !== null) return;
    this.stickPointer = event.pointerId;
    this.container.toLocal(event.global, undefined, this.stickOrigin);
    this.drawStick(this.stickOrigin.x, this.stickOrigin.y, 0);
  };

  private onStickMove = (event: FederatedPointerEvent): void => {
    if (this.stickPointer !== event.pointerId) return;
    this.container.toLocal(event.global, undefined, this.localPoint);
    const radius = STICK_RADIUS * this.scale;
    const dx = this.localPoint.x - this.stickOrigin.x;
    this.state.steer = clamp(dx / radius, -1, 1);
    this.drawStick(this.stickOrigin.x, this.stickOrigin.y, this.state.steer * radius);
  };

  private onStickUp = (event: FederatedPointerEvent): void => {
    if (this.stickPointer !== event.pointerId) return;
    this.stickPointer = null;
    this.state.steer = 0;
    this.stickBase.alpha = 0;
    this.stickKnob.alpha = 0;
  };

  private drawStick(x: number, y: number, offset: number): void {
    const radius = STICK_RADIUS * this.scale;
    this.stickBase
      .clear()
      .circle(x, y, radius)
      .fill({ color: UI_COLORS.paper, alpha: 0.1 })
      .circle(x, y, radius)
      .stroke({ color: UI_COLORS.paper, alpha: 0.28, width: 2 * this.scale });
    this.stickKnob
      .clear()
      .circle(x + offset, y, radius * 0.42)
      .fill({ color: UI_COLORS.paper, alpha: 0.42 });
    this.stickBase.alpha = 1;
    this.stickKnob.alpha = 1;
  }

  private releaseAll(): void {
    this.state.steer = 0;
    this.state.brake = 0;
    this.state.drift = false;
    this.state.item = false;
    this.state.throttle = this.settings.autoAccelerate ? 1 : 0;
    this.stickPointer = null;
    this.stickBase.alpha = 0;
    this.stickKnob.alpha = 0;
    for (const button of [this.leftButton, this.rightButton, this.accelButton, this.brakeButton, this.driftButton, this.itemButton]) {
      button.forceUp();
    }
  }
}

class TouchButton {
  readonly view = new Container();
  isDown = false;

  private readonly shape = new Graphics();
  private readonly label: Text;
  private radius = 40;

  constructor(
    text: string,
    private readonly onDown: () => void,
    private readonly onUp: () => void,
    private readonly color: number = UI_COLORS.paper,
  ) {
    this.label = new Text({
      text,
      style: new TextStyle({
        fontFamily: 'system-ui, -apple-system, "Segoe UI", Roboto, sans-serif',
        fontSize: 16,
        fontWeight: '800',
        fill: UI_COLORS.paper,
      }),
    });
    this.label.anchor.set(0.5);
    this.view.addChild(this.shape, this.label);
    this.view.eventMode = 'static';
    this.view.on('pointerdown', this.press);
    this.view.on('pointerup', this.release);
    this.view.on('pointerupoutside', this.release);
    this.view.on('pointercancel', this.release);
  }

  place(x: number, y: number, radius: number, scale: number): void {
    this.radius = radius;
    this.view.position.set(x, y);
    this.label.style.fontSize = Math.max(11, 15 * scale);
    this.draw();
  }

  setVisible(visible: boolean): void {
    this.view.visible = visible;
    if (!visible) this.forceUp();
  }

  forceUp(): void {
    if (!this.isDown) return;
    this.isDown = false;
    this.onUp();
    this.draw();
  }

  private press = (): void => {
    if (this.isDown) return;
    this.isDown = true;
    this.onDown();
    this.draw();
  };

  private release = (): void => {
    if (!this.isDown) return;
    this.isDown = false;
    this.onUp();
    this.draw();
  };

  private draw(): void {
    this.shape
      .clear()
      .circle(0, 0, this.radius)
      .fill({ color: this.color, alpha: this.isDown ? BUTTON_ALPHA_DOWN : BUTTON_ALPHA })
      .circle(0, 0, this.radius)
      .stroke({ color: UI_COLORS.paper, alpha: 0.35, width: 2 });
    this.view.hitArea = { contains: (x: number, y: number) => x * x + y * y <= this.radius * this.radius * 1.4 };
  }
}
