/**
 * Giroscópio. É o controle com mais armadilhas do projeto (PLAN.md §8.2):
 *
 *  - iOS 13+ exige `requestPermission()` DENTRO de um gesto do usuário, por
 *    isso existe um botão nas configurações e não um pedido no boot;
 *  - exige HTTPS, inclusive no servidor de desenvolvimento;
 *  - em paisagem o eixo útil depende de `screen.orientation.angle`;
 *  - sem calibrar, quem joga deitado no sofá não consegue andar reto.
 */
import { clamp, deadzone } from '@/core/math';
import type { InputFrame } from '../InputFrame';
import type { InputDevice } from '../InputDevice';

type PermissionCapableEvent = typeof DeviceOrientationEvent & {
  requestPermission?: () => Promise<'granted' | 'denied' | 'prompt'>;
};

export type GyroStatus = 'idle' | 'pending' | 'granted' | 'denied' | 'unsupported' | 'silent';

/** Se nenhum evento chegar neste prazo após a permissão, o sensor não responde. */
const SILENCE_TIMEOUT = 1500;

export class GyroDevice implements InputDevice {
  readonly id = 'gyro';

  /** Ângulo, em graus, que corresponde a esterço total. */
  range = 28;
  /** Zona morta em fração do alcance. */
  deadzone = 0.08;
  /** Suavização passa-baixa: 0 = cru, perto de 1 = muito lento. */
  smoothing = 0.75;
  inverted = false;

  status: GyroStatus = 'idle';

  private zero = 0;
  private raw = 0;
  private steer = 0;
  private listening = false;
  private gotEvent = false;
  private silenceTimer = 0;
  private onStatusChange: ((status: GyroStatus) => void) | null = null;

  static get isSupported(): boolean {
    return typeof DeviceOrientationEvent !== 'undefined';
  }

  /** Verdadeiro quando o navegador exige um gesto para liberar o sensor (iOS). */
  static get needsPermission(): boolean {
    return typeof (DeviceOrientationEvent as PermissionCapableEvent)?.requestPermission === 'function';
  }

  observe(callback: (status: GyroStatus) => void): void {
    this.onStatusChange = callback;
  }

  enable(): void {
    // nada acontece até `requestAccess` — a permissão precisa de um gesto
  }

  disable(): void {
    this.stopListening();
  }

  /** Chame DENTRO de um clique/toque. Devolve o status final. */
  async requestAccess(): Promise<GyroStatus> {
    if (!GyroDevice.isSupported) return this.setStatus('unsupported');
    this.setStatus('pending');

    if (GyroDevice.needsPermission) {
      try {
        const result = await (DeviceOrientationEvent as PermissionCapableEvent).requestPermission!();
        if (result !== 'granted') return this.setStatus('denied');
      } catch {
        return this.setStatus('denied');
      }
    }

    this.startListening();
    return this.setStatus('granted');
  }

  /** Captura a inclinação atual como posição neutra. */
  calibrate(): void {
    this.zero = this.raw;
  }

  sample(dt: number): void {
    if (!this.listening) return;
    if (!this.gotEvent) {
      this.silenceTimer += dt * 1000;
      if (this.silenceTimer > SILENCE_TIMEOUT && this.status === 'granted') {
        this.setStatus('silent');
      }
      return;
    }
    const normalized = clamp((this.raw - this.zero) / this.range, -1, 1);
    const shaped = deadzone(normalized, this.deadzone) * (this.inverted ? -1 : 1);
    // passa-baixa independente de framerate
    const alpha = 1 - Math.pow(this.smoothing, dt * 60);
    this.steer += (shaped - this.steer) * alpha;
  }

  poll(out: InputFrame): void {
    if (this.status !== 'granted' || !this.gotEvent) return;
    out.steer += this.steer;
  }

  private startListening(): void {
    if (this.listening) return;
    window.addEventListener('deviceorientation', this.onOrientation);
    this.listening = true;
    this.gotEvent = false;
    this.silenceTimer = 0;
  }

  private stopListening(): void {
    if (!this.listening) return;
    window.removeEventListener('deviceorientation', this.onOrientation);
    this.listening = false;
    this.steer = 0;
  }

  private onOrientation = (event: DeviceOrientationEvent): void => {
    const beta = event.beta ?? 0;
    const gamma = event.gamma ?? 0;
    this.raw = tiltForOrientation(beta, gamma);
    if (!this.gotEvent) {
      this.gotEvent = true;
      // a primeira leitura vira o neutro, senão o jogo já começa virando
      this.zero = this.raw;
      if (this.status === 'silent') this.setStatus('granted');
    }
  };

  private setStatus(status: GyroStatus): GyroStatus {
    this.status = status;
    this.onStatusChange?.(status);
    return status;
  }
}

/**
 * Qual ângulo representa "girar o volante" depende de como o aparelho está
 * deitado. Em paisagem o eixo é `beta`, e o sinal inverte conforme o lado.
 */
export function tiltForOrientation(beta: number, gamma: number, angle = screenAngle()): number {
  switch (angle) {
    case 90:
      return beta;
    case -90:
    case 270:
      return -beta;
    case 180:
      return -gamma;
    default:
      return gamma;
  }
}

function screenAngle(): number {
  const orientation = globalThis.screen?.orientation;
  if (orientation && typeof orientation.angle === 'number') return orientation.angle;
  return 0;
}
