/**
 * Billboard genérico para objetos de cenário e de item: caixas, projéteis,
 * poças. Mesma projeção dos karts, com folha de sprites configurável.
 */
import { Rectangle, Sprite, Texture, Container } from 'pixi.js';
import { smoothstep, TAU } from '@/core/math';
import type { Mode7Camera, ProjectedPoint } from '../mode7/Mode7Camera';
import type { Billboard } from './Billboard';
import type { Pose } from './KartView';

/** Igual ao KartView: billboard rente à câmera vira mancha. */
const FADE_NEAR = 1.6;
const FADE_FAR = 4;

export interface PropOptions {
  readonly sheet: Texture;
  /** Quantos ângulos a folha cobre. 1 = sprite único, sem rotação. */
  readonly angles: number;
  readonly frameSize: number;
  readonly cols: number;
  /** Pixels por metro usados ao gerar o sprite. */
  readonly pxPerMeter: number;
  /** Onde está o contato com o chão dentro do quadro, normalizado. */
  readonly anchorY: number;
  /** Giro visual contínuo, em voltas por segundo (caixa de item). */
  readonly spin?: number;
}

export class PropView implements Billboard {
  readonly display = new Container();
  depth = Infinity;

  private readonly sprite: Sprite;
  private readonly frames: Texture[];
  private readonly options: PropOptions;
  private spinPhase = 0;
  private baseAlpha = 1;
  private currentFrame = -1;

  constructor(options: PropOptions) {
    this.options = options;
    this.frames = sliceFrames(options);
    this.sprite = new Sprite(this.frames[0]);
    this.sprite.anchor.set(0.5, options.anchorY);
    this.display.addChild(this.sprite);
    this.display.visible = false;
  }

  advance(dt: number): void {
    if (!this.options.spin) return;
    this.spinPhase = (this.spinPhase + this.options.spin * dt) % 1;
  }

  hide(): void {
    this.display.visible = false;
    this.depth = Infinity;
  }

  update(
    pose: Pose,
    camera: Mode7Camera,
    out: ProjectedPoint,
    screenWidth: number,
    screenHeight: number,
  ): void {
    if (!camera.project(pose.x, pose.y, pose.z, out) || out.sx < -0.4 || out.sx > 1.4) {
      this.hide();
      return;
    }

    if (this.options.angles > 1) {
      const relative = normalize(pose.angle - camera.angle + this.spinPhase * TAU);
      const frame = Math.round((relative / TAU) * this.options.angles) % this.options.angles;
      if (frame !== this.currentFrame) {
        this.currentFrame = frame;
        this.sprite.texture = this.frames[frame]!;
      }
    }

    const nearness = smoothstep(FADE_NEAR, FADE_FAR, out.depth);
    if (nearness <= 0.01) {
      this.hide();
      this.depth = out.depth;
      return;
    }

    this.display.visible = true;
    this.display.alpha = this.baseAlpha * nearness;
    this.sprite.x = out.sx * screenWidth;
    this.sprite.y = out.sy * screenHeight;
    this.sprite.scale.set(out.pxPerMeter / this.options.pxPerMeter);
    this.depth = out.depth;
  }

  setAlpha(alpha: number): void {
    this.baseAlpha = alpha;
  }
}

function normalize(angle: number): number {
  const x = angle % TAU;
  return x < 0 ? x + TAU : x;
}

function sliceFrames(options: PropOptions): Texture[] {
  if (options.angles <= 1) return [options.sheet];
  const frames: Texture[] = [];
  for (let i = 0; i < options.angles; i++) {
    const col = i % options.cols;
    const row = Math.floor(i / options.cols);
    frames.push(
      new Texture({
        source: options.sheet.source,
        frame: new Rectangle(
          col * options.frameSize,
          row * options.frameSize,
          options.frameSize,
          options.frameSize,
        ),
      }),
    );
  }
  return frames;
}
