/**
 * Contrato do `track.json`. Escrito pelo gerador em `tools/art/track.ts` e
 * lido pelo jogo. Todas as coordenadas são em METROS no plano do mundo
 * (X direita, Y baixo). Ver PLAN.md §6.1.
 */

/** Polilinha de colisão. `closed` indica se liga o último ponto ao primeiro. */
export interface TrackWall {
  readonly closed: boolean;
  /** Pares [x, y] achatados, em metros. */
  readonly points: readonly number[];
}

/** Ponto da linha ideal usado pela IA e pela ordenação de posição. */
export interface TrackWaypoint {
  readonly x: number;
  readonly y: number;
  /** Meia-largura utilizável da pista neste ponto, em metros. */
  readonly halfWidth: number;
  /** Velocidade sugerida para atravessar este ponto, em m/s. */
  readonly targetSpeed: number;
  /** Distância acumulada desde a largada, em metros. */
  readonly distance: number;
}

/** Segmento que precisa ser cruzado, na ordem, para a volta valer. */
export interface TrackCheckpoint {
  readonly ax: number;
  readonly ay: number;
  readonly bx: number;
  readonly by: number;
  /** Índice do waypoint mais próximo — usado para ordenar a corrida. */
  readonly waypoint: number;
}

/** Caixa de item parada na pista. */
export interface TrackItemBox {
  readonly x: number;
  readonly y: number;
}

export interface TrackSpawn {
  readonly x: number;
  readonly y: number;
  readonly angle: number;
}

export interface TrackData {
  readonly id: string;
  readonly name: string;
  readonly theme: string;
  /** Lado do mundo quadrado, em metros. A textura cobre exatamente esta área. */
  readonly sizeMeters: number;
  /** Lado da textura, em pixels. */
  readonly textureSize: number;
  /** Comprimento de uma volta, em metros. */
  readonly lapLength: number;
  readonly walls: readonly TrackWall[];
  readonly waypoints: readonly TrackWaypoint[];
  readonly checkpoints: readonly TrackCheckpoint[];
  readonly spawns: readonly TrackSpawn[];
  readonly itemBoxes: readonly TrackItemBox[];
}

/** Superfícies reconhecidas na máscara. A ordem define o id numérico. */
export const SURFACES = ['asphalt', 'grass', 'sand', 'water', 'wall', 'boost', 'ramp'] as const;
export type SurfaceName = (typeof SURFACES)[number];

export interface SurfaceProps {
  /** Multiplica a aderência lateral: quanto o kart "agarra" em vez de escorregar. */
  readonly grip: number;
  /** Multiplica a força do motor. */
  readonly traction: number;
  /** Multiplica o arrasto — acima de 1 o terreno freia. */
  readonly drag: number;
  /** Se verdadeiro, o kart é devolvido ao último checkpoint. */
  readonly respawn: boolean;
}

