/** Lê o estado dos controles virtuais desenhados por `TouchControls`. */
import type { TouchState } from '@/ui/TouchControls';
import type { InputFrame } from '../InputFrame';
import type { InputDevice } from '../InputDevice';

export class TouchDevice implements InputDevice {
  readonly id = 'touch';

  constructor(private readonly state: TouchState) {}

  enable(): void {
    // os eventos são dos próprios botões em Pixi
  }

  disable(): void {
    this.state.steer = 0;
    this.state.brake = 0;
    this.state.drift = false;
    this.state.item = false;
  }

  poll(out: InputFrame): void {
    out.steer += this.state.steer;
    out.throttle = Math.max(out.throttle, this.state.throttle);
    out.brake = Math.max(out.brake, this.state.brake);
    out.drift ||= this.state.drift;
    out.item ||= this.state.item;
  }
}
