/**
 * Painel da corrida: posição, volta, tempo e velocímetro. Ancorado nos cantos
 * reais da tela e escalado pela altura, para continuar legível no celular.
 * Ver PLAN.md §9.
 */
import gsap from 'gsap';
import { Container, Graphics, Rectangle, Sprite, Text, TextStyle, Texture } from 'pixi.js';
import { clamp } from '@/core/math';
import { UI_COLORS } from '@/data/colors';
import { ITEM_KINDS, type ItemKind } from '@/data/items';
import type { KartProgress } from '@/sim/systems/LapSystem';

/** Lado do quadro no sprite de ícones (tools/art/icons.ts). */
const ICON_SIZE = 64;

const PAD = 16;

function style(size: number, weight: '600' | '800' = '800', outlined = false): TextStyle {
  return new TextStyle({
    fontFamily: 'system-ui, -apple-system, "Segoe UI", Roboto, sans-serif',
    fontSize: size,
    fontWeight: weight,
    fill: UI_COLORS.paper,
    letterSpacing: 0.5,
    // o que é desenhado sobre o cenário precisa de contorno para ser legível
    ...(outlined
      ? {
          stroke: { color: UI_COLORS.ink, width: Math.max(4, size * 0.07), join: 'round' as const },
          dropShadow: { color: 0x000000, alpha: 0.45, blur: 6, distance: 3, angle: Math.PI / 2 },
        }
      : {}),
  });
}

export class Hud {
  readonly container = new Container();

  private readonly positionValue = new Text({ text: '1', style: style(46) });
  private readonly positionSuffix = new Text({ text: 'º', style: style(22, '600') });
  private readonly positionTotal = new Text({ text: '/8', style: style(18, '600') });

  private readonly lapLabel = new Text({ text: 'VOLTA', style: style(14, '600') });
  private readonly lapValue = new Text({ text: '1/3', style: style(32) });

  private readonly timeValue = new Text({ text: '0:00.00', style: style(22, '600') });

  private readonly speedValue = new Text({ text: '0', style: style(56) });
  private readonly speedUnit = new Text({ text: 'km/h', style: style(16, '600') });

  private readonly driftBar = new Graphics();
  private readonly panels = new Graphics();
  private readonly countdown = new Text({ text: '', style: style(96, '800', true) });
  private lastCountdownStep = -1;

  private readonly itemSlot = new Graphics();
  private readonly itemIcon = new Sprite();
  private readonly itemCharges = new Text({ text: '', style: style(16, '800', true) });
  private readonly iconFrames = new Map<ItemKind, Texture>();
  private currentItem: ItemKind | null = null;

  private width = 0;
  private height = 0;
  private scaleFactor = 1;

  constructor(totalLaps: number, gridSize: number, icons?: Texture) {
    if (icons) {
      ITEM_KINDS.forEach((kind, index) => {
        this.iconFrames.set(kind, new Texture({
          source: icons.source,
          frame: new Rectangle(index * ICON_SIZE, 0, ICON_SIZE, ICON_SIZE),
        }));
      });
    }
    this.itemIcon.anchor.set(0.5);
    this.itemCharges.anchor.set(1, 1);

    this.lapValue.text = `1/${totalLaps}`;
    this.positionTotal.text = `/${gridSize}`;

    this.positionSuffix.alpha = 0.75;
    this.positionTotal.alpha = 0.55;
    this.lapLabel.alpha = 0.6;
    this.speedUnit.alpha = 0.65;
    this.timeValue.alpha = 0.85;

    this.container.addChild(
      this.panels,
      this.positionValue,
      this.positionSuffix,
      this.positionTotal,
      this.lapLabel,
      this.lapValue,
      this.timeValue,
      this.speedValue,
      this.speedUnit,
      this.driftBar,
      this.itemSlot,
      this.itemIcon,
      this.itemCharges,
      this.countdown,
    );
    this.setItem(null, 0);
    this.countdown.anchor.set(0.5);
    this.countdown.visible = false;
  }

  resize(width: number, height: number): void {
    this.width = width;
    this.height = height;
    this.scaleFactor = clamp(height / 720, 0.68, 1.35);
    this.container.scale.set(this.scaleFactor);
    this.layout();
  }

  update(progress: KartProgress, speedMps: number, driftCharge: number, totalLaps: number): void {
    const kmh = Math.max(0, Math.round(speedMps * 3.6));
    if (this.speedValue.text !== String(kmh)) {
      this.speedValue.text = String(kmh);
      this.layoutSpeed();
    }

    const position = String(progress.position);
    if (this.positionValue.text !== position) {
      this.positionValue.text = position;
      this.layoutPosition();
    }

    const lap = `${clamp(progress.lap, 1, totalLaps)}/${totalLaps}`;
    if (this.lapValue.text !== lap) this.lapValue.text = lap;

    this.drawDrift(driftCharge);
  }

  /** Mostra o item em mãos. `null` esvazia o slot. */
  setItem(kind: ItemKind | null, charges: number): void {
    const texture = kind ? this.iconFrames.get(kind) : undefined;
    const visible = Boolean(texture);
    this.itemSlot.visible = visible;
    this.itemIcon.visible = visible;
    this.itemCharges.visible = visible && charges > 1;
    this.itemCharges.text = charges > 1 ? `×${charges}` : '';
    if (!texture) {
      this.currentItem = null;
      return;
    }
    if (kind !== this.currentItem) {
      this.currentItem = kind;
      this.itemIcon.texture = texture;
      gsap.fromTo(this.itemIcon.scale, { x: 0.3, y: 0.3 }, { x: 1, y: 1, duration: 0.3, ease: 'back.out(2)' });
    }
  }

  setTime(seconds: number): void {
    this.timeValue.text = formatTime(seconds);
  }

  /**
   * Contagem da largada. `null` esconde. O pop é feito com GSAP porque é um
   * evento discreto — o tipo de animação para o qual ele existe (PLAN.md §11).
   */
  setCountdown(secondsLeft: number | null): void {
    if (secondsLeft === null) {
      if (this.lastCountdownStep !== -1) {
        this.lastCountdownStep = -1;
        gsap.killTweensOf(this.countdown.scale);
        this.countdown.visible = false;
      }
      return;
    }

    const step = Math.ceil(secondsLeft);
    if (step === this.lastCountdownStep) return;
    this.lastCountdownStep = step;

    this.countdown.text = step > 0 ? String(step) : 'VALENDO!';
    this.countdown.style.fill = step > 0 ? UI_COLORS.paper : UI_COLORS.accent;
    this.countdown.visible = true;
    this.countdown.alpha = 1;
    this.countdown.scale.set(1.9);
    gsap.to(this.countdown.scale, { x: 1, y: 1, duration: 0.42, ease: 'back.out(2.4)' });
    if (step === 0) {
      gsap.to(this.countdown, { alpha: 0, duration: 0.5, delay: 0.45 });
    }
  }

  private layout(): void {
    const w = this.width / this.scaleFactor;
    const h = this.height / this.scaleFactor;

    this.panels.clear();
    this.panels
      .roundRect(PAD, PAD, 118, 74, 14)
      .fill({ color: UI_COLORS.ink, alpha: 0.42 })
      .roundRect(w - PAD - 132, PAD, 132, 74, 14)
      .fill({ color: UI_COLORS.ink, alpha: 0.42 })
      .roundRect(w - PAD - 160, h - PAD - 86, 160, 86, 14)
      .fill({ color: UI_COLORS.ink, alpha: 0.42 });

    this.countdown.position.set(w / 2, h * 0.36);

    const slot = 64;
    const slotX = w / 2 - slot / 2;
    this.itemSlot
      .clear()
      .roundRect(slotX, PAD, slot, slot, 14)
      .fill({ color: UI_COLORS.ink, alpha: 0.42 })
      .roundRect(slotX, PAD, slot, slot, 14)
      .stroke({ color: UI_COLORS.paper, alpha: 0.22, width: 2 });
    this.itemIcon.position.set(w / 2, PAD + slot / 2);
    this.itemCharges.position.set(slotX + slot - 6, PAD + slot - 2);

    this.positionValue.position.set(PAD + 18, PAD + 10);
    this.lapLabel.position.set(w - PAD - 116, PAD + 12);
    this.lapValue.position.set(w - PAD - 116, PAD + 30);
    this.timeValue.position.set(PAD + 4, h - PAD - 30);
    this.layoutPosition();
    this.layoutSpeed();
  }

  private layoutPosition(): void {
    const right = this.positionValue.x + this.positionValue.width + 2;
    this.positionSuffix.position.set(right, this.positionValue.y + 10);
    this.positionTotal.position.set(right, this.positionValue.y + 36);
  }

  private layoutSpeed(): void {
    const w = this.width / this.scaleFactor;
    const h = this.height / this.scaleFactor;
    this.speedValue.position.set(w - PAD - 20 - this.speedValue.width, h - PAD - 78);
    this.speedUnit.position.set(w - PAD - 20 - this.speedUnit.width, h - PAD - 28);
  }

  /** Barra de carga do mini-turbo — só aparece enquanto derrapa. */
  private drawDrift(charge: number): void {
    this.driftBar.clear();
    if (charge <= 0) return;
    const w = this.width / this.scaleFactor;
    const h = this.height / this.scaleFactor;
    const barWidth = 190;
    const x = (w - barWidth) / 2;
    const y = h - 46;
    const stage = charge >= 2.2 ? 2 : charge >= 1.4 ? 1 : 0;
    const color = [0x4fb8ff, 0xffa63d, 0xc06bff][stage]!;
    this.driftBar
      .roundRect(x, y, barWidth, 10, 5)
      .fill({ color: UI_COLORS.ink, alpha: 0.5 })
      .roundRect(x, y, barWidth * clamp(charge / 2.2, 0, 1), 10, 5)
      .fill({ color });
  }
}

export function formatTime(seconds: number): string {
  if (!Number.isFinite(seconds)) return '--:--';
  const minutes = Math.floor(seconds / 60);
  const rest = seconds - minutes * 60;
  return `${minutes}:${rest.toFixed(2).padStart(5, '0')}`;
}
