/**
 * Fantasma do contrarrelógio.
 *
 * Gravamos a TRAJETÓRIA, não os comandos. Re-simular comandos dependeria de a
 * física dar exatamente o mesmo resultado em qualquer aparelho, o que não é
 * garantido em JavaScript — e o fantasma sairia da pista. Interpolar posições
 * é imune a isso, custa ~20 KB por volta e não precisa de física nenhuma.
 * Ver PLAN.md §13.3.
 */
import { lerp, lerpAngle } from '@/core/math';
import type { Kart } from '@/sim/entities/Kart';

/** Intervalo entre amostras, em segundos. */
export const GHOST_INTERVAL = 0.05;

/** Cada amostra ocupa 4 números: x, y, ângulo, altura. */
const STRIDE = 4;

export interface GhostPose {
  x: number;
  y: number;
  angle: number;
  z: number;
}

export class GhostRecorder {
  private readonly samples: number[] = [];
  private nextSampleAt = 0;

  reset(): void {
    this.samples.length = 0;
    this.nextSampleAt = 0;
  }

  /** Chame a cada tick com o tempo da volta corrente. */
  sample(kart: Kart, lapTime: number): void {
    if (lapTime < this.nextSampleAt) return;
    this.nextSampleAt += GHOST_INTERVAL;
    this.samples.push(round(kart.x), round(kart.y), round(kart.angle), round(kart.z));
  }

  /** Fecha a gravação e devolve os dados; `null` se for curta demais. */
  finish(): number[] | null {
    if (this.samples.length < STRIDE * 10) return null;
    return [...this.samples];
  }
}

export class GhostPlayer {
  constructor(private readonly samples: readonly number[]) {}

  get duration(): number {
    return (this.samples.length / STRIDE - 1) * GHOST_INTERVAL;
  }

  get isEmpty(): boolean {
    return this.samples.length < STRIDE * 2;
  }

  /** Pose interpolada no instante pedido. Repete a volta em laço. */
  poseAt(time: number, out: GhostPose): GhostPose {
    const count = this.samples.length / STRIDE;
    const position = (time / GHOST_INTERVAL) % (count - 1);
    const index = Math.floor(position);
    const fraction = position - index;
    const a = index * STRIDE;
    const b = ((index + 1) % count) * STRIDE;

    out.x = lerp(this.samples[a]!, this.samples[b]!, fraction);
    out.y = lerp(this.samples[a + 1]!, this.samples[b + 1]!, fraction);
    out.angle = lerpAngle(this.samples[a + 2]!, this.samples[b + 2]!, fraction);
    out.z = lerp(this.samples[a + 3]!, this.samples[b + 3]!, fraction);
    return out;
  }
}

function round(value: number): number {
  return Math.round(value * 100) / 100;
}
