/**
 * Gamepad. Esterço analógico no stick esquerdo, acelerador e freio nos
 * gatilhos. A API exige polling, então a leitura acontece em `sample`.
 */
import { clamp, deadzone } from '@/core/math';
import type { InputFrame } from '../InputFrame';
import type { InputDevice } from '../InputDevice';

const DEADZONE = 0.14;
/** Gatilhos analógicos passam a contar a partir daqui. */
const TRIGGER_THRESHOLD = 0.08;

export class GamepadDevice implements InputDevice {
  readonly id = 'gamepad';

  /** Zona morta configurável pelo menu. */
  deadzone = DEADZONE;

  private connected = false;
  private steer = 0;
  private throttle = 0;
  private brake = 0;
  private drift = false;
  private item = false;

  enable(): void {
    window.addEventListener('gamepadconnected', this.onConnected);
    window.addEventListener('gamepaddisconnected', this.onDisconnected);
  }

  disable(): void {
    window.removeEventListener('gamepadconnected', this.onConnected);
    window.removeEventListener('gamepaddisconnected', this.onDisconnected);
    this.reset();
  }

  get isConnected(): boolean {
    return this.connected;
  }

  sample(): void {
    const pad = navigator.getGamepads?.().find((p) => p?.connected) ?? null;
    if (!pad) {
      if (this.connected) this.reset();
      return;
    }
    this.connected = true;

    const stick = pad.axes[0] ?? 0;
    const dpadLeft = pad.buttons[14]?.pressed ? 1 : 0;
    const dpadRight = pad.buttons[15]?.pressed ? 1 : 0;
    this.steer = clamp(deadzone(stick, this.deadzone) + dpadRight - dpadLeft, -1, 1);

    this.throttle = readTrigger(pad, 7, 0);
    this.brake = readTrigger(pad, 6, 1);
    this.drift = Boolean(pad.buttons[5]?.pressed || pad.buttons[1]?.pressed);
    this.item = Boolean(pad.buttons[2]?.pressed || pad.buttons[4]?.pressed);
  }

  poll(out: InputFrame): void {
    if (!this.connected) return;
    out.steer += this.steer;
    out.throttle = Math.max(out.throttle, this.throttle);
    out.brake = Math.max(out.brake, this.brake);
    out.drift ||= this.drift;
    out.item ||= this.item;
  }

  private reset(): void {
    this.connected = false;
    this.steer = 0;
    this.throttle = 0;
    this.brake = 0;
    this.drift = false;
    this.item = false;
  }

  private onConnected = (): void => {
    this.connected = true;
  };

  private onDisconnected = (): void => {
    this.reset();
  };
}

/** Lê um gatilho analógico, caindo para o botão correspondente se não houver eixo. */
function readTrigger(pad: Gamepad, triggerIndex: number, fallbackButton: number): number {
  const trigger = pad.buttons[triggerIndex];
  if (trigger) {
    const value = trigger.value || (trigger.pressed ? 1 : 0);
    if (value > TRIGGER_THRESHOLD) return clamp(value, 0, 1);
  }
  return pad.buttons[fallbackButton]?.pressed ? 1 : 0;
}
