/**
 * Voltas, checkpoints e posição na corrida.
 *
 * A volta só conta se TODOS os checkpoints forem cruzados na ordem — é isso
 * que impede atalhos. Ver PLAN.md §6.7.
 */
import type { TrackData } from '@/data/TrackData';
import type { Kart } from '../entities/Kart';

/** Movimento maior que isto num tick é teletransporte (respawn), não corrida. */
const MAX_STEP_DISTANCE = 20;

export interface KartProgress {
  /** 0 antes de cruzar a linha pela primeira vez. */
  lap: number;
  /** Índice do próximo checkpoint esperado. */
  nextCheckpoint: number;
  /** Total de checkpoints cruzados — cresce sempre, e ordena a corrida. */
  passed: number;
  /** Distância em metros até o próximo checkpoint, para desempatar. */
  distanceToNext: number;
  /** Colocação, 1 = primeiro. */
  position: number;
  finished: boolean;
  finishTime: number;
  lapStartTime: number;
  lapTimes: number[];
  bestLap: number;
}

function emptyProgress(): KartProgress {
  return {
    lap: 0,
    nextCheckpoint: 0,
    passed: 0,
    distanceToNext: 0,
    position: 1,
    finished: false,
    finishTime: 0,
    lapStartTime: 0,
    lapTimes: [],
    bestLap: Infinity,
  };
}

export class LapSystem {
  readonly progress: KartProgress[] = [];

  private readonly order: number[] = [];

  constructor(
    private readonly track: TrackData,
    private readonly totalLaps: number,
  ) {}

  register(kart: Kart): void {
    this.progress[kart.id] = emptyProgress();
    this.order.push(kart.id);
  }

  update(karts: readonly Kart[], time: number): void {
    for (const kart of karts) {
      const state = this.progress[kart.id];
      if (!state || state.finished) continue;
      this.checkCrossing(kart, state, time);
      this.updateDistance(kart, state);
    }
    this.updatePositions();
  }

  private checkCrossing(kart: Kart, state: KartProgress, time: number): void {
    const moved = Math.hypot(kart.x - kart.prevX, kart.y - kart.prevY);
    if (moved === 0 || moved > MAX_STEP_DISTANCE) return;

    const gate = this.track.checkpoints[state.nextCheckpoint];
    if (!gate) return;
    if (!segmentsCross(kart.prevX, kart.prevY, kart.x, kart.y, gate.ax, gate.ay, gate.bx, gate.by)) {
      return;
    }

    state.passed++;
    state.nextCheckpoint = (state.nextCheckpoint + 1) % this.track.checkpoints.length;

    // voltar ao checkpoint 0 significa que a volta fechou
    if (state.nextCheckpoint !== 1) return;

    if (state.lap > 0) {
      const lapTime = time - state.lapStartTime;
      state.lapTimes.push(lapTime);
      if (lapTime < state.bestLap) state.bestLap = lapTime;
    }
    state.lap++;
    state.lapStartTime = time;

    if (state.lap > this.totalLaps) {
      state.finished = true;
      state.finishTime = time;
    }
  }

  private updateDistance(kart: Kart, state: KartProgress): void {
    const gate = this.track.checkpoints[state.nextCheckpoint];
    if (!gate) return;
    const midX = (gate.ax + gate.bx) / 2;
    const midY = (gate.ay + gate.by) / 2;
    state.distanceToNext = Math.hypot(midX - kart.x, midY - kart.y);
  }

  /** Mais checkpoints cruzados vem primeiro; empate decide quem está mais perto do próximo. */
  private updatePositions(): void {
    this.order.sort((a, b) => {
      const pa = this.progress[a]!;
      const pb = this.progress[b]!;
      if (pa.finished !== pb.finished) return pa.finished ? -1 : 1;
      if (pa.finished && pb.finished) return pa.finishTime - pb.finishTime;
      if (pb.passed !== pa.passed) return pb.passed - pa.passed;
      return pa.distanceToNext - pb.distanceToNext;
    });
    for (let i = 0; i < this.order.length; i++) {
      this.progress[this.order[i]!]!.position = i + 1;
    }
  }
}

/** Dois segmentos se cruzam? Teste por orientação, sem divisões. */
function segmentsCross(
  ax: number, ay: number, bx: number, by: number,
  cx: number, cy: number, dx: number, dy: number,
): boolean {
  const d1 = cross(cx, cy, dx, dy, ax, ay);
  const d2 = cross(cx, cy, dx, dy, bx, by);
  const d3 = cross(ax, ay, bx, by, cx, cy);
  const d4 = cross(ax, ay, bx, by, dx, dy);
  return ((d1 > 0) !== (d2 > 0)) && ((d3 > 0) !== (d4 > 0));
}

function cross(ax: number, ay: number, bx: number, by: number, px: number, py: number): number {
  return (bx - ax) * (py - ay) - (by - ay) * (px - ax);
}
