/**
 * Um kart dentro da simulação. Guarda o corpo do Planck e o estado derivado
 * que o render consome. Nada aqui sabe o que é Pixi ou Spine.
 */
import type { Body } from 'planck';
import type { SurfaceName } from '@/data/TrackData';
import type { HeldItem } from './Item';

export const enum DriftSide {
  None = 0,
  Left = -1,
  Right = 1,
}

export class Kart {
  /** Estado do tick anterior, para o render interpolar. Ver PLAN.md §3. */
  prevX = 0;
  prevY = 0;
  prevAngle = 0;
  prevZ = 0;

  x = 0;
  y = 0;
  angle = 0;
  /** Altura acima do plano, em metros (rampas e saltos). */
  z = 0;
  vz = 0;

  /** Velocidade na direção em que o kart aponta, em m/s. Negativa = ré. */
  speed = 0;
  /** Velocidade perpendicular — o quanto está escorregando. */
  lateralSpeed = 0;

  driftSide: DriftSide = DriftSide.None;
  /** Carga do mini-turbo acumulada enquanto derrapa, em segundos. */
  driftCharge = 0;
  /** Estágio de carga alcançado: -1 nenhum, 0 azul, 1 laranja, 2 roxo. */
  driftStage = -1;

  /** Tempo de turbo restante, em segundos, e a força extra aplicada. */
  boostTime = 0;
  boostForce = 0;
  /** Estágio de turbo recém-liberado, aguardando virar evento. */
  pendingBoostStage: number | null = null;

  /** Tempo restante rodando sem controle, em segundos. */
  spinTime = 0;
  /** Sentido do giro durante a rodada. */
  spinDirection = 1;
  /** Enquanto maior que zero, novas batidas não derrubam de novo. */
  invulnerableTime = 0;
  /** Pedido de rodada vindo de fora da física (acerto de besouro). */
  pendingSpin = false;

  /** Item em mãos, se houver. */
  heldItem: HeldItem | null = null;
  /** Tempo até poder usar outro item, em segundos. */
  itemCooldown = 0;
  /** Bolha ativa: absorve um acerto. */
  shield = false;
  /** Tempo escorregando na lama, em segundos. */
  slipTime = 0;

  surface: SurfaceName = 'asphalt';
  /** Esterço já suavizado, -1 a 1 — o que a física realmente usa. */
  steer = 0;

  constructor(
    readonly id: number,
    readonly body: Body,
  ) {
    const p = body.getPosition();
    this.x = this.prevX = p.x;
    this.y = this.prevY = p.y;
    this.angle = this.prevAngle = body.getAngle();
  }

  get drifting(): boolean {
    return this.driftSide !== DriftSide.None;
  }

  /** Guarda o estado atual como "anterior" antes de um novo passo da física. */
  snapshotPrevious(): void {
    this.prevX = this.x;
    this.prevY = this.y;
    this.prevAngle = this.angle;
    this.prevZ = this.z;
  }

  /** Copia a pose do corpo do Planck para o estado de leitura. */
  syncFromBody(): void {
    const p = this.body.getPosition();
    this.x = p.x;
    this.y = p.y;
    this.angle = this.body.getAngle();
  }

  /** Reposiciona de forma dura — largada e respawn. */
  reset(x: number, y: number, angle: number): void {
    this.body.setTransform({ x, y }, angle);
    this.body.setLinearVelocity({ x: 0, y: 0 });
    this.body.setAngularVelocity(0);
    this.body.setAwake(true);
    this.x = this.prevX = x;
    this.y = this.prevY = y;
    this.angle = this.prevAngle = angle;
    this.z = this.prevZ = 0;
    this.vz = 0;
    this.speed = 0;
    this.lateralSpeed = 0;
    this.steer = 0;
    this.driftSide = DriftSide.None;
    this.driftCharge = 0;
    this.driftStage = -1;
    this.boostTime = 0;
    this.boostForce = 0;
    this.pendingBoostStage = null;
    this.spinTime = 0;
    this.invulnerableTime = 0;
    this.pendingSpin = false;
    this.heldItem = null;
    this.itemCooldown = 0;
    this.shield = false;
    this.slipTime = 0;
  }

  get boosting(): boolean {
    return this.boostTime > 0;
  }

  get spinning(): boolean {
    return this.spinTime > 0;
  }

  /** Liga o turbo, sem encurtar um turbo melhor que já esteja rodando. */
  applyBoost(duration: number, force: number): void {
    if (force >= this.boostForce) {
      this.boostForce = force;
      this.boostTime = Math.max(this.boostTime, duration);
    } else {
      this.boostTime = Math.max(this.boostTime, duration);
    }
  }
}
