/**
 * Painel reutilizável para todas as telas de fluxo (modo, personagem, pista,
 * resultado, classificação, pódio). Uma única sobreposição em DOM, reciclada:
 * seis telas quase iguais não merecem seis implementações.
 */
import { el, clear } from '../dom/elements';

export interface PanelAction {
  readonly label: string;
  readonly onClick: () => void;
  readonly primary?: boolean;
  readonly disabled?: boolean;
}

export interface PanelContent {
  readonly title: string;
  readonly subtitle?: string | undefined;
  readonly body?: (Node | string)[];
  readonly actions?: readonly PanelAction[];
}

export class Panel {
  readonly root: HTMLElement;

  private readonly titleEl = el('h2');
  private readonly subtitleEl = el('p', { class: 'hint' });
  private readonly bodyEl = el('div', { class: 'panel-body' });
  private readonly footEl = el('div', { class: 'panel-foot' });

  constructor() {
    this.root = el('div', { class: 'overlay', role: 'dialog', 'aria-modal': 'true' }, [
      el('div', { class: 'panel' }, [
        el('div', { class: 'panel-head' }, [el('div', {}, [this.titleEl, this.subtitleEl])]),
        this.bodyEl,
        this.footEl,
      ]),
    ]);
  }

  get isOpen(): boolean {
    return this.root.classList.contains('show');
  }

  show(content: PanelContent): void {
    this.titleEl.textContent = content.title;
    this.subtitleEl.textContent = content.subtitle ?? '';
    this.subtitleEl.style.display = content.subtitle ? '' : 'none';

    clear(this.bodyEl);
    for (const node of content.body ?? []) {
      this.bodyEl.append(typeof node === 'string' ? document.createTextNode(node) : node);
    }

    clear(this.footEl);
    for (const action of content.actions ?? []) {
      this.footEl.append(
        el('button', {
          class: action.primary ? 'btn btn-primary' : 'btn',
          text: action.label,
          disabled: action.disabled,
          onClick: action.onClick,
        }),
      );
    }

    this.root.classList.add('show');
    this.root.querySelector<HTMLButtonElement>('.btn-primary, .btn, button')?.focus();
  }

  hide(): void {
    this.root.classList.remove('show');
  }
}

/** Linha clicável de lista — usada para modo, personagem, pista e copa. */
export function choiceRow(
  label: string,
  hint: string | undefined,
  selected: boolean,
  onClick: () => void,
): HTMLElement {
  return el('div', { class: 'row' }, [
    el('div', {}, [
      el('span', { text: label }),
      hint ? el('p', { class: 'hint', text: hint }) : null,
    ]),
    el('div', { class: 'control' }, [
      el('button', {
        class: selected ? 'btn btn-primary' : 'btn',
        text: selected ? '✓' : '→',
        'aria-label': label,
        onClick,
      }),
    ]),
  ]);
}

/** Lista de valores — resultados, tempos, pontos. */
export function infoRow(label: string, value: string, highlight = false): HTMLElement {
  return el('div', { class: 'row' }, [
    el('span', { text: label }),
    el('span', {
      class: highlight ? 'value status ok' : 'value',
      text: value,
      style: 'min-width:auto',
    }),
  ]);
}
