/** Estado da sessão de jogo: modo escolhido, personagem, pista e copa. */
import type { CupDef } from '@/data/cups';
import type { Standing } from '@/meta/Scoring';

export type GameMode = 'quick' | 'cup' | 'timetrial';

export interface RaceRequest {
  readonly mode: GameMode;
  readonly trackId: string;
  readonly characterId: string;
  readonly opponents: number;
  /** Amostras do fantasma a exibir, se houver. */
  readonly ghost: number[] | null;
}

export interface RaceSummary {
  readonly position: number;
  readonly totalTime: number;
  readonly bestLap: number;
  readonly finished: boolean;
  readonly order: readonly { kartId: number; characterId: string; position: number }[];
}

export class Session {
  mode: GameMode = 'quick';
  characterId = 'capivara';
  trackId = 'track01';
  cup: CupDef | null = null;
  raceIndex = 0;
  standings: Standing[] = [];

  get isLastRace(): boolean {
    return this.cup !== null && this.raceIndex >= this.cup.tracks.length - 1;
  }

  get currentCupTrack(): string {
    return this.cup?.tracks[this.raceIndex] ?? this.trackId;
  }
}
