/**
 * Tradução. Só pt-BR está escrito na v1, mas nenhum texto nasce solto numa
 * tela: adicionar um idioma é traduzir esta lista. Ver PLAN.md §1.
 */
import { ptBR, type MessageKey } from './locales/pt-BR';

const LOCALES: Record<string, Partial<Record<MessageKey, string>>> = {
  'pt-BR': ptBR,
};

let current = 'pt-BR';

export function setLanguage(language: string): void {
  if (LOCALES[language]) current = language;
}

export function getLanguage(): string {
  return current;
}

export function availableLanguages(): string[] {
  return Object.keys(LOCALES);
}

/** Traduz; devolve a própria chave quando falta tradução, para o buraco aparecer. */
export function t(key: MessageKey, params?: Record<string, string | number>): string {
  const text = LOCALES[current]?.[key] ?? ptBR[key] ?? key;
  if (!params) return text;
  return text.replace(/\{(\w+)\}/g, (_, name: string) => String(params[name] ?? `{${name}}`));
}
