/** Pontuação do campeonato. Ver PLAN.md §13.2. */

/** Pontos por colocação, do primeiro ao oitavo. */
export const POINTS = [15, 12, 10, 8, 6, 4, 2, 1] as const;

export function pointsFor(position: number): number {
  return POINTS[position - 1] ?? 0;
}

export interface Standing {
  readonly kartId: number;
  readonly characterId: string;
  points: number;
  /** Colocação na corrida mais recente, para desempate. */
  lastPosition: number;
}

/**
 * Ordena a tabela: mais pontos primeiro; empate decide pela melhor colocação
 * na última corrida.
 */
export function sortStandings(standings: Standing[]): Standing[] {
  return [...standings].sort((a, b) => {
    if (b.points !== a.points) return b.points - a.points;
    return a.lastPosition - b.lastPosition;
  });
}
