/**
 * Batida forte: o kart roda, perde velocidade e fica um instante sem controle.
 *
 * O Planck já resolve o empurrão; o que decidimos aqui é QUANDO a batida é
 * forte o bastante para tirar o controle. O limiar é alto de propósito —
 * encostar de lado não pode punir, senão a disputa vira sorte. Ver PLAN.md §6.8.
 */
import { TAU } from '@/core/math';
import { COLLISION } from '@/data/tuning';
import type { SimEvent } from '../SimEvents';
import type { Kart } from '../entities/Kart';
import { DriftSide } from '../entities/Kart';

export interface PendingImpact {
  readonly a: Kart;
  readonly b: Kart | null;
  readonly impulse: number;
}

/** Aplica as batidas acumuladas no passo e produz os eventos. */
export function resolveImpacts(
  impacts: readonly PendingImpact[],
  events: SimEvent[],
): void {
  for (const impact of impacts) {
    if (impact.impulse < COLLISION.impactThreshold) continue;

    events.push({
      type: 'impact',
      kartId: impact.a.id,
      strength: Math.min(1, impact.impulse / (COLLISION.spinThreshold * 1.5)),
    });

    if (impact.impulse < COLLISION.spinThreshold) continue;

    // sem oponente é parede: bater no muro empurra, mas não roda
    if (!impact.b) continue;

    const victim = chooseVictim(impact.a, impact.b);
    if (!victim) continue;
    const aggressor = victim === impact.a ? impact.b : impact.a;

    startSpin(victim);
    events.push({ type: 'spinout', kartId: victim.id });

    // quem bateu também perde velocidade: senão empurrar vira a melhor tática
    scaleSpeed(aggressor, COLLISION.aggressorSpeedKeep);
  }
}

/** Roda o mais lento; empatados, nenhum dos dois roda. */
function chooseVictim(a: Kart, b: Kart): Kart | null {
  const eligibleA = a.invulnerableTime <= 0 && !a.spinning;
  const eligibleB = b.invulnerableTime <= 0 && !b.spinning;
  if (!eligibleA && !eligibleB) return null;
  if (!eligibleA) return b;
  if (!eligibleB) return a;

  const difference = Math.abs(a.speed) - Math.abs(b.speed);
  if (Math.abs(difference) < 1.5) return null;
  return difference < 0 ? a : b;
}

/** Roda o kart por ordem externa (acerto de item), ignorando limiares. */
export function forceSpin(kart: Kart): void {
  if (kart.spinning) return;
  startSpin(kart);
}

function startSpin(kart: Kart): void {
  kart.spinTime = COLLISION.spinDuration;
  kart.invulnerableTime = COLLISION.spinDuration + COLLISION.invulnerableDuration;
  kart.spinDirection = kart.lateralSpeed >= 0 ? 1 : -1;
  kart.driftSide = DriftSide.None;
  kart.driftCharge = 0;
  kart.driftStage = -1;
  kart.boostTime = 0;
  kart.boostForce = 0;
  scaleSpeed(kart, COLLISION.spinSpeedKeep);
}

function scaleSpeed(kart: Kart, factor: number): void {
  const velocity = kart.body.getLinearVelocity();
  kart.body.setLinearVelocity({ x: velocity.x * factor, y: velocity.y * factor });
}

/** Faz o kart girar enquanto está rodando. Chamado antes da física. */
export function updateSpin(kart: Kart, dt: number): void {
  if (kart.pendingSpin) {
    kart.pendingSpin = false;
    forceSpin(kart);
  }
  if (kart.invulnerableTime > 0) kart.invulnerableTime = Math.max(0, kart.invulnerableTime - dt);
  if (kart.spinTime <= 0) return;

  kart.spinTime = Math.max(0, kart.spinTime - dt);
  const rate = (COLLISION.spinTurns * TAU) / COLLISION.spinDuration;
  kart.body.setAngularVelocity(rate * kart.spinDirection);
}
