import '@/ui/dom/ui.css';
import { Game } from '@/app/Game';

const host = document.getElementById('game');
if (!host) throw new Error('#game não encontrado');

const game = new Game();
game.start(host).catch((error: unknown) => {
  console.error('falha ao iniciar o jogo', error);
  host.innerHTML =
    '<p style="color:#e8eef5;font:600 1rem system-ui;padding:2rem;text-align:center">' +
    'Não foi possível iniciar o jogo. Veja o console.</p>';
});
