/**
 * Decide o que emitir a partir do estado dos karts: fumaça de drift, faíscas
 * do mini-turbo, chama do boost, poeira fora da pista e estouros de batida.
 * Só leitura da simulação — nada aqui mexe no jogo.
 */
import { SURFACE_PROPS } from '@/data/TrackData';
import type { Kart } from '@/sim/entities/Kart';
import type { SimEvent } from '@/sim/SimEvents';
import type { Mode7Camera } from '../mode7/Mode7Camera';
import type { ParticleSystem } from './ParticleSystem';

/** Cores das faíscas por estágio de carga do drift. */
const DRIFT_COLORS = [0x4fb8ff, 0xffa63d, 0xc06bff] as const;
const SMOKE_COLOR = 0xdfe6ee;
const DUST_COLORS: Record<string, number> = {
  grass: 0x6f9b50,
  sand: 0xd8c08a,
  water: 0x8fc4e8,
};

/** Emissões por segundo. */
const DRIFT_RATE = 46;
const BOOST_RATE = 40;
const DUST_RATE = 26;
/** Além desta distância da câmera não vale emitir, em metros. */
const MAX_DISTANCE = 70;

export class RaceFx {
  /** Acumuladores por kart, para controlar a taxa sem depender do framerate. */
  private readonly driftAccum = new Map<number, number>();
  private readonly boostAccum = new Map<number, number>();
  private readonly dustAccum = new Map<number, number>();
  private readonly wasAirborne = new Map<number, boolean>();

  constructor(private readonly particles: ParticleSystem) {}

  update(dt: number, karts: readonly Kart[], camera: Mode7Camera): void {
    for (const kart of karts) {
      const dx = kart.x - camera.x;
      const dy = kart.y - camera.y;
      if (dx * dx + dy * dy > MAX_DISTANCE * MAX_DISTANCE) continue;

      this.emitDrift(kart, dt);
      this.emitBoost(kart, dt);
      this.emitDust(kart, dt);
      this.checkLanding(kart);
    }
  }

  /** Estouros ligados a eventos discretos da simulação. */
  handleEvent(event: SimEvent, kart: Kart | undefined): void {
    if (!kart) return;
    switch (event.type) {
      case 'impact':
        this.burst(kart, 10 + Math.round(event.strength * 14), 0xfff0c8, 'spark', 4.5);
        break;
      case 'spinout':
        this.burst(kart, 22, SMOKE_COLOR, 'smoke', 3.2);
        break;
      case 'slip':
        this.burst(kart, 16, DUST_COLORS.grass ?? 0x6f9b50, 'smoke', 2.4);
        break;
      case 'shieldBreak':
        this.burst(kart, 18, 0xbfe4ff, 'spark', 5);
        break;
      default:
        break;
    }
  }

  reset(): void {
    this.driftAccum.clear();
    this.boostAccum.clear();
    this.dustAccum.clear();
    this.wasAirborne.clear();
    this.particles.clear();
  }

  /* ───────────────────────────── emissores ───────────────────────────── */

  private emitDrift(kart: Kart, dt: number): void {
    if (!kart.drifting || kart.z > 0.05) {
      this.driftAccum.set(kart.id, 0);
      return;
    }
    const count = this.tick(this.driftAccum, kart.id, dt, DRIFT_RATE);
    if (count === 0) return;

    const stage = kart.driftStage;
    const color = stage >= 0 ? DRIFT_COLORS[Math.min(stage, 2)]! : SMOKE_COLOR;
    for (let i = 0; i < count; i++) {
      // alterna entre as duas rodas traseiras
      const side = i % 2 === 0 ? -1 : 1;
      const { x, y } = this.rearWheel(kart, side);
      const spread = (i % 3) * 0.4 - 0.4;
      if (stage >= 0) {
        this.particles.emit(x, y, 0.22, spread * 1.6, spread * 1.6, 1.4, {
          kind: 'spark', life: 0.32, size: 0.3, growth: 0.4, tint: color, alpha: 0.95,
        });
      }
      this.particles.emit(x, y, 0.12, spread, spread, 0.7, {
        kind: 'smoke', life: 0.55, size: 0.45, growth: 1.8, tint: SMOKE_COLOR, alpha: 0.42,
      });
    }
  }

  private emitBoost(kart: Kart, dt: number): void {
    if (!kart.boosting) {
      this.boostAccum.set(kart.id, 0);
      return;
    }
    const count = this.tick(this.boostAccum, kart.id, dt, BOOST_RATE);
    for (let i = 0; i < count; i++) {
      const backX = -Math.cos(kart.angle);
      const backY = -Math.sin(kart.angle);
      const x = kart.x + backX * 1.25;
      const y = kart.y + backY * 1.25;
      const jitter = ((i % 5) - 2) * 0.35;
      this.particles.emit(x, y, kart.z + 0.3, backX * 5 + jitter, backY * 5 + jitter, 1.2, {
        kind: 'spark', life: 0.28, size: 0.42, growth: 0.9, tint: 0xffb347, alpha: 0.9,
      });
    }
  }

  private emitDust(kart: Kart, dt: number): void {
    const dust = DUST_COLORS[kart.surface];
    const speed = Math.abs(kart.speed);
    if (!dust || speed < 3 || kart.z > 0.05) {
      this.dustAccum.set(kart.id, 0);
      return;
    }
    const count = this.tick(this.dustAccum, kart.id, dt, DUST_RATE * Math.min(1, speed / 10));
    for (let i = 0; i < count; i++) {
      const { x, y } = this.rearWheel(kart, i % 2 === 0 ? -1 : 1);
      this.particles.emit(x, y, 0.1, ((i % 3) - 1) * 0.8, ((i % 2) - 0.5) * 1.2, 1.1, {
        kind: 'smoke', life: 0.7, size: 0.5, growth: 2.2, tint: dust, alpha: 0.5,
      });
    }
    void SURFACE_PROPS;
  }

  /** Poeira ao tocar o chão depois de uma rampa. */
  private checkLanding(kart: Kart): void {
    const airborne = kart.z > 0.05;
    const previous = this.wasAirborne.get(kart.id) ?? false;
    this.wasAirborne.set(kart.id, airborne);
    if (previous && !airborne) this.burst(kart, 14, DUST_COLORS.sand ?? 0xd8c08a, 'smoke', 2.6);
  }

  private burst(kart: Kart, count: number, tint: number, kind: 'smoke' | 'spark', speed: number): void {
    for (let i = 0; i < count; i++) {
      const angle = (i / count) * Math.PI * 2;
      const magnitude = speed * (0.5 + ((i * 37) % 10) / 20);
      this.particles.emit(
        kart.x, kart.y, kart.z + 0.3,
        Math.cos(angle) * magnitude, Math.sin(angle) * magnitude, 1.6 + (i % 3) * 0.5,
        { kind, life: kind === 'spark' ? 0.4 : 0.7, size: kind === 'spark' ? 0.35 : 0.55,
          growth: 1.6, tint, alpha: 0.85 },
      );
    }
  }

  /** Converte uma taxa por segundo em uma contagem inteira neste quadro. */
  private tick(store: Map<number, number>, id: number, dt: number, rate: number): number {
    const accumulated = (store.get(id) ?? 0) + rate * dt;
    const count = Math.floor(accumulated);
    store.set(id, accumulated - count);
    return count;
  }

  /** Posição aproximada de uma roda traseira, em metros. */
  private rearWheel(kart: Kart, side: number): { x: number; y: number } {
    const forwardX = Math.cos(kart.angle);
    const forwardY = Math.sin(kart.angle);
    const rightX = -forwardY;
    const rightY = forwardX;
    return {
      x: kart.x - forwardX * 0.75 + rightX * side * 0.7,
      y: kart.y - forwardY * 0.75 + rightY * side * 0.7,
    };
  }
}
