/**
 * O chão. Um quad do tamanho da tela com o shader de perspectiva: cada pixel
 * descobre que ponto do mundo está vendo e lê a textura da pista ali.
 * Ver PLAN.md §5.2.
 */
import { Geometry, GlProgram, Mesh, Shader, Texture, UniformGroup } from 'pixi.js';
import type { Mode7Camera } from './Mode7Camera';
import { MODE7_FRAG, MODE7_VERT } from './shaders';

export interface Mode7Options {
  /** Lado do mundo quadrado coberto pela textura, em metros. */
  readonly trackSize: number;
  readonly fogColor: number;
  readonly outOfBoundsColor: number;
  /** Onde a névoa começa e termina, em metros. */
  readonly fogStart?: number;
  readonly fogEnd?: number;
  /** Textura de granulado ladrilhada sobre o chão. */
  readonly detail: Texture;
}

function rgbTriple(color: number, out: Float32Array): Float32Array {
  out[0] = ((color >> 16) & 0xff) / 255;
  out[1] = ((color >> 8) & 0xff) / 255;
  out[2] = (color & 0xff) / 255;
  return out;
}

export class Mode7Layer {
  readonly mesh: Mesh<Geometry, Shader>;

  private readonly geometry: Geometry;
  private readonly uniforms: UniformGroup<{
    uCamPos: { value: Float32Array; type: 'vec2<f32>' };
    uCamDir: { value: Float32Array; type: 'vec2<f32>' };
    uHeight: { value: number; type: 'f32' };
    uHorizon: { value: number; type: 'f32' };
    uK: { value: number; type: 'f32' };
    uAspect: { value: number; type: 'f32' };
    uTrackSize: { value: number; type: 'f32' };
    uFar: { value: number; type: 'f32' };
    uFogStart: { value: number; type: 'f32' };
    uFogEnd: { value: number; type: 'f32' };
    uFogColor: { value: Float32Array; type: 'vec3<f32>' };
    uOutColor: { value: Float32Array; type: 'vec3<f32>' };
    uDetailScale: { value: number; type: 'f32' };
    uDetailStrength: { value: number; type: 'f32' };
    uDetailFade: { value: number; type: 'f32' };
  }>;

  constructor(track: Texture, options: Mode7Options) {
    configureTrackTexture(track);
    configureDetailTexture(options.detail);

    this.geometry = new Geometry({
      attributes: {
        aPosition: new Float32Array([0, 0, 1, 0, 1, 1, 0, 1]),
        aUV: new Float32Array([0, 0, 1, 0, 1, 1, 0, 1]),
      },
      indexBuffer: new Uint32Array([0, 1, 2, 0, 2, 3]),
    });

    this.uniforms = new UniformGroup({
      uCamPos: { value: new Float32Array([0, 0]), type: 'vec2<f32>' },
      uCamDir: { value: new Float32Array([1, 0]), type: 'vec2<f32>' },
      uHeight: { value: 5.4, type: 'f32' },
      uHorizon: { value: 0.4, type: 'f32' },
      uK: { value: 0.55, type: 'f32' },
      uAspect: { value: 16 / 9, type: 'f32' },
      uTrackSize: { value: options.trackSize, type: 'f32' },
      uFar: { value: 260, type: 'f32' },
      uFogStart: { value: options.fogStart ?? 90, type: 'f32' },
      uFogEnd: { value: options.fogEnd ?? 240, type: 'f32' },
      uFogColor: { value: rgbTriple(options.fogColor, new Float32Array(3)), type: 'vec3<f32>' },
      uOutColor: {
        value: rgbTriple(options.outOfBoundsColor, new Float32Array(3)),
        type: 'vec3<f32>',
      },
      uDetailScale: { value: 1 / 3.5, type: 'f32' },
      uDetailStrength: { value: 0.9, type: 'f32' },
      uDetailFade: { value: 75, type: 'f32' },
    });

    const shader = new Shader({
      glProgram: GlProgram.from({
        vertex: MODE7_VERT,
        fragment: MODE7_FRAG,
        name: 'mode7',
        // sem isto o Pixi compila o fragment em mediump e a pista rasga
        preferredFragmentPrecision: 'highp',
      }),
      resources: {
        uTrack: track.source,
        uSampler: track.source.style,
        uDetail: options.detail.source,
        uDetailSampler: options.detail.source.style,
        mode7Uniforms: this.uniforms,
      },
    });

    this.mesh = new Mesh({ geometry: this.geometry, shader });
  }

  resize(width: number, height: number): void {
    const positions = this.geometry.getBuffer('aPosition');
    const data = positions.data as Float32Array;
    data[0] = 0; data[1] = 0;
    data[2] = width; data[3] = 0;
    data[4] = width; data[5] = height;
    data[6] = 0; data[7] = height;
    positions.update();
  }

  /** Copia o estado da câmera para os uniforms. Uma vez por quadro. */
  update(camera: Mode7Camera): void {
    const u = this.uniforms.uniforms;
    u.uCamPos[0] = camera.x;
    u.uCamPos[1] = camera.y;
    u.uCamDir[0] = Math.cos(camera.angle);
    u.uCamDir[1] = Math.sin(camera.angle);
    u.uHeight = camera.height;
    u.uHorizon = camera.horizon;
    u.uK = camera.k;
    u.uAspect = camera.aspect;
    u.uFar = camera.far;
    this.uniforms.update();
  }

  /** Permite à câmera e à UI saberem onde a névoa começa. */
  setFogRange(start: number, end: number): void {
    this.uniforms.uniforms.uFogStart = start;
    this.uniforms.uniforms.uFogEnd = end;
    this.uniforms.update();
  }

  destroy(): void {
    this.mesh.destroy({ children: true });
    this.geometry.destroy();
  }
}

/** O granulado precisa repetir indefinidamente sobre o plano. */
export function configureDetailTexture(texture: Texture): void {
  const source = texture.source;
  source.autoGenerateMipmaps = true;
  source.style.addressMode = 'repeat';
  source.style.scaleMode = 'linear';
  source.style.mipmapFilter = 'linear';
  source.style.update();
  source.update();
}

/**
 * Mipmaps são o que impede a pista distante de virar ruído. Como as derivadas
 * da projeção são contínuas, o `texture()` escolhe o nível certo sozinho.
 */
export function configureTrackTexture(texture: Texture): void {
  const source = texture.source;
  source.autoGenerateMipmaps = true;
  source.style.addressMode = 'clamp-to-edge';
  source.style.scaleMode = 'linear';
  source.style.mipmapFilter = 'linear';
  source.style.update();
  source.update();
}
