/**
 * Sequência de telas fora da corrida: modo → personagem → pista → corrida →
 * resultado → (copa) classificação → pódio. Tudo num painel reciclado.
 * Ver PLAN.md §13.
 */
import { CHARACTERS, characterById } from '@/data/characters';
import { CUPS, TRACK_IDS, TRACK_NAMES, cupById } from '@/data/cups';
import { t } from '@/i18n';
import {
  completeCup, loadChampionship, recordFor, rememberCharacter, saveChampionship,
} from '@/meta/Records';
import { pointsFor, sortStandings, type Standing } from '@/meta/Scoring';
import { formatTime } from '@/ui/Hud';
import { assetUrl } from './assets';
import { el } from '@/ui/dom/elements';
import { choiceRow, infoRow, Panel } from '@/ui/screens/Panel';
import { Session, type GameMode, type RaceRequest, type RaceSummary } from './Session';

export interface FlowCallbacks {
  readonly onStartRace: (request: RaceRequest) => void;
  readonly onPlaySound: (name: 'click' | 'back') => void;
}

export class Flow {
  readonly panel = new Panel();
  readonly session = new Session();

  constructor(private readonly callbacks: FlowCallbacks) {}

  get isOpen(): boolean {
    return this.panel.isOpen;
  }

  /* ──────────────────────────── escolha do modo ──────────────────────────── */

  showModeSelect(): void {
    const saved = loadChampionship();
    const modes: [GameMode, string, string][] = [
      ['quick', t('mode.quick'), t('mode.quick.hint')],
      ['cup', t('mode.cup'), t('mode.cup.hint')],
      ['timetrial', t('mode.timetrial'), t('mode.timetrial.hint')],
    ];

    this.panel.show({
      title: t('mode.title'),
      body: [
        ...modes.map(([mode, label, hint]) =>
          choiceRow(label, hint, false, () => {
            this.click();
            this.session.mode = mode;
            this.session.cup = null;
            this.showCharacterSelect();
          }),
        ),
        saved
          ? choiceRow(t('mode.continueCup'), cupById(saved.cupId).name, false, () => {
              this.click();
              this.resumeChampionship();
            })
          : null,
      ].filter(Boolean) as Node[],
    });
  }

  /* ───────────────────────── personagem e pista ──────────────────────────── */

  private showCharacterSelect(): void {
    const grid = el('div', { class: 'grid-characters' });
    const render = (): void => {
      grid.replaceChildren(
        ...CHARACTERS.map((character) =>
          el('button', {
            class: 'character-card',
            type: 'button',
            'aria-pressed': character.id === this.session.characterId,
            onClick: () => {
              this.click();
              this.session.characterId = character.id;
              render();
            },
          }, [
            el('span', {
              class: 'portrait',
              style: `background-image:url(${assetUrl(`karts/${character.id}.png`)})`,
            }),
            el('span', { text: character.name }),
          ]),
        ),
      );
    };
    render();

    this.panel.show({
      title: t('character.title'),
      body: [grid],
      actions: [
        { label: t('action.back'), onClick: () => { this.back(); this.showModeSelect(); } },
        {
          label: t('action.start'),
          primary: true,
          onClick: () => {
            this.click();
            rememberCharacter(this.session.characterId);
            if (this.session.mode === 'cup') this.showCupSelect();
            else this.showTrackSelect();
          },
        },
      ],
    });
  }

  private showTrackSelect(): void {
    this.panel.show({
      title: t('track.title'),
      body: TRACK_IDS.map((id) => {
        const record = recordFor(id);
        const best = Number.isFinite(record.bestLap)
          ? `${t('track.bestLap')}: ${formatTime(record.bestLap)}`
          : t('track.noRecord');
        return choiceRow(TRACK_NAMES[id] ?? id, best, id === this.session.trackId, () => {
          this.click();
          this.session.trackId = id;
          this.startRace();
        });
      }),
      actions: [{ label: t('action.back'), onClick: () => { this.back(); this.showCharacterSelect(); } }],
    });
  }

  private showCupSelect(): void {
    this.panel.show({
      title: t('cup.title'),
      body: CUPS.map((cup) =>
        choiceRow(
          cup.name,
          cup.tracks.map((id) => TRACK_NAMES[id] ?? id).join(' · '),
          false,
          () => {
            this.click();
            this.startChampionship(cup.id);
          },
        ),
      ),
      actions: [{ label: t('action.back'), onClick: () => { this.back(); this.showCharacterSelect(); } }],
    });
  }

  /* ─────────────────────────────── campeonato ────────────────────────────── */

  private startChampionship(cupId: string): void {
    const cup = cupById(cupId);
    this.session.cup = cup;
    this.session.raceIndex = 0;
    this.session.standings = [];
    this.persistChampionship();
    this.startRace();
  }

  private resumeChampionship(): void {
    const saved = loadChampionship();
    if (!saved) {
      this.showModeSelect();
      return;
    }
    this.session.mode = 'cup';
    this.session.cup = cupById(saved.cupId);
    this.session.raceIndex = saved.raceIndex;
    this.session.characterId = saved.characterId;
    this.session.standings = saved.standings;
    this.startRace();
  }

  private persistChampionship(): void {
    const { cup, raceIndex, characterId, standings } = this.session;
    if (!cup) return;
    saveChampionship({ cupId: cup.id, raceIndex, characterId, standings });
  }

  /* ──────────────────────────────── corrida ──────────────────────────────── */

  private startRace(): void {
    const { mode } = this.session;
    const trackId = mode === 'cup' ? this.session.currentCupTrack : this.session.trackId;
    const ghost = mode === 'timetrial' ? recordFor(trackId).ghost : null;

    this.panel.hide();
    this.callbacks.onStartRace({
      mode,
      trackId,
      characterId: this.session.characterId,
      opponents: mode === 'timetrial' ? 0 : 7,
      ghost,
    });
  }

  /** Chamado pelo jogo quando a corrida termina. */
  showResults(summary: RaceSummary, records: { newBestLap: boolean; newBestRace: boolean }): void {
    const { mode } = this.session;
    const body = [
      infoRow(t('results.position'), summary.finished ? `${summary.position}º` : t('results.dnf')),
      infoRow(t('results.time'), formatTime(summary.totalTime)),
      infoRow(
        t('results.bestLap'),
        Number.isFinite(summary.bestLap) ? formatTime(summary.bestLap) : '—',
        records.newBestLap,
      ),
      records.newBestLap || records.newBestRace
        ? el('p', { class: 'hint status ok', text: t('results.newRecord') })
        : null,
    ].filter(Boolean) as Node[];

    const actions = mode === 'cup'
      ? [{ label: t('action.continue'), primary: true, onClick: () => { this.click(); this.applyCupResult(summary); } }]
      : [
          { label: t('action.menu'), onClick: () => { this.back(); this.showModeSelect(); } },
          { label: t('action.again'), primary: true, onClick: () => { this.click(); this.startRace(); } },
        ];

    this.panel.show({ title: t('results.title'), body, actions });
  }

  private applyCupResult(summary: RaceSummary): void {
    const standings = new Map(this.session.standings.map((s) => [s.kartId, { ...s }]));
    for (const entry of summary.order) {
      const existing = standings.get(entry.kartId) ?? {
        kartId: entry.kartId,
        characterId: entry.characterId,
        points: 0,
        lastPosition: entry.position,
      };
      existing.points += pointsFor(entry.position);
      existing.lastPosition = entry.position;
      standings.set(entry.kartId, existing);
    }
    this.session.standings = [...standings.values()];
    this.showStandings();
  }

  private showStandings(): void {
    const cup = this.session.cup;
    if (!cup) {
      this.showModeSelect();
      return;
    }
    const sorted = sortStandings(this.session.standings);
    const list = el(
      'div',
      { class: 'standings-list' },
      sorted.map((standing) =>
        infoRow(
          characterById(standing.characterId).name,
          `${standing.points} ${t('standings.points')}`,
          standing.kartId === 0,
        ),
      ),
    );

    const last = this.session.isLastRace;
    this.panel.show({
      title: t('standings.title'),
      subtitle: t('standings.race', {
        current: this.session.raceIndex + 1,
        total: cup.tracks.length,
      }),
      body: [list],
      actions: [
        {
          label: last ? t('action.continue') : t('action.next'),
          primary: true,
          onClick: () => {
            this.click();
            if (last) {
              this.showPodium(sorted);
              return;
            }
            this.session.raceIndex++;
            this.persistChampionship();
            this.startRace();
          },
        },
      ],
    });
  }

  private showPodium(sorted: readonly Standing[]): void {
    const champion = sorted[0];
    const playerPosition = sorted.findIndex((s) => s.kartId === 0) + 1;
    if (this.session.cup) completeCup(this.session.cup.id, playerPosition);

    this.panel.show({
      title: t('podium.title'),
      subtitle: champion ? `${t('podium.champion')}: ${characterById(champion.characterId).name}` : undefined,
      body: sorted.slice(0, 3).map((standing, index) =>
        infoRow(
          `${index + 1}º ${characterById(standing.characterId).name}`,
          `${standing.points} ${t('standings.points')}`,
          standing.kartId === 0,
        ),
      ),
      actions: [
        {
          label: t('action.menu'),
          primary: true,
          onClick: () => {
            this.click();
            this.session.cup = null;
            this.showModeSelect();
          },
        },
      ],
    });
  }

  private click(): void {
    this.callbacks.onPlaySound('click');
  }

  private back(): void {
    this.callbacks.onPlaySound('back');
  }
}
