/** Telas de abertura e de pausa. */
import { t } from '@/i18n';
import { el } from '../dom/elements';

export class StartScreen {
  readonly root: HTMLElement;

  constructor(onPlay: () => void) {
    this.root = el('div', { class: 'overlay show' }, [
      el('div', { class: 'title-screen' }, [
        el('h1', { text: t('game.title') }),
        el('p', { text: t('game.subtitle') }),
        el('button', {
          class: 'btn btn-primary',
          text: t('action.play'),
          onClick: () => {
            this.hide();
            onPlay();
          },
        }),
      ]),
    ]);
  }

  hide(): void {
    this.root.classList.remove('show');
  }
}

export interface PauseMenuOptions {
  readonly onResume: () => void;
  readonly onSettings: () => void;
  readonly onRestart: () => void;
}

export class PauseMenu {
  readonly root: HTMLElement;

  constructor(options: PauseMenuOptions) {
    this.root = el('div', { class: 'overlay', role: 'dialog', 'aria-modal': 'true' }, [
      el('div', { class: 'panel' }, [
        el('div', { class: 'panel-head' }, [el('h2', { text: t('pause.title') })]),
        el('div', { class: 'panel-body' }, [
          el('div', { class: 'group' }, [
            menuButton(t('action.continue'), options.onResume, true),
            menuButton(t('action.settings'), options.onSettings),
            menuButton(t('action.restart'), options.onRestart),
          ]),
        ]),
      ]),
    ]);
  }

  get isOpen(): boolean {
    return this.root.classList.contains('show');
  }

  open(): void {
    this.root.classList.add('show');
    this.root.querySelector<HTMLButtonElement>('.btn-primary')?.focus();
  }

  close(): void {
    this.root.classList.remove('show');
  }
}

function menuButton(label: string, onClick: () => void, primary = false): HTMLElement {
  return el('div', { class: 'row' }, [
    el('button', {
      class: primary ? 'btn btn-primary' : 'btn',
      style: 'width:100%',
      text: label,
      onClick,
    }),
  ]);
}
