/**
 * Funde todos os devices ativos num único `InputFrame` por tick.
 * Ver PLAN.md §8.
 */
import { clamp } from '@/core/math';
import { emptyInput, type InputFrame } from './InputFrame';
import type { InputDevice } from './InputDevice';

export class InputManager {
  /** Multiplica o esterço final — ajustável no menu. */
  steerSensitivity = 1;

  private readonly devices: InputDevice[] = [];
  private readonly frame = emptyInput();

  add(device: InputDevice): void {
    this.devices.push(device);
    device.enable();
  }

  remove(device: InputDevice): void {
    const index = this.devices.indexOf(device);
    if (index >= 0) {
      this.devices.splice(index, 1);
      device.disable();
    }
  }

  get<T extends InputDevice>(id: string): T | undefined {
    return this.devices.find((d) => d.id === id) as T | undefined;
  }

  /** Devices que precisam ler sensores/gamepad fazem isso aqui. */
  sample(dt: number): void {
    for (const device of this.devices) device.sample?.(dt);
  }

  /** Quadro de entrada do tick. O objeto é reusado: copie se precisar guardar. */
  read(tick: number): InputFrame {
    const frame = this.frame;
    frame.tick = tick;
    frame.steer = 0;
    frame.throttle = 0;
    frame.brake = 0;
    frame.drift = false;
    frame.item = false;
    frame.respawn = false;

    for (const device of this.devices) device.poll(frame);

    frame.steer = clamp(frame.steer * this.steerSensitivity, -1, 1);
    frame.throttle = clamp(frame.throttle, 0, 1);
    frame.brake = clamp(frame.brake, 0, 1);
    return frame;
  }

  destroy(): void {
    for (const device of this.devices) device.disable();
    this.devices.length = 0;
  }
}
