/**
 * Saltos. O Box2D é 2D puro, então a altura é um eixo escalar integrado à mão:
 * o kart continua colidindo no plano enquanto `z` sobe. É o bastante para
 * rampas legíveis e custa quase nada. Ver PLAN.md §6.5.
 */
import { RAMP } from '@/data/tuning';
import type { Kart } from '../entities/Kart';

/** Põe o kart no ar. Chamado ao pisar numa rampa. */
export function launch(kart: Kart, power = RAMP.power): void {
  if (kart.z > 0.01) return;
  kart.vz = power;
}

/** Integra a altura e devolve `true` se acabou de aterrissar. */
export function updateAir(kart: Kart, dt: number): boolean {
  if (kart.z <= 0 && kart.vz <= 0) {
    kart.z = 0;
    kart.vz = 0;
    return false;
  }

  kart.vz -= RAMP.gravity * dt;
  kart.z += kart.vz * dt;

  if (kart.z > 0) return false;

  // aterrissou
  kart.z = 0;
  kart.vz = 0;
  return true;
}

export function isAirborne(kart: Kart): boolean {
  return kart.z > 0.01;
}
