/**
 * Desenha tudo que fica "em pé" sobre o chão, do mais distante para o mais
 * próximo. São poucos objetos, então uma ordenação simples por quadro resolve.
 */
import { Container } from 'pixi.js';
import type { Billboard } from './Billboard';

export class BillboardLayer {
  readonly container = new Container();

  private readonly views: Billboard[] = [];
  private readonly sorted: Billboard[] = [];

  add(view: Billboard): void {
    this.views.push(view);
    this.sorted.push(view);
    this.container.addChild(view.display);
  }

  /** Reordena por profundidade: quem está longe é desenhado primeiro. */
  sort(): void {
    this.sorted.sort((a, b) => b.depth - a.depth);
    for (let i = 0; i < this.sorted.length; i++) {
      this.container.setChildIndex(this.sorted[i]!.display, i);
    }
  }

  get all(): readonly Billboard[] {
    return this.views;
  }
}
