/**
 * Teclado. Entrega esterço digital (-1/0/1); a suavização para analógico
 * acontece no `DriveSystem`, para valer também para o D-pad virtual.
 */
import type { InputFrame } from '../InputFrame';
import { actionForKey, DEFAULT_KEY_BINDINGS, type KeyBindings } from '../Bindings';
import type { InputDevice } from '../InputDevice';

export class KeyboardDevice implements InputDevice {
  readonly id = 'keyboard';

  private bindings: KeyBindings = DEFAULT_KEY_BINDINGS;
  private readonly pressed = new Set<keyof KeyBindings>();
  private attached = false;

  setBindings(bindings: KeyBindings): void {
    this.bindings = bindings;
    this.pressed.clear();
  }

  enable(): void {
    if (this.attached) return;
    window.addEventListener('keydown', this.onKeyDown);
    window.addEventListener('keyup', this.onKeyUp);
    window.addEventListener('blur', this.onBlur);
    this.attached = true;
  }

  disable(): void {
    if (!this.attached) return;
    window.removeEventListener('keydown', this.onKeyDown);
    window.removeEventListener('keyup', this.onKeyUp);
    window.removeEventListener('blur', this.onBlur);
    this.pressed.clear();
    this.attached = false;
  }

  poll(out: InputFrame): void {
    const left = this.pressed.has('left') ? 1 : 0;
    const right = this.pressed.has('right') ? 1 : 0;
    out.steer += right - left;
    if (this.pressed.has('accelerate')) out.throttle = Math.max(out.throttle, 1);
    if (this.pressed.has('brake')) out.brake = Math.max(out.brake, 1);
    out.drift ||= this.pressed.has('drift');
    out.item ||= this.pressed.has('item');
    out.respawn ||= this.pressed.has('respawn');
  }

  /** Consome um toque único — usado por ações que não são "segurar". */
  consume(action: keyof KeyBindings): boolean {
    if (!this.pressed.has(action)) return false;
    this.pressed.delete(action);
    return true;
  }

  private onKeyDown = (event: KeyboardEvent): void => {
    const action = actionForKey(this.bindings, event.code);
    if (!action) return;
    event.preventDefault();
    this.pressed.add(action);
  };

  private onKeyUp = (event: KeyboardEvent): void => {
    const action = actionForKey(this.bindings, event.code);
    if (!action) return;
    event.preventDefault();
    this.pressed.delete(action);
  };

  private onBlur = (): void => {
    this.pressed.clear();
  };
}
