/**
 * Kart desenhado com Spine. Um billboard é visto de todos os lados, então cada
 * ângulo é uma SKIN; os ossos (inclinação, suspensão, cabeça) animam igual em
 * qualquer uma. Ver PLAN.md §2.4 e §12.
 *
 * `autoUpdate` fica desligado: quem dá o tempo ao Spine é o nosso loop, com o
 * dt do render — não o ticker do Pixi.
 */
import { MixBlend, type Spine, type TrackEntry } from '@esotericsoftware/spine-pixi-v8';
import { clamp, TAU } from '@/core/math';
import { SPINE_PX_PER_METER, spineSkinFor } from '@/data/spineKart';
import type { Kart } from '@/sim/entities/Kart';
import { DriftSide } from '@/sim/entities/Kart';
import type { Mode7Camera, ProjectedPoint } from '../mode7/Mode7Camera';
import type { Pose } from './KartView';

export class SpineKartView {
  readonly spine: Spine;

  private currentSkin = '';
  private poseEntry: TrackEntry | null = null;
  private posePlaying = '';
  private airPlaying = false;

  constructor(spine: Spine) {
    this.spine = spine;
    this.spine.autoUpdate = false;
    this.spine.state.setAnimation(0, 'idle', true);
    this.applySkin('angle0');
  }

  /** Atualiza pose, skin e animações. Devolve a profundidade projetada. */
  update(
    kart: Kart,
    pose: Pose,
    camera: Mode7Camera,
    out: ProjectedPoint,
    screenWidth: number,
    screenHeight: number,
    dt: number,
  ): boolean {
    if (!camera.project(pose.x, pose.y, pose.z, out) || out.sx < -0.35 || out.sx > 1.35) {
      this.spine.visible = false;
      return false;
    }

    const relative = normalizeTurns((pose.angle - camera.angle) / TAU);
    this.applySkin(spineSkinFor(relative));
    this.applyAnimations(kart);

    this.spine.visible = true;
    this.spine.position.set(out.sx * screenWidth, out.sy * screenHeight);
    this.spine.scale.set(out.pxPerMeter / SPINE_PX_PER_METER);
    this.spine.update(dt);
    return true;
  }

  setVisible(visible: boolean): void {
    this.spine.visible = visible;
  }

  /** Dispara uma animação de uma vez só (turbo, batida). */
  fire(name: 'boost' | 'hit'): void {
    this.spine.state.setAnimation(2, name, false);
  }

  private applySkin(name: string): void {
    if (name === this.currentSkin) return;
    this.currentSkin = name;
    this.spine.skeleton.setSkinByName(name);
    this.spine.skeleton.setSlotsToSetupPose();
  }

  /**
   * Esterço e drift entram como POSE na trilha 1, com peso proporcional ao
   * esterço — misturar é o que evita o kart saltar de uma pose para a outra.
   */
  private applyAnimations(kart: Kart): void {
    const drifting = kart.driftSide !== DriftSide.None;
    const toRight = drifting ? kart.driftSide === DriftSide.Right : kart.steer > 0;
    const wanted = drifting
      ? toRight ? 'drift_right' : 'drift_left'
      : toRight ? 'steer_right' : 'steer_left';

    const weight = drifting ? 1 : clamp(Math.abs(kart.steer), 0, 1);

    if (wanted !== this.posePlaying) {
      this.posePlaying = wanted;
      this.poseEntry = this.spine.state.setAnimation(1, wanted, true);
      this.poseEntry.mixBlend = MixBlend.replace;
    }
    if (this.poseEntry) this.poseEntry.alpha = weight;

    const airborne = kart.z > 0.05;
    if (airborne !== this.airPlaying) {
      this.airPlaying = airborne;
      if (airborne) this.spine.state.setAnimation(3, 'air', true);
      else this.spine.state.setEmptyAnimation(3, 0.18);
    }
  }
}

function normalizeTurns(turns: number): number {
  const x = turns % 1;
  return x < 0 ? x + 1 : x;
}
