/**
 * A cena da corrida: céu, chão em Mode 7 e billboards, nesta ordem.
 * Lê a simulação e nunca escreve nela. Ver PLAN.md §5.3.
 */
import { Container, RenderTexture, Sprite, type Renderer, type Texture } from 'pixi.js';
import { damp } from '@/core/math';
import { CAMERA } from '@/data/tuning';
import type { TrackBundle } from '@/app/assets';
import type { SimWorld } from '@/sim/World';
import { BillboardLayer } from './billboards/BillboardLayer';
import { ItemsView, type ItemTextures } from './billboards/ItemsView';
import { ParticleSystem, type ParticleTextures } from './fx/ParticleSystem';
import { RaceFx } from './fx/RaceFx';
import { KartView, type Pose } from './billboards/KartView';
import { SpineKartView } from './billboards/SpineKartView';
import { Mode7Camera, type ProjectedPoint } from './mode7/Mode7Camera';
import { Mode7Layer } from './mode7/Mode7Layer';
import { SkyLayer } from './mode7/SkyLayer';
import { emptyPose, poseAt } from './pose';

export class RaceView {
  /** O que o palco recebe. Pode ser a cena direta ou o sprite do alvo reduzido. */
  readonly container = new Container();
  readonly camera = new Mode7Camera();

  /** Cena do mundo — é ela que paga o custo por pixel do Mode 7. */
  private readonly scene = new Container();
  private readonly output = new Sprite();
  private target: RenderTexture | null = null;
  private renderScale = 1;
  private cssWidth = 1;
  private cssHeight = 1;

  private readonly sky: SkyLayer;
  private readonly ground: Mode7Layer;
  private readonly billboards = new BillboardLayer();
  /** Views dos karts, na ordem dos ids. */
  private readonly kartViews: KartView[] = [];
  private items: ItemsView | null = null;
  private particles: ParticleSystem | null = null;
  private fx: RaceFx | null = null;
  private readonly pose: Pose = emptyPose();
  private readonly projection: ProjectedPoint = { sx: 0, sy: 0, depth: 0, pxPerMeter: 0 };
  /** Kart semitransparente do contrarrelógio. */
  private ghostView: KartView | null = null;

  private width = 1;
  private height = 1;

  constructor(
    private readonly sim: SimWorld,
    track: TrackBundle,
    kartSheets: ReadonlyMap<string, Texture>,
    private readonly characterIds: readonly string[],
    detail: Texture,
  ) {
    this.camera.height = CAMERA.height;
    this.camera.horizon = CAMERA.horizon;
    this.camera.k = CAMERA.k;
    this.camera.near = CAMERA.near;
    this.camera.far = CAMERA.far;
    this.camera.trail = CAMERA.trail;

    this.sky = new SkyLayer(track.sky);
    this.ground = new Mode7Layer(track.texture, {
      trackSize: track.data.sizeMeters,
      fogColor: hexToNumber(themeFog(track)),
      outOfBoundsColor: hexToNumber(themeOut(track)),
      fogStart: CAMERA.fogStart,
      fogEnd: CAMERA.fogEnd,
      detail,
    });

    // as partículas entram ANTES dos billboards: a fumaça sai de trás do kart,
    // está mais longe da câmera, e precisa ser desenhada atrás dele
    this.scene.addChild(this.sky.sprite, this.ground.mesh);
    this.scene.addChild(this.billboards.container);
    this.container.addChild(this.scene);

    for (const id of this.characterIds) {
      const sheet = kartSheets.get(id);
      if (!sheet) throw new Error(`sprite sheet ausente: ${id}`);
      const view = new KartView(sheet);
      this.kartViews.push(view);
      this.billboards.add(view);
    }
  }

  resize(width: number, height: number): void {
    this.cssWidth = width;
    this.cssHeight = height;
    this.applyLayout();
  }

  /**
   * Reduz a resolução em que o cenário é desenhado, mantendo o HUD nítido.
   * É a alavanca de desempenho mais eficaz no celular: o shader do Mode 7
   * custa por pixel. Ver PLAN.md §9.
   */
  setRenderScale(scale: number, renderer: Renderer): void {
    const next = Math.min(1, Math.max(0.4, scale));
    if (next === this.renderScale) return;
    this.renderScale = next;
    this.renderer = renderer;
    this.applyLayout();
  }

  /** Desenha a cena no alvo reduzido. Sem redução, não faz nada. */
  renderScene(renderer: Renderer): void {
    if (!this.target) return;
    renderer.render({ container: this.scene, target: this.target, clear: true });
  }

  private renderer: Renderer | null = null;

  private applyLayout(): void {
    const width = Math.max(1, Math.round(this.cssWidth * this.renderScale));
    const height = Math.max(1, Math.round(this.cssHeight * this.renderScale));

    this.width = width;
    this.height = height;
    this.camera.resize(width, height);
    this.ground.resize(width, height);
    this.sky.resize(width, height, this.camera);

    this.container.removeChildren();
    if (this.renderScale === 1) {
      this.target?.destroy(true);
      this.target = null;
      this.scene.scale.set(1);
      this.scene.addChild(this.billboards.container);
    this.container.addChild(this.scene);
      return;
    }

    this.target?.destroy(true);
    this.target = RenderTexture.create({ width, height, resolution: 1, antialias: false });
    this.output.texture = this.target;
    this.output.scale.set(1 / this.renderScale);
    this.container.addChild(this.output);
    void this.renderer;
  }

  /**
   * Liga a versão em Spine dos karts. `make` devolve uma instância por
   * personagem; se faltar alguma, aquele kart segue como sprite.
   */
  enableSpine(make: (characterId: string) => SpineKartView | null): void {
    for (let i = 0; i < this.characterIds.length; i++) {
      const view = make(this.characterIds[i]!);
      if (view) this.kartViews[i]?.attachSpine(view);
    }
  }

  /** Liga as partículas de drift, turbo, poeira e batida. */
  enableFx(textures: ParticleTextures): RaceFx {
    const particles = new ParticleSystem(textures);
    this.particles = particles;
    this.fx = new RaceFx(particles);
    // entre o chão e os billboards
    this.scene.addChildAt(particles.container, 2);
    return this.fx;
  }

  get effects(): RaceFx | null {
    return this.fx;
  }

  /** Liga o desenho das caixas, besouros e poças. */
  enableItems(textures: ItemTextures, bubble?: Texture): void {
    this.items = new ItemsView(textures, this.billboards);
    if (bubble) for (const view of this.kartViews) view.attachBubble(bubble);
  }

  /** Dispara uma animação pontual no kart, quando houver Spine. */
  fireKartAnimation(kartId: number, name: 'boost' | 'hit'): void {
    this.kartViews[kartId]?.fire(name);
  }

  /** Liga o fantasma do contrarrelógio, usando o sprite do personagem. */
  enableGhost(sheet: Texture): void {
    if (this.ghostView) return;
    const view = new KartView(sheet);
    view.setBaseAlpha(0.42);
    this.ghostView = view;
    this.billboards.add(view);
  }

  /** Posiciona o fantasma; `null` o esconde. */
  updateGhost(pose: Pose | null): void {
    if (!this.ghostView) return;
    if (!pose) {
      this.ghostView.display.visible = false;
      this.ghostView.depth = Infinity;
      return;
    }
    this.ghostView.update(pose, this.camera, this.projection, this.width, this.height);
  }

  /** Ajusta onde a névoa começa e termina, em metros. */
  setFog(start: number, end: number): void {
    this.ground.setFogRange(start, end);
  }

  destroy(): void {
    this.target?.destroy(true);
    this.target = null;
    this.ground.destroy();
    this.container.destroy({ children: true });
  }

  /** Reposiciona a câmera sem suavizar — largada, respawn, troca de câmera. */
  snapCamera(): void {
    const kart = this.sim.karts[0];
    if (!kart) return;
    this.camera.follow(kart.x, kart.y, kart.angle, 0, true);
  }

  update(alpha: number, dt: number, followKartId: number): void {
    const target = this.sim.karts[followKartId];
    if (target) {
      poseAt(target, alpha, this.pose);
      this.camera.follow(this.pose.x, this.pose.y, this.pose.angle, dt);
      // o campo de visão abre no turbo: é daí que vem a sensação de arrancada
      const wanted = target.boosting ? CAMERA.k * CAMERA.boostZoom : CAMERA.k;
      this.camera.k = damp(this.camera.k, wanted, 7, dt);
    }

    this.ground.update(this.camera);
    this.sky.update(this.camera);

    for (let i = 0; i < this.sim.karts.length && i < this.kartViews.length; i++) {
      const kart = this.sim.karts[i]!;
      poseAt(kart, alpha, this.pose);
      const view = this.kartViews[i]!;
      view.setShield(kart.shield);
      view.update(this.pose, this.camera, this.projection, this.width, this.height, kart, dt);
    }

    this.items?.update(this.sim.items, this.camera, this.projection, this.width, this.height, dt);
    this.billboards.sort();

    if (this.fx && this.particles) {
      this.fx.update(dt, this.sim.karts, this.camera);
      this.particles.update(dt, this.camera, this.width, this.height);
    }
  }
}

/** Cores do tema vêm do JSON da pista; por enquanto derivadas do nome. */
function themeFog(track: TrackBundle): string {
  return THEME_FOG[track.data.theme] ?? '#cfe9f7';
}

function themeOut(track: TrackBundle): string {
  return THEME_OUT[track.data.theme] ?? '#2e86c1';
}

const THEME_FOG: Record<string, string> = {
  orla: '#cfe9f7',
  feira: '#2a2a4a',
  vulcao: '#8a3a26',
};

const THEME_OUT: Record<string, string> = {
  orla: '#2e86c1',
  feira: '#0f1120',
  vulcao: '#e2511a',
};

function hexToNumber(hex: string): number {
  return parseInt(hex.replace('#', ''), 16);
}
