/**
 * Shader do Mode 7. O fragment shader faz, por pixel, a MESMA inversa de
 * perspectiva que `Mode7Camera.unproject` — ver PLAN.md §5.2.
 *
 * `precision highp float` é obrigatório: o padrão do Pixi para fragment é
 * mediump, e com mediump a divisão `k*h/dy` perde precisão perto do horizonte,
 * rasgando a pista em faixas.
 */

export const MODE7_VERT = /* glsl */ `#version 300 es
precision highp float;

in vec2 aPosition;
in vec2 aUV;

out vec2 vUV;

uniform mat3 uProjectionMatrix;
uniform mat3 uWorldTransformMatrix;
uniform mat3 uTransformMatrix;

void main() {
  mat3 mvp = uProjectionMatrix * uWorldTransformMatrix * uTransformMatrix;
  gl_Position = vec4((mvp * vec3(aPosition, 1.0)).xy, 0.0, 1.0);
  vUV = aUV;
}
`;

export const MODE7_FRAG = /* glsl */ `#version 300 es
precision highp float;

in vec2 vUV;
out vec4 finalColor;

uniform sampler2D uTrack;
uniform sampler2D uDetail;

uniform vec2 uCamPos;      // metros
uniform vec2 uCamDir;      // (cos a, sin a)
uniform float uHeight;     // altura da câmera, metros
uniform float uHorizon;    // linha do horizonte, 0..1 na tela
uniform float uK;          // escala focal
uniform float uAspect;     // largura / altura
uniform float uTrackSize;  // lado do mundo, metros
uniform float uFar;
uniform float uFogStart;
uniform float uFogEnd;
uniform vec3 uFogColor;
uniform vec3 uOutColor;    // além dos limites do mapa
uniform float uDetailScale;    // ladrilhos por metro
uniform float uDetailStrength;
uniform float uDetailFade;     // distância em que o detalhe some, em metros

void main() {
  float dy = vUV.y - uHorizon;

  // acima do horizonte o chão não existe: quem pinta ali é a camada de céu
  if (dy <= 0.0001) {
    finalColor = vec4(uFogColor, 1.0);
    return;
  }

  float depth = (uK * uHeight) / dy;
  if (depth > uFar) {
    finalColor = vec4(uFogColor, 1.0);
    return;
  }

  float side = ((vUV.x - 0.5) * uAspect * depth) / uK;

  vec2 fwd = uCamDir;
  vec2 rgt = vec2(-uCamDir.y, uCamDir.x);
  vec2 world = uCamPos + fwd * depth + rgt * side;

  vec2 uv = world / uTrackSize;
  vec3 color;
  if (uv.x < 0.0 || uv.y < 0.0 || uv.x > 1.0 || uv.y > 1.0) {
    color = uOutColor;
  } else {
    color = texture(uTrack, uv).rgb;
  }

  // granulado em escala de mundo: o mapa tem ~10 px/m e de perto fica chapado
  float detail = texture(uDetail, world * uDetailScale).r;
  float nearness = 1.0 - smoothstep(0.0, uDetailFade, depth);
  color *= mix(1.0, 0.84 + detail * 0.32, uDetailStrength * nearness);

  float fog = smoothstep(uFogStart, uFogEnd, depth);
  finalColor = vec4(mix(color, uFogColor, fog), 1.0);
}
`;
