/**
 * Partículas em espaço de MUNDO, projetadas pela mesma câmera do Mode 7 —
 * é isso que faz a fumaça ficar grudada na pista em vez de flutuar na tela.
 *
 * Pool fixo, sem alocação durante a corrida. Ver PLAN.md §5.3.
 */
import { Container, Sprite, type Texture } from 'pixi.js';
import { smoothstep } from '@/core/math';
import type { Mode7Camera, ProjectedPoint } from '../mode7/Mode7Camera';

export interface ParticleTextures {
  readonly smoke: Texture;
  readonly spark: Texture;
}

export type ParticleKind = 'smoke' | 'spark';

interface Particle {
  x: number;
  y: number;
  z: number;
  vx: number;
  vy: number;
  vz: number;
  life: number;
  maxLife: number;
  size: number;
  growth: number;
  tint: number;
  alpha: number;
  kind: ParticleKind;
  active: boolean;
}

/** Teto de partículas vivas. Acima disso as mais antigas são recicladas. */
const MAX_PARTICLES = 220;
/** Pixels por metro do sprite de partícula (64 px cobrindo 1 m). */
const PX_PER_METER = 64;
/**
 * Partícula mais perto que isto some. A fumaça fica para trás e a câmera passa
 * por dentro dela: sem a atenuação, a escala explode e vira uma barra na tela.
 */
const FADE_NEAR = 2.5;
const FADE_FAR = 7;

export interface EmitOptions {
  readonly kind?: ParticleKind;
  readonly life?: number;
  readonly size?: number;
  readonly growth?: number;
  readonly tint?: number;
  readonly alpha?: number;
  readonly drag?: number;
}

export class ParticleSystem {
  readonly container = new Container();

  private readonly particles: Particle[] = [];
  private readonly sprites: Sprite[] = [];
  private readonly projection: ProjectedPoint = { sx: 0, sy: 0, depth: 0, pxPerMeter: 0 };
  private next = 0;

  constructor(private readonly textures: ParticleTextures) {
    for (let i = 0; i < MAX_PARTICLES; i++) {
      const sprite = new Sprite(textures.smoke);
      sprite.anchor.set(0.5);
      sprite.visible = false;
      sprite.blendMode = 'normal';
      this.sprites.push(sprite);
      this.container.addChild(sprite);
      this.particles.push({
        x: 0, y: 0, z: 0, vx: 0, vy: 0, vz: 0,
        life: 0, maxLife: 1, size: 1, growth: 0,
        tint: 0xffffff, alpha: 1, kind: 'smoke', active: false,
      });
    }
  }

  /** Solta uma partícula. Posição e velocidade em metros. */
  emit(
    x: number, y: number, z: number,
    vx: number, vy: number, vz: number,
    options: EmitOptions = {},
  ): void {
    const index = this.findSlot();
    const particle = this.particles[index]!;
    particle.x = x;
    particle.y = y;
    particle.z = z;
    particle.vx = vx;
    particle.vy = vy;
    particle.vz = vz;
    particle.maxLife = options.life ?? 0.6;
    particle.life = particle.maxLife;
    particle.size = options.size ?? 0.6;
    particle.growth = options.growth ?? 1.2;
    particle.tint = options.tint ?? 0xffffff;
    particle.alpha = options.alpha ?? 0.7;
    particle.kind = options.kind ?? 'smoke';
    particle.active = true;

    const sprite = this.sprites[index]!;
    sprite.texture = particle.kind === 'spark' ? this.textures.spark : this.textures.smoke;
    sprite.tint = particle.tint;
    sprite.blendMode = particle.kind === 'spark' ? 'add' : 'normal';
  }

  /** Integra e projeta. Chame uma vez por quadro, depois da câmera. */
  update(dt: number, camera: Mode7Camera, width: number, height: number): void {
    for (let i = 0; i < this.particles.length; i++) {
      const particle = this.particles[i]!;
      const sprite = this.sprites[i]!;
      if (!particle.active) {
        if (sprite.visible) sprite.visible = false;
        continue;
      }

      particle.life -= dt;
      if (particle.life <= 0) {
        particle.active = false;
        sprite.visible = false;
        continue;
      }

      particle.x += particle.vx * dt;
      particle.y += particle.vy * dt;
      particle.z = Math.max(0, particle.z + particle.vz * dt);
      // arrasto do ar: a fumaça perde velocidade rápido
      const damp = Math.exp(-3.5 * dt);
      particle.vx *= damp;
      particle.vy *= damp;
      particle.vz = particle.vz * damp - 0.6 * dt;

      if (!camera.project(particle.x, particle.y, particle.z, this.projection)) {
        sprite.visible = false;
        continue;
      }
      if (this.projection.sx < -0.3 || this.projection.sx > 1.3) {
        sprite.visible = false;
        continue;
      }

      const nearness = smoothstep(FADE_NEAR, FADE_FAR, this.projection.depth);
      if (nearness <= 0.01) {
        sprite.visible = false;
        continue;
      }

      const fraction = particle.life / particle.maxLife;
      const meters = particle.size * (1 + (1 - fraction) * particle.growth);
      sprite.visible = true;
      sprite.x = this.projection.sx * width;
      sprite.y = this.projection.sy * height;
      sprite.scale.set((this.projection.pxPerMeter * meters) / PX_PER_METER);
      sprite.alpha = particle.alpha * fraction * nearness;
    }
  }

  clear(): void {
    for (let i = 0; i < this.particles.length; i++) {
      this.particles[i]!.active = false;
      this.sprites[i]!.visible = false;
    }
  }

  /** Procura um slot livre; se não houver, recicla em rodízio. */
  private findSlot(): number {
    for (let i = 0; i < this.particles.length; i++) {
      const index = (this.next + i) % this.particles.length;
      if (!this.particles[index]!.active) {
        this.next = (index + 1) % this.particles.length;
        return index;
      }
    }
    const index = this.next;
    this.next = (this.next + 1) % this.particles.length;
    return index;
  }
}
