/** Copas: sequências ordenadas de pistas. Ver PLAN.md §13.2. */
export interface CupDef {
  readonly id: string;
  readonly name: string;
  readonly tracks: readonly string[];
}

export const CUPS: readonly CupDef[] = [
  { id: 'copa-litoral', name: 'Copa Litoral', tracks: ['track01', 'track02', 'track03'] },
];

export function cupById(id: string): CupDef {
  return CUPS.find((c) => c.id === id) ?? CUPS[0]!;
}

/** Pistas avulsas, na ordem em que aparecem na seleção. */
export const TRACK_IDS = ['track01', 'track02', 'track03'] as const;
export const TRACK_NAMES: Record<string, string> = {
  track01: 'Orla da Vila',
  track02: 'Feira Noturna',
  track03: 'Serra do Vulcão',
};
